PROCEDURE validate_parameters(
            p_order_number                 IN NUMBER      DEFAULT NULL
           ,p_header_id                    IN NUMBER      DEFAULT NULL
           ,p_line_id                      IN NUMBER      DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'N'
           ,p_print_wf                     IN VARCHAR2    DEFAULT 'Y'
           ,p_print_purch                  IN VARCHAR2    DEFAULT 'Y'
           ,p_print_mfg                    IN VARCHAR2    DEFAULT 'Y'
           ,p_print_inv                    IN VARCHAR2    DEFAULT 'Y'
           ,p_print_ar                     IN VARCHAR2    DEFAULT 'Y'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------
-- Accommodations for 19C DB
l_DBbanner VARCHAR2(255);

-- Apps Check
l_org_name                  VARCHAR2(240);
-- l_user_name                 VARCHAR2(100);
-- p2_user_name                VARCHAR2(100);
-- l_responsibility_name       VARCHAR2(100); 
-- p2_responsibility_id        VARCHAR2(30);
l_include_apps_check        VARCHAR2(1); 

l_wsh_otm_dlvy_multi_leg  VARCHAR2(1);

-- variables for messaging only
--l_so_org_id    VARCHAR2(240);
--l_so_org_name  VARCHAR2(240);



FUNCTION get_ORGID
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: ORGID');
BEGIN
  select org_id
    into l_system_function_var 
  from   oe_order_headers_all ord
  where 
     ORD.HEADER_ID = p_header_id;
  return l_system_function_var;
EXCEPTION WHEN NO_DATA_FOUND THEN
      return null;
END;
debug('end sql token function: ORGID');
END get_ORGID;

FUNCTION get_SALESORDERID
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: SALESORDERID');
BEGIN
  SELECT mso.sales_order_id
    INTO l_system_function_var
    FROM mtl_sales_orders mso,
         oe_order_headers_all ord,
         oe_transaction_types_tl typ
   WHERE ord.header_id = p_header_id
     AND ord.order_type_id = typ.transaction_type_id
     AND typ.language = 'US'
     AND mso.segment1 = to_char(ord.order_number)
     AND typ.name = mso.segment2
     AND mso.segment3 = fnd_profile.value('ONT_SOURCE_CODE');

  RETURN l_system_function_var;
EXCEPTION
  WHEN no_data_found THEN
    RETURN NULL;
END;

debug('end sql token function: SALESORDERID');
END get_SALESORDERID;

FUNCTION get_LINES
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: LINES');
BEGIN
  select count(1)
    into l_system_function_var
  from   oe_order_lines_all lin
  where 
     lin.header_id = p_header_id;
  return l_system_function_var;
EXCEPTION WHEN NO_DATA_FOUND THEN
      return null;
END;
debug('end sql token function: LINES');
END get_LINES;

FUNCTION get_HEADER_STATUS
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: HEADER_STATUS');
BEGIN
  select FLOW_STATUS_CODE
    into l_system_function_var 
  from   oe_order_headers_all ord
  where 
     ORD.HEADER_ID = p_header_id;
  return l_system_function_var;
EXCEPTION WHEN NO_DATA_FOUND THEN
      return null;
END;
debug('end sql token function: HEADER_STATUS');
END get_HEADER_STATUS;

FUNCTION get_ORDERNO
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: ORDERNO');
BEGIN
   SELECT order_number
    into l_system_function_var 
    from OE_ORDER_HEADERS_ALL          ORD
   where ORD.HEADER_ID                 = p_header_id;
   return l_system_function_var;
EXCEPTION WHEN NO_DATA_FOUND THEN
      return null;
END;
debug('end sql token function: ORDERNO');
END get_ORDERNO;

FUNCTION get_WDD_LINE_COUNT
   return VARCHAR2 IS
BEGIN
debug('begin sql token function: WDD_LINE_COUNT');
BEGIN
SELECT COUNT(1)
INTO l_system_function_var
  FROM wsh_delivery_details det,
       oe_order_lines_all lin
 WHERE det.source_code = 'OE'
   AND det.source_line_id = lin.line_id
   AND det.source_header_id = p_header_id
   AND lin.header_id = p_header_id;  
  RETURN l_system_function_var;
EXCEPTION
  WHEN no_data_found THEN
    RETURN NULL;
END;
debug('end sql token function: WDD_LINE_COUNT');
END get_WDD_LINE_COUNT;



BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   IF g_is_concurrent THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Order Number';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_order_number,'NO_MASK');
   END IF;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Header ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_header_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Line ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_line_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Diagnostic Apps Check (Default is N)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_include_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Workflow Information (Y/N)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_print_wf,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Purchasing Information (Y/N)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_print_purch,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Manufacturing Information (Y/N)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_print_mfg,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Inventory Information (Y/N)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_print_inv,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Receivables Information (Y/N)';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_print_ar,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.108  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/01/27 17:16:14 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'om_order_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_header_id');
IF p_header_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Header ID is required.');
   raise invalid_parameters;
END IF;
IF p_header_id IS NOT NULL THEN
BEGIN
SELECT HEADER_ID
INTO l_exists_val
FROM OE_ORDER_HEADERS_ALL H, HR_OPERATING_UNITS O, OE_TRANSACTION_TYPES_TL OT
WHERE HEADER_ID = p_header_id
 AND H.ORDER_NUMBER = NVL(p_order_number, H.ORDER_NUMBER)
AND H.ORG_ID = O.ORGANIZATION_ID
AND H.ORDER_TYPE_ID = OT.TRANSACTION_TYPE_ID(+)
AND OT.LANGUAGE='US'

 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid Header ID parameter provided.  Process cannot continue.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_header_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_header_id');

debug('begin parameter validation: p_line_id');
IF p_line_id IS NOT NULL THEN
BEGIN
SELECT LINE_ID
INTO l_exists_val
FROM OE_ORDER_LINES_ALL LIN
WHERE LINE_ID = p_line_id
 AND LIN.HEADER_ID = p_header_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid Line ID parameter provided.  Process cannot continue.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_line_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_line_id');

debug('begin parameter validation: p_include_apps_check');
IF p_include_apps_check IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Include Diagnostic Apps Check (Default is N) is required.');
   raise invalid_parameters;
END IF;
IF p_include_apps_check IS NOT NULL AND p_include_apps_check NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Gather and Include Apps Check Information is invalid.  Valid values are Y or N.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_include_apps_check');

debug('begin parameter validation: p_print_wf');
