PROCEDURE load_signatures IS
  l_info  HASH_TBL_4K;
BEGIN

null;

   -----------------------------------------
  -- Add definition of signatures here ....
  ------------------------------------------


debug('begin add_signature: SALES_ORDER_HEADER_INFORMATION_DISPLAY');
   l_info('##MASK##SALESPERSON'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '698',
      p_sig_id                 => 'SALES_ORDER_HEADER_INFORMATION_DISPLAY',
      p_sig_sql                => 'SELECT h.order_number "Order Number",
       h.header_id "Header ID",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''ORDER_CATEGORY''
            AND lookup_code = h.order_category_code ) "Order Category",
       h.order_type_id "Order Type ID",
       ( SELECT name
           FROM oe_transaction_types_tl
          WHERE transaction_type_id = h.order_type_id
            AND language = ''US'' ) "Order Type",
       ( SELECT ac.display_name
           FROM wf_item_activity_statuses ias,
                wf_process_activities pa,
                wf_activities_vl ac,
                wf_activities_vl ap,
                wf_items i
          WHERE ias.item_type = decode(h.transaction_phase_code, ''N'', ''OENH'', ''F'', ''OEOH'')
            AND ias.item_key = to_char(h.header_id)
            AND ias.process_activity = pa.instance_id
            AND pa.activity_name = ac.name
            AND pa.activity_item_type = ac.item_type
            AND pa.process_name = ap.name
            AND pa.process_item_type = ap.item_type
            AND pa.process_version = ap.version
            AND pa.process_name = ''ROOT''
            AND i.item_type = decode(h.transaction_phase_code, ''N'', ''OENH'', ''F'', ''OEOH'')
            AND i.item_key = ias.item_key
            AND i.begin_date >= ac.begin_date
            AND i.begin_date < nvl(ac.end_date, i.begin_date + 1) ) "Flow Process",
       h.flow_status_code "Flow Status Code",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE language = ''US''
            AND view_application_id = 660
            AND security_group_id = 0
            AND lookup_type = ''FLOW_STATUS''
            AND lookup_code = h.flow_status_code ) "Flow Status",
       h.sold_to_org_id "Sold To Org ID",
       party.party_name "Customer",
       cust_acct.account_number "Customer Number",
       nvl(party.gsa_indicator_flag, ''N'') "GSA",
       h.ship_to_org_id "Ship To Org ID",
       ship_su.location "Ship To Location",
       h.invoice_to_org_id "Invoice To Org ID",
       bill_su.location "Invoice To Location",
       h.org_id "Org ID",
       ( SELECT name
           FROM hr_operating_units hr
          WHERE h.org_id = hr.organization_id ) "Operating Unit",
       decode(nvl(h.transaction_phase_code, ''F''),
              ''N'', ''Negotiation'',
              ''F'', ''Fulfillment'') "Transaction Phase",
       nvl(h.open_flag, ''N'') "Open",
       nvl(h.booked_flag, ''N'') "Booked",
       nvl(h.cancelled_flag, ''N'') "Cancelled",
       h.quote_number "Quote Number",
       to_char(h.quote_date, ''DD-MON-RR_HH24:MI:SS'') "Quote Date",
       h.draft_submitted_flag "Draft Submitted",
       to_char(h.ordered_date, ''DD-MON-RR_HH24:MI:SS'') "Date Ordered",
       to_char(h.booked_date, ''DD-MON-RR_HH24:MI:SS'') "Date Booked",
       to_char(h.request_date, ''DD-MON-RR_HH24:MI:SS'') "Request Date",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''REQUEST_DATE_TYPE''
            AND lookup_code = nvl(h.order_date_type_code, ''SHIP'') ) "Order Date Type",
       h.ship_from_org_id "Ship From Org ID",
       ( SELECT organization_code
           FROM mtl_parameters mp
          WHERE mp.organization_id = h.ship_from_org_id ) "Warehouse",
       h.shipping_method_code "Shipping Method Code",
       ( SELECT meaning
           FROM fnd_lookup_values_vl
          WHERE lookup_type = ''SHIP_METHOD''
            AND lookup_code = h.shipping_method_code ) "Shipping Method",
       h.freight_terms_code "Freight Terms Code",
       ( SELECT meaning
           FROM fnd_lookup_values_vl
          WHERE lookup_type = ''FREIGHT_TERMS''
            AND view_application_id = 660
            AND lookup_code = h.freight_terms_code ) "Freight Terms",
       h.freight_carrier_code "Freight Carrier Code",
       h.fob_point_code "FOB Point Code",
       h.sold_from_org_id "Sold From Org ID",
       h.price_list_id "Price List ID",
       ( SELECT name
           FROM qp_list_headers_tl
          WHERE list_header_id = h.price_list_id
            AND language = ''US'' ) "Price List",
       to_char(h.pricing_date, ''DD-MON-RR_HH24:MI:SS'') "Pricing Date",
       h.transactional_curr_code "Currency",
       fc.precision "Precision",
       fc.extended_precision "Extended Precision",
       h.conversion_type_code "Conversion Type",
       h.conversion_rate "Conversion Rate",
       h.conversion_rate_date "Conversion Rate Date",
       ( SELECT name
           FROM jtf_rs_salesreps jrs
          WHERE jrs.salesrep_id = h.salesrep_id
            AND jrs.org_id = h.org_id ) "Salesperson",
       ( SELECT name
           FROM ra_terms_tl
          WHERE term_id = h.payment_term_id
            AND language = ''US'' ) "Payment Term",
       --( SELECT meaning from oe_lookups WHERE lookup_type = ''SALES_CHANNEL'' AND lookup_code = h.sales_channel_code) "Sales Channel",

       h.invoicing_rule_id "Invoicing Rule ID",
       ( SELECT name
           FROM ra_rules
          WHERE rule_id = h.invoicing_rule_id
            AND type = ''I'' ) "Invoicing Rule",
       h.accounting_rule_id "Accounting Rule ID",
       ( SELECT name
           FROM ra_rules
          WHERE rule_id = h.accounting_rule_id
            AND type = ''A'' ) "Accounting Rule",
       h.accounting_rule_duration "Accounting Rule Duration",
       h.fulfillment_set_name "Fulfillment Set",
       h.default_fulfillment_set "Default Fulfillment Set",
       h.line_set_name "Line Set",
       h.cust_po_number "Customer PO",
       h.agreement_id "Agreement ID",
       ( SELECT name
           FROM oe_agreements
          WHERE agreement_id = h.agreement_id ) "Pricing Agreement",
       h.blanket_number "Blanket Number",
       h.order_source_id "Order Source ID",
       ( SELECT name
           FROM oe_order_sources
          WHERE order_source_id = h.order_source_id ) "Order Source",
       h.orig_sys_document_ref "Orig Sys Document Ref",
       h.change_sequence "Change Sequence",
       h.source_document_type_id "Source Document Type ID",
       h.source_document_id "Source Document ID",
       h.upgraded_flag "Upgraded",
       ( SELECT name
           FROM oe_payment_types_tl opt
          WHERE opt.payment_type_code = h.payment_type_code
            AND language = ''US''
            AND org_id = h.org_id ) "Payment Type",
       h.payment_amount "Payment Amount",
       decode(h.tax_exempt_flag, 
	          ''E'', ''Exempt'', 
			  ''R'', ''Require'',
              ''S'', ''Standard'') "Tax Handling",
       --h.tax_exempt_number      "Tax Exempt No",
       --h.tax_exempt_reason_code "Tax Exempt Reason",

       h.shipment_priority_code "Shipment Priority",
       h.ship_tolerance_above "Over Shipment Tolerance",
       h.ship_tolerance_below "Under Shipment Tolerance",
       h.demand_class_code "Demand Class",
       --h.earliest_schedule_limit "Earlier Days Limit",
       --h.latest_schedule_limit   "Later Days Limit",
       --to_char(h.order_firmed_date, ''DD-MON-RR_HH24:MI:SS'') "Demand Firm Date",

       h.created_by "Created By",
       to_char(h.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Creation Date",
       h.last_updated_by "Last Updated By",
       to_char(h.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Last Update Date"
  FROM oe_order_headers_all h,
       hz_cust_accounts cust_acct,
       hz_parties party,
       hz_cust_site_uses_all ship_su,
       hz_cust_site_uses_all bill_su,
       fnd_currencies fc
 WHERE h.header_id = ##$$HEADERID$$##
   AND h.sold_to_org_id = cust_acct.cust_account_id (+)
   AND cust_acct.party_id = party.party_id (+)
   AND h.ship_to_org_id = ship_su.site_use_id (+)
   AND h.invoice_to_org_id = bill_su.site_use_id (+)
   AND h.transactional_curr_code = fc.currency_code (+)',
      p_title                  => 'Sales Order Header Information for Order: ##$$ORDERNO$$##',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no sales order header information',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '31'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_HEADER_INFORMATION_DISPLAY');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_WF_ASSIGNMENT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25232',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_WF_ASSIGNMENT',
      p_sig_sql                => 'SELECT wfa.wf_item_type|| '': ''|| 
       ( SELECT display_name FROM wf_item_types_tl WHERE language = ''US'' AND name = wfa.wf_item_type ) "Workflow Item Type",
       --wfa.item_type_code,
       ( SELECT meaning FROM oe_lookups WHERE lookup_type = ''WF_ASSIGN_ITEM_TYPES'' AND lookup_code = wfa.item_type_code ) "Item Type",
       wfa.line_type_id "Line Type ID",
       ( SELECT name FROM oe_transaction_types_tl WHERE language = ''US'' AND transaction_type_id = wfa.line_type_id ) "Line Type",
       wfa.process_name "Process",
       ( SELECT display_name
           FROM wf_activities_tl wat
          WHERE item_type = wfa.wf_item_type
            AND language = ''US''
            AND name = wfa.process_name
            AND version = (
           SELECT MAX(version)
             FROM wf_activities_tl wat1
            WHERE wat1.item_type = wfa.wf_item_type
              AND wat1.name = wat.name ) ) "Process Name",
       wfa.start_date_active "Start Date",
       wfa.end_date_active "End Date"
  FROM oe_workflow_assignments wfa,
       oe_order_headers_all oh
 WHERE wfa.order_type_id = oh.order_type_id
   AND oh.header_id = ##$$HEADERID$$##
   AND sysdate BETWEEN wfa.start_date_active AND nvl(wfa.end_date_active, sysdate)
 ORDER BY wfa.wf_item_type,
          wfa.item_type_code
',
      p_title                  => 'Workflow Assignments of the Transaction Type',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Missing workflow assignments for transaction type',
      p_solution               => 'Follow details in [130038/KB365642]<br>
Setup Workflow assignments for order/line transaction types',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_WF_ASSIGNMENT');



debug('begin add_signature: SALES_ORDER_ORDER_TYPE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '835',
      p_sig_id                 => 'SALES_ORDER_ORDER_TYPE',
      p_sig_sql                => 'SELECT otta.transaction_type_id "Transaction Type ID",
       ( SELECT name
           FROM oe_transaction_types_tl
          WHERE transaction_type_id = otta.transaction_type_id
            AND language = ''US'' ) "Transaction Type Name",
       otta.org_id "Org ID",
       ( SELECT name
           FROM hr_all_organization_units_tl
          WHERE organization_id = nvl(otta.org_id, - 99)
            AND language = ''US'' ) "Operating Unit",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''SALES_DOCUMENT_TYPE''
            AND lookup_code = otta.sales_document_type_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Sales Document Type",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''ORDER_CATEGORY''
            AND lookup_code = otta.order_category_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Order Category",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''TRANSACTION_TYPE''
            AND lookup_code = otta.transaction_type_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Transaction Type Code",
       ( SELECT display_name
           FROM wf_activities_tl wat
          WHERE item_type = ''OEOH''
            AND language = ''US''
            AND name IN (
           SELECT process_name
             FROM oe_workflow_assignments wfa
            WHERE line_type_id IS NULL
              AND wf_item_type = ''OEOH''
              AND order_type_id = otta.transaction_type_id
              AND sysdate BETWEEN start_date_active AND nvl(end_date_active, sysdate) )
            AND version = (
           SELECT MAX(version)
             FROM wf_activities_tl wat1
            WHERE wat1.item_type = ''OEOH''
              AND wat1.name = wat.name ) ) "Fulfillment Flow",
       ( SELECT display_name
           FROM wf_activities_tl wat
          WHERE item_type = ''OENH''
            AND language = ''US''
            AND name IN (
           SELECT process_name
             FROM oe_workflow_assignments wfa
            WHERE line_type_id IS NULL
              AND wf_item_type = ''OENH''
              AND order_type_id = otta.transaction_type_id
              AND sysdate BETWEEN start_date_active AND nvl(end_date_active, sysdate) )
            AND version = (
           SELECT MAX(version)
             FROM wf_activities_tl wat1
            WHERE wat1.item_type = ''OENH''
              AND wat1.name = wat.name ) ) "Negotiation Flow",
       to_char(otta.start_date_active, ''DD-MON-RR'') "Start Date",
       to_char(otta.end_date_active, ''DD-MON-RR'') "End Date",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''TRANSACTION_PHASE''
            AND lookup_code = otta.def_transaction_phase_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Default Transaction Phase",
       ( SELECT template_name
           FROM xdo_templates_vl
          WHERE application_id = 660
            AND template_id = otta.layout_template_id
            AND sysdate BETWEEN nvl(start_date, sysdate) AND nvl(end_date, sysdate) ) "Layout Template",
       ( SELECT template_name
           FROM okc_terms_templates_all
          WHERE template_id = otta.contract_template_id
            AND sysdate BETWEEN nvl(start_date, sysdate) AND nvl(end_date, sysdate) ) "Contract Template",
       decode(nvl(otta.quote_num_as_ord_num_flag, ''Y''),
              ''Y'', ''Yes'',
              ''N'', ''No'') "Retain Doc Number",
--       decode(nvl(otta.USE_AME_APPROVAL,''N''),
--              ''Y'', ''Yes'',
--              ''N'', ''No'') "Use AME",
       ( SELECT meaning
           FROM qp_lookups
          WHERE lookup_type = ''QP_AGREEMENT_TYPE''
            AND lookup_code = otta.agreement_type_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Agreement Type",
       decode(nvl(otta.agreement_required_flag, ''N''),
              ''Y'', ''Yes'',
              ''N'', ''No'') "Agreement Required",
       decode(nvl(otta.po_required_flag, ''N''),
              ''Y'', ''Yes'',
              ''N'', ''No'') "Purchase Order Required",
       ( SELECT name
           FROM oe_transaction_types_tl
          WHERE language = ''US''
            AND transaction_type_id = otta.default_inbound_line_type_id ) "Default Return Line Type",
       ( SELECT name
           FROM oe_transaction_types_tl
          WHERE language = ''US''
            AND transaction_type_id = otta.default_outbound_line_type_id ) "Default Order Line Type",
       decode(nvl(otta.enforce_line_prices_flag, ''N''),
              ''Y'', ''Yes'',
              ''N'', ''No'') "Enforce List Price",
       ( SELECT name
           FROM qp_list_headers_tl
          WHERE list_header_id = otta.price_list_id
            AND language = ''US'' ) "Price List",
       otta.min_margin_percent "Minimum Margin Percent",
       ( SELECT name
           FROM oe_credit_check_rules
          WHERE credit_check_rule_id = otta.entry_credit_check_rule_id
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Credit Check Rule: Ordering",
       ( SELECT name
           FROM oe_credit_check_rules
          WHERE credit_check_rule_id = otta.packing_credit_check_rule_id
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Credit Check Rule: Packing",
       ( SELECT name
           FROM oe_credit_check_rules
          WHERE credit_check_rule_id = otta.picking_credit_check_rule_id
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Credit Check Rule: Picking",
       ( SELECT name
           FROM oe_credit_check_rules
          WHERE credit_check_rule_id = otta.shipping_credit_check_rule_id
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Credit Check Rule: Shipping",
--       (SELECT meaning
--        FROM oe_lookups 
--        WHERE lookup_type in (''OE_CC_REVERSAL_REAUTHORIZATION'', ''OE_CC_EVENT_REV_REAUTH'') 
--        AND lookup_code = otta.CREDIT_CARD_REV_REAUTH_CODE
--        AND enabled_flag = ''Y''
--        AND sysdate between nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Reversal CC Auth Re-auth",
       ( SELECT organization_name
           FROM org_organization_definitions
          WHERE organization_id = otta.warehouse_id ) "Warehouse",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE lookup_type = ''SHIP_METHOD''
            AND language = ''US''
            AND view_application_id = 3
            AND lookup_code = otta.shipping_method_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Shipping Method",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE lookup_type = ''SHIPMENT_PRIORITY''
            AND language = ''US''
            AND view_application_id = 660
            AND lookup_code = otta.shipment_priority_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Shipment Priority",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE lookup_type = ''FREIGHT_TERMS''
            AND language = ''US''
            AND view_application_id = 660
            AND lookup_code = otta.freight_terms_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Freight Terms",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE lookup_type = ''FOB''
            AND language = ''US''
            AND view_application_id = 222
            AND lookup_code = otta.fob_point_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "FOB",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''SOURCE_TYPE''
            AND lookup_code = otta.ship_source_type_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Shipping Source Type",
       ( SELECT demand_class
           FROM oe_demand_classes_v
          WHERE demand_class_code = otta.demand_class_code ) "Demand Class",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''SCHEDULING_LEVEL''
            AND lookup_code = otta.scheduling_level_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Scheduling Level",
       decode(otta.inspection_required_flag, ''Y'', ''Yes'', ''N'', ''No'') "Inspection Required",
       decode(otta.auto_scheduling_flag, ''Y'', ''Yes'', ''N'', ''No'') "Auto Schedule",
       ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''OE_LINE_SET_POPLIST''
            AND lookup_code = otta.default_line_set_code
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Default Line Set",
       decode(otta.default_fulfillment_set, ''Y'', ''Yes'', ''N'', ''No'') "Fulfillment Set",
--       decode(otta.BILL_ONLY,
--              ''Y'', ''Yes'',
--              ''N'', ''No'')  "Bill Only",
       ( SELECT name
           FROM ra_rules
          WHERE type = ''I''
            AND status = ''A''
            AND rule_id = otta.invoicing_rule_id ) "Invoicing Rule",
       ( SELECT name
           FROM ra_rules
          WHERE status = ''A''
            AND type IN ( ''A'', ''ACC_DUR'', ''PP_DR_ALL'', ''PP_DR_PP'' )
            AND rule_id = otta.accounting_rule_id ) "Accounting Rule",
       ( SELECT name
           FROM ra_batch_sources_all
          WHERE batch_source_id = otta.invoice_source_id
            AND org_id = otta.org_id
			AND status = ''A''
            AND sysdate BETWEEN nvl(start_date, sysdate) AND nvl(end_date, sysdate) ) "Invoice Source",
       ( SELECT name
           FROM ra_batch_sources_all
          WHERE batch_source_id = otta.non_delivery_invoice_source_id
            AND org_id = otta.org_id
			AND status = ''A''
            AND sysdate BETWEEN nvl(start_date, sysdate) AND nvl(end_date, sysdate) ) "Non Delivery Invoice Source",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE view_application_id = 222
            AND lookup_type = ''CREDIT_METHOD_FOR_RULES''
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate)
            AND lookup_code = otta.accounting_credit_method_code
            AND language = ''US'' ) "Credit Method: Accounting",
       ( SELECT meaning
           FROM fnd_lookup_values
          WHERE view_application_id = 222
            AND lookup_type = ''CREDIT_METHOD_FOR_RULES''
            AND enabled_flag = ''Y''
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate)
            AND lookup_code = otta.invoicing_credit_method_code
            AND language = ''US'' ) "Credit Method: Invoicing",
       ( SELECT name
           FROM ra_cust_trx_types_all
          WHERE org_id = otta.org_id
            AND cust_trx_type_id = otta.cust_trx_type_id
            AND sysdate BETWEEN nvl(start_date, sysdate) AND nvl(end_date, sysdate) ) "Receivables Transaction Type",
       otta.tax_calculation_event_code "Tax Event",
       ( SELECT concatenated_segments
           FROM gl_code_combinations_kfv gcc
          WHERE otta.cost_of_goods_sold_account = gcc.code_combination_id
            AND sysdate BETWEEN nvl(start_date_active, sysdate) AND nvl(end_date_active, sysdate) ) "Cost of Goods Sold Account",
       otta.currency_code "Currency",
       otta.conversion_type_code "Conversion Type",
       otta.transaction_type_id "##$$FK1$$##"
  FROM oe_transaction_types_all otta,
       oe_order_headers_all ord
 WHERE ord.header_id = ##$$HEADERID$$##
   AND otta.transaction_type_id = ord.order_type_id',
      p_title                  => 'Order Header Transaction Type',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no order header transaction type.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('EBS_MFG_OM_ONT_ONTONESO_WF_ASSIGNMENT'),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '22'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_ORDER_TYPE');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_CUSTOMER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25968',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_CUSTOMER',
      p_sig_sql                => 'SELECT cust_acct.cust_account_id "Cust Account ID",
       cust_acct.account_number "Account No",
       cust_acct.account_name "Account Name",
       ( SELECT meaning FROM ar_lookups WHERE lookup_type = ''CODE_STATUS'' AND lookup_code = cust_acct.status ) "Status",
       ( SELECT meaning FROM ar_lookups WHERE lookup_type = ''CUSTOMER_TYPE'' AND lookup_code = cust_acct.customer_type ) "Customer Type",
       cust_acct.customer_class_code "Customer Class",

       cust_acct.party_id "Party ID",
       party.party_number "Party Number",
       party.party_name "Party Name",
       party.party_type "Party Type",
       party.address1||'' ''||party.address2 "Address",
       party.city "City",
       nvl(party.state, party.province) "State",
	   party.postal_code "Postal Code",
       party.country "Country",
       ( SELECT meaning FROM ar_lookups WHERE lookup_type = ''CODE_STATUS'' AND lookup_code = party.status ) "Party Status",

       ( SELECT site_use.site_use_id||'': ''||site_use.location
         FROM hz_cust_site_uses_all site_use,
              hz_cust_acct_sites_all site
         WHERE site_use.site_use_code = ''BILL_TO'' 
           AND site.cust_acct_site_id = site_use.cust_acct_site_id
 	       AND site.CUST_ACCOUNT_ID = cust_acct.cust_account_id
           AND site_use.primary_flag = ''Y''
           AND site_use.status = ''A''
           AND site.status = ''A''
           AND site.bill_to_flag = ''P''
           AND site.org_id = oh.org_id) "Primary Invoice To Org",
       ( SELECT site_use.site_use_id||'': ''||site_use.location
         FROM hz_cust_site_uses_all site_use,
              hz_cust_acct_sites_all site
         WHERE site_use.site_use_code = ''SHIP_TO'' 
           AND site.cust_acct_site_id = site_use.cust_acct_site_id
 	       AND site.CUST_ACCOUNT_ID = cust_acct.cust_account_id
           AND site_use.primary_flag = ''Y''
           AND site_use.status = ''A''
           AND site.status = ''A''
           AND site.ship_to_flag = ''P''
           AND site.org_id = oh.org_id) "Primary Ship To Org",

       ( SELECT meaning FROM oe_lookups WHERE lookup_type = ''SALES_CHANNEL'' AND lookup_code = cust_acct.sales_channel_code ) "Sales Channel",
       ( SELECT name FROM oe_transaction_types_tl WHERE transaction_type_id = cust_acct.order_type_id AND language = ''US'' ) "Order Type",
       ( SELECT name FROM qp_list_headers_tl WHERE list_header_id = cust_acct.price_list_id AND language = ''US'' ) "Price List",
       cust_acct.tax_code "Tax Code",
       cust_acct.fob_point "FOB Point",
       ( SELECT meaning FROM oe_lookups WHERE lookup_type = ''FREIGHT_TERMS'' AND lookup_code = cust_acct.freight_term ) "Freight Term",
       cust_acct.ship_via "Ship Method",
       cust_acct.warehouse_id "Warehouse",
       cust_acct.date_type_preference "Date Type Preference",
       cust_acct.over_shipment_tolerance "Over Shipment Tolerance",
       cust_acct.under_shipment_tolerance "Under Shipment Tolerance",
       cust_acct.over_return_tolerance "Over Return Tolerance",
       cust_acct.under_return_tolerance "Under Return Tolerance",
       cust_acct.ship_sets_include_lines_flag "Ship Sets Include",
       cust_acct.arrivalsets_include_lines_flag "Arrival Sets Include",
       cust_acct.sched_date_push_flag "Schedule Date Pushed",
       cust_acct.invoice_quantity_rule "Invoice Qty Rule",
       cust_acct.org_id "Org ID"

  FROM hz_cust_accounts cust_acct,
       hz_parties party,   
       oe_order_headers_all oh
 WHERE oh.sold_to_org_id = cust_acct.cust_account_id (+)
   AND cust_acct.party_id = party.party_id 
   AND oh.header_id = ##$$HEADERID$$##   
   ',
      p_title                  => 'Customer',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no customer.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_CUSTOMER');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_CUST_ADDRESS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25969',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_CUST_ADDRESS',
