 WHERE op.header_id = ##$$HEADERID$$## 
   AND op.line_id IS NULL
UNION ALL
SELECT -- Lines
       op.payment_number "Payment No",
       op.payment_trx_id "Payment Trx ID",
       op.payment_level_code "Payment Level",
       om_order_analyzer_pkg.line_shipment_option (lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line #",
       op.payment_collection_event "Payment Collection",
       op.payment_type_code "Payment Type",
       op.payment_percentage "Percent",
       op.payment_amount "Payment Amount",
       op.prepaid_amount "Prepaid Amount",
       op.credit_card_code "Credit Card",
       op.credit_card_number "CC Number", -- mask
       op.credit_card_holder_name "CC Holder", -- mask
       op.credit_card_expiration_date "CC Expiration",
       op.trxn_extension_id "Trxn Extension ID",
       op.credit_card_approval_code "Approval Code",
       op.credit_card_approval_date "Approval Date",
       op.check_number "Check No",
       op.receipt_method_id "Receipt Method",
       op.defer_payment_processing_flag "Defer",
       op.commitment_applied_amount "Commitment Applied",
       op.commitment_interfaced_amount "Commitment Interfaced",
       --op.invoiced_flag "Invoiced",
       op.payment_set_id "Payment Set ID",
       op.orig_sys_payment_ref "Orig Sys Payment Ref",
       lin.line_number "o1",
       nvl (lin.shipment_number, - 1) "o2",
       nvl (lin.option_number, - 1) "o3",
       nvl (lin.component_number, - 1) "o4",
       nvl (lin.service_number, - 1) "o5"
  FROM oe_payments op,
       oe_order_lines_all lin
 WHERE op.header_id = ##$$HEADERID$$## 
   AND lin.header_id = ##$$HEADERID$$## 
   AND nvl(''##$$LINEID$$##'',0) in (0,lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id)
   AND op.header_id = lin.header_id
   AND op.line_id = lin.line_id
   AND op.line_id IS NOT NULL
 ORDER BY 3 desc, 23, 24, 25, 26, 27, 1, 2',
      p_title                  => 'Order Payments',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no order payments.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_PAYMENT');



debug('begin add_signature: SALES_ORDER_HEADER_OPEN_WITH_CLOSED_LINES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1678',
      p_sig_id                 => 'SALES_ORDER_HEADER_OPEN_WITH_CLOSED_LINES',
      p_sig_sql                => ' SELECT h.header_id "Header ID",
       h.order_number "Order Number",
       h.org_id "Org ID",
       h.open_flag "Open Flag",
       substr(h.FLOW_STATUS_CODE,1,22) "Workflow Status"
FROM oe_order_headers_all h
WHERE h.open_flag = ''Y''
  AND h.header_id = ##$$HEADERID$$##
  AND NOT EXISTS ( SELECT 1
        FROM wf_items i
        WHERE i.item_type = ''OEOH''
          AND i.item_key = to_char(h.header_id)
          AND i.end_date IS NULL
    )
  AND NOT EXISTS (SELECT 1
        FROM oe_order_lines_all l
        WHERE l.open_flag = ''Y''
         AND l.header_id = h.header_id
    )
  AND NOT EXISTS ( SELECT 1
                    FROM wf_items i
        WHERE i.item_type = ''OEOL''
            AND i.parent_item_key = to_char(h.header_id)
            AND i.parent_item_type = ''OEOH''
            AND i.end_date IS NULL
    )',
      p_title                  => 'Sales Order Header Open with all lines Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Header Workflow should be in Close - Order, Deferred status since all lines are CLOSED.',
      p_solution               => 'Refer to [397565/KB746001] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_HEADER_OPEN_WITH_CLOSED_LINES');



