debug('begin add_signature: SALES_ORDER_HEADER_BOOKED_LINES_CLOSED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14153',
      p_sig_id                 => 'SALES_ORDER_HEADER_BOOKED_LINES_CLOSED',
      p_sig_sql                => 'SELECT h.header_id "Header ID",
       h.order_number "Order Number",
       h.org_id "Org ID",
       h.flow_status_code "Flow Status",
       h.ordered_date "Order Date"
  FROM wf_item_activity_statuses was,
       wf_process_activities p,
       oe_order_headers_all h
 WHERE h.header_id = ##$$HEADERID$$##
   AND TO_NUMBER(was.item_key) = h.header_id
   AND was.process_activity = p.instance_id
   AND p.activity_item_type = ''OEOH''
   AND p.activity_name = ''CLOSE_WAIT_FOR_L''
   AND was.activity_status = ''NOTIFIED''
   AND was.item_type = ''OEOH''
   AND NOT EXISTS (select /*+ NO_UNNEST */ 1
                 from oe_order_lines_all
                 where header_id = TO_NUMBER(was.item_key)
                 and open_flag = ''Y'' )
  AND NOT EXISTS (select 1 from wf_items
                 where item_type = ''OEOL''
                  and parent_item_key = to_char(h.header_id)
                  and parent_item_type = ''OEOH''
                  and end_date is null)',
      p_title                  => 'Header Remains in BOOKED Status where all Lines are In CLOSED or CANCELLED Status',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Order Header Remains in BOOKED status with all lines are in CLOSED or CANCELLED status.  Order Header should progress to either CLOSED or CANCELLED.',
      p_solution               => 'Refer to [1517127/KB754082] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
