debug('end add_signature: SALES_ORDER_HEADER_BOOKED_LINES_CLOSED');



debug('begin add_signature: SALES_ORDER_HEADER_OPEN_WITH_NO_OPEN_LIN_NO_HDR_WF_AND_NO_LIN_WF');
