debug('begin add_signature: SALES_ORDER_BOOKED_HDR_NONBOOKED_LIN_PROGRESSED_WF');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15627',
      p_sig_id                 => 'SALES_ORDER_BOOKED_HDR_NONBOOKED_LIN_PROGRESSED_WF',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
    lin.line_id "Line ID",
    lin.flow_status_code "Flow Status Code",
    lin.booked_flag "Booked Flag",
    lin.shipping_interfaced_flag "Shipping Interfaced Flag"
FROM
    oe_order_headers_all oh,
    oe_order_lines_all lin,
    wf_item_activity_statuses wfs,
    wf_process_activities wfp
WHERE
    oh.booked_flag = ''Y''
    AND lin.header_id = ##$$HEADERID$$##
    AND oh.header_id = lin.header_id
    AND NVL(''##$$LINEID$$##'',0) in (0, lin.LINE_ID, lin.TOP_MODEL_LINE_ID, lin.ATO_LINE_ID, lin.LINK_TO_LINE_ID, lin.SERVICE_REFERENCE_LINE_ID)
    AND oh.open_flag = ''Y''
    AND lin.booked_flag = ''N''
    AND lin.shipping_interfaced_flag != ''Y''
    AND oh.header_id = lin.header_id
    AND wfs.item_key = TO_CHAR(lin.line_id)
    AND wfs.item_type = ''OEOL''
    AND wfp.process_name = ''SHIP_CONFIRM''
	AND wfp.activity_name = ''SHIP_LINE''
    AND wfs.activity_status IN (''NOTIFIED'',''ERROR'')
    AND wfs.process_activity = wfp.instance_id
	AND EXISTS (SELECT 1 FROM wsh_delivery_details wdd WHERE wdd.source_line_id = lin.line_id AND wdd.source_code = ''OE'' AND wdd.released_status NOT IN (''X'', ''D''))
 ORDER BY lin.line_number,
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.component_number, - 1),
          nvl(lin.service_number, - 1)  ',
      p_title                  => 'Header Booked, Line Not Booked and Line Workflow Progressed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Header Booked, Line Not Booked and Line Workflow Progressed',
      p_solution               => 'Refer [2495581/KB714561]',
      p_success_msg            => 'No issues found.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_BOOKED_HDR_NONBOOKED_LIN_PROGRESSED_WF');



