debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_QUOTE_STATUS_LOST_UPDATE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27403',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_QUOTE_STATUS_LOST_UPDATE',
      p_sig_sql                => 'SELECT
    ooh.header_id "Header ID",
    ooh.order_number "Order Number",
    ooh.flow_status_code "Header Status",
    ooh.version_number "Version Number",
    ooh.creation_date "Creation Date",
     ( SELECT meaning
           FROM oe_lookups
          WHERE lookup_type = ''ORDER_CATEGORY''
            AND lookup_code = ooh.order_category_code ) "Order Category",
    ooh.order_type_id "Order Type ID",
       ( SELECT name
           FROM oe_transaction_types_tl
          WHERE transaction_type_id = ooh.order_type_id
            AND language = ''US'' ) "Order Type" ,
        ( SELECT ac.display_name
           FROM wf_item_activity_statuses ias,
                wf_process_activities pa,
                wf_activities_vl ac,
                wf_activities_vl ap,
                wf_items i
          WHERE ias.item_type = decode(ooh.transaction_phase_code, ''N'', ''OENH'', ''F'', ''OEOH'')
            AND ias.item_key = to_char(ooh.header_id)
            AND ias.process_activity = pa.instance_id
            AND pa.activity_name = ac.name
            AND pa.activity_item_type = ac.item_type
            AND pa.process_name = ap.name
            AND pa.process_item_type = ap.item_type
            AND pa.process_version = ap.version
            AND pa.process_name = ''ROOT''
            AND i.item_type = decode(ooh.transaction_phase_code, ''N'', ''OENH'', ''F'', ''OEOH'')
            AND i.item_key = ias.item_key
            AND i.begin_date >= ac.begin_date
            AND i.begin_date < nvl(ac.end_date, i.begin_date + 1) ) "Flow Process"   ,
            ( SELECT meaning
           FROM fnd_lookup_values
          WHERE language = ''US''
            AND view_application_id = 660
            AND security_group_id = 0
            AND lookup_type = ''FLOW_STATUS''
            AND lookup_code = ooh.flow_status_code ) "Flow Status",
            ooh.org_id "Org ID",
       ( SELECT name
           FROM hr_operating_units hr
          WHERE ooh.org_id = hr.organization_id ) "Operating Unit",
       decode(nvl(ooh.transaction_phase_code, ''F''),
              ''N'', ''Negotiation'',
              ''F'', ''Fulfillment'') "Transaction Phase",
              nvl(ooh.open_flag, ''N'') "Open",
       nvl(ooh.booked_flag, ''N'') "Booked",
       nvl(ooh.cancelled_flag, ''N'') "Cancelled",
       ooh.quote_number "Quote Number",
       to_char(ooh.quote_date, ''DD-MON-RR_HH24:MI:SS'') "Quote Date",
       ooh.draft_submitted_flag "Draft Submitted",
       to_char(ooh.ordered_date, ''DD-MON-RR_HH24:MI:SS'') "Date Ordered",
       to_char(ooh.booked_date, ''DD-MON-RR_HH24:MI:SS'') "Date Booked",
       to_char(ooh.request_date, ''DD-MON-RR_HH24:MI:SS'') "Request Date"
FROM
    oe_order_headers_all ooh
WHERE
    1 = 1
    AND ooh.header_id = ##$$HEADERID$$##
    AND ooh.open_flag = ''Y''
    AND ooh.booked_flag = ''N''
    AND ooh.transaction_Phase_code =''N'' -- Used only to identify Quotes
    AND ooh.flow_status_code NOT IN (
        ''Lost'',
        ''Draft'',
        ''ENTERED'',
        ''CANCELLED''
    )
    AND NOT EXISTS (
        SELECT
            *
        FROM
            wf_items wfi
        WHERE
            wfi.item_type = ''OENH''
            AND wfi.item_key = to_char(ooh.header_id)
    )',
      p_title                  => 'Quote Is Stuck and Unable to Update Status to Lost Because of Missing Quote Header Workflow',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Quote is Stuck in Status Other Than Lost and Draft and Negotiation Header Workflow is Purged. Unable to Update the Quote Status to Lost. ',
      p_solution               => 'Refer to [1459931/KB747345] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_QUOTE_STATUS_LOST_UPDATE');



