debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_HEADER_IN_DRAFT_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27526',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_HEADER_IN_DRAFT_STATUS',
      p_sig_sql                => 'SELECT ooh.order_number "Order Number",
       ooh.header_id "Header ID", 
       ooh.org_id "Org ID",
       ooh.transaction_phase_code "Trx Phase Code",
       ooh.flow_status_code "Header Status"
FROM oe_order_headers_all ooh, oe_order_lines_all ool
WHERE ooh.flow_status_code = ''DRAFT''
AND ooh.transaction_phase_code = ''N''
AND ooh.header_id = ool.line_id
AND ooh.org_id = ool.org_id
AND ool.shippable_flag = ''Y''
AND shipping_interfaced_flag = ''Y''
AND ool.booked_flag = ''Y''
AND ooh.booked_flag = ''Y''
AND ooh.header_id = ##$$HEADERID$$##
AND EXISTS (SELECT 1
              FROM wsh_delivery_details wdd
             WHERE wdd.source_line_id = ool.line_id
               AND wdd.released_status <> ''D'')',
      p_title                  => 'Order Header In Draft Status',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales order header is in Draft status whereas order lines got pick released',
      p_solution               => 'Refer To : [2766573/KB575004] ',
      p_success_msg            => 'There is no issue with Order Status as the order is in booked status',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_HEADER_IN_DRAFT_STATUS');



