debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_HEADER_BOOKED_WORKFLOW_BOOK_ELIGIBLE_LINES_CLOSED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27444',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_HEADER_BOOKED_WORKFLOW_BOOK_ELIGIBLE_LINES_CLOSED',
      p_sig_sql                => 'SELECT
              ''exist''
 FROM
    oe_order_headers_all        oh,
    wf_item_activity_statuses   sta,
    wf_process_activities       pa
WHERE
    oh.header_id = ##$$HEADERID$$##
    AND oh.open_flag = ''Y''
    AND oh.flow_status_code = ''BOOKED''
    AND nvl(oh.booked_flag, ''N'') = ''Y''
    AND sta.end_date is Null
    AND sta.process_activity = pa.instance_id
    AND sta.item_type = ''OEOH''
    AND sta.item_key = to_char(oh.header_id)
    AND pa.activity_name = ''BOOK_ELIGIBLE''
AND sta.activity_status = ''NOTIFIED''
    AND NOT EXISTS (
        SELECT
            1
        FROM
            oe_order_lines_all   ol,
            wf_items             wfi
        WHERE
            ol.header_id = oh.header_id
            AND ol.open_flag = ''Y''
            AND wfi.item_key = to_char(ol.line_id)
            AND wfi.item_type = ''OEOL''
            AND wfi.end_date IS NULL) ',
