      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are orders which need to get the header status from "Booked" to "Closed".
Order header is in BOOKED status, but workflow shows BOOK_ELIGIBLE.

Lines are closed and cancelled with line workflow at CLOSE_CONTINUE_HEADER.',
      p_solution               => 'Refer to [2805977/KB737432] for details
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_HEADER_BOOKED_WORKFLOW_BOOK_ELIGIBLE_LINES_CLOSED');



