debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_HEADER_ENTERED_LINES_BOOKED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27579',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_HEADER_ENTERED_LINES_BOOKED',
      p_sig_sql                => 'SELECT h.order_number,
        h.header_id,
        h.open_flag,
        h.booked_flag,
        h.flow_Status_code
    FROM
        oe_order_headers_all        h
    WHERE
        1 = 1
        AND h.open_flag = ''Y''
        AND h.flow_status_code = ''ENTERED''
        AND h.booked_flag = ''N''
        AND h.header_id = ##$$HEADERID$$##
AND NOT EXISTS (
            SELECT
                1
            FROM
                oe_order_lines_all l
            WHERE
                l.header_id = h.header_id
                AND NVL(l.booked_flag, ''N'') <> ''Y''
        )
 AND EXISTS (select 1 from oe_order_lines_all l1
             WHERE  l1.header_id = h.header_id
             AND l1.open_flag=''Y''
        )',
      p_title                  => 'Sales Order Header In Entered Status While Lines Progressed Beyond Booking',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Header In Entered Status. All Lines are Booked and Progressed Beyond Booking activity in Workflow.',
      p_solution               => 'Refer to [2801273/KB712535] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
