      p_sig_repo_id            => '27601',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_RELEASE_INTERNAL_REQUISITION_APPROVAL_HOLD',
      p_sig_sql                => 'SELECT
l.header_id "Order Header ID",
om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line Number",
