AND hs.hold_release_id IS NULL
AND oh.header_id = l.header_id
AND hs.hold_entity_id = l.header_id
AND oh.released_flag = ''N''
)
AND EXISTS (
SELECT
1
FROM
po_requisition_headers_all prh,
po_change_requests pcr
WHERE
l.source_document_id = prh.requisition_header_id
AND prh.requisition_header_id = pcr.document_header_id
AND prh.authorization_status = ''APPROVED''
AND prh.change_pending_flag = ''N''
