debug('begin add_signature: SALES_ORDER_LINES_ON_ORDER_DISPLAY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8923',
      p_sig_id                 => 'SALES_ORDER_LINES_ON_ORDER_DISPLAY',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       lin.flow_status_code "Line Status Code",
	   ( SELECT meaning
	     FROM fnd_lookup_values
         WHERE language = ''US''
           AND view_application_id = 660
           AND security_group_id = 0
           AND lookup_type = ''LINE_FLOW_STATUS''
           AND lookup_code = lin.flow_status_code ) "Line Status",
       ( SELECT meaning
	     FROM fnd_lookup_values
         WHERE language = ''US''
           AND view_application_id = 660
           AND security_group_id = 0
           AND lookup_type = ''LINE_CATEGORY''
           AND lookup_code = lin.line_category_code ) "Line Category",
       nvl(lin.open_flag, ''N'') "Open",
       nvl(lin.cancelled_flag, ''N'') "Cancelled",
       substr(itm.segment1, 1, 80) "Item Name",
       ( SELECT meaning
	     FROM fnd_lookup_values
         WHERE language = ''US''
           AND view_application_id = 660
           AND security_group_id = 0
           AND lookup_type = ''ITEM_TYPE''
           AND lookup_code = lin.item_type_code ) "Item Type",
	   nvl(lin.ordered_quantity, 0) "Ordered Qty",
       lin.order_quantity_uom "UOM",
       nvl(lin.cancelled_quantity, 0)  "Cancelled Qty",
       nvl(lin.shipped_quantity, 0)    "Shipped Qty",
       nvl(fulfilled_quantity, 0)      "Fulfilled Qty",
	   --Sets
  	   nvl2(lin.ship_set_id, lin.ship_set_id||'': ''||( SELECT set_name||'': ''||os.set_type FROM oe_sets os WHERE os.set_id = lin.ship_set_id ), '''') "Ship Set",
       nvl2(lin.arrival_set_id, lin.arrival_set_id||'': ''||( SELECT set_name||'': ''||os.set_type FROM oe_sets os WHERE os.set_id = lin.arrival_set_id ), '''') "Arrival Set",
       ( SELECT ols.set_id||'': ''||os.set_name||'': ''||os.set_type
         FROM oe_sets os, oe_line_sets ols
         WHERE os.set_id = ols.set_id
           AND ols.line_id = lin.line_id
           AND rownum=1) "Fulfillment Set",
       nvl2(lin.line_set_id, lin.line_set_id||'': ''||os.set_name||'': ''||os.set_type, '''') "Line Set",
	   lin.split_by                 "Split By",
       lin.split_from_line_id       "Split From Line"
FROM oe_order_lines_all    lin,
     mtl_system_items      itm,
	 oe_sets               os
WHERE lin.header_id = ##$$HEADERID$$##
      AND lin.ship_from_org_id = itm.organization_id (+)
      AND lin.inventory_item_id = itm.inventory_item_id (+)
	  AND lin.line_set_id = os.set_id (+)
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1)		 ',
      p_title                  => 'Sales Order Line(s) Associated with Order ##$$ORDERNO$$##',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no sales order line(s).',
      p_solution               => 'Order Lines on Order ##$$ORDERNO$$##',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '25'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_ON_ORDER_DISPLAY');



debug('begin add_signature: SALES_ORDER_LINES_DISPLAY');
   l_info('##HYPERLINK##'):= 'Delivery Detail ID,SALES_ORDER_WSH_DELIVERY_DETAILS,Delivery Detail ID:Flow Status Code,SALES_ORDER_LINE_WF_ACTIVITY_PARENT,Flow Status Code';
   l_info('##MASK##SALESPERSON'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '704',
      p_sig_id                 => 'SALES_ORDER_LINES_DISPLAY',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       ( SELECT MIN(det.delivery_detail_id)
         FROM wsh_delivery_details det
         WHERE det.source_code = ''OE''
              AND lin.line_id = det.source_line_id) "Delivery Detail ID",
       ( SELECT ac.display_name
         FROM wf_item_activity_statuses ias,
              wf_process_activities     pa,
              wf_activities_vl          ac,
              wf_activities_vl          ap,
              wf_items                  i
         WHERE ias.item_type = ''OEOL''
               AND ias.item_key = to_char(lin.line_id)
               AND ias.process_activity = pa.instance_id
               AND pa.activity_name = ac.name
               AND pa.activity_item_type = ac.item_type
               AND pa.process_name = ap.name
               AND pa.process_item_type = ap.item_type
               AND pa.process_version = ap.version
               AND pa.process_name = ''ROOT''
               AND i.item_type = ''OEOL''
               AND i.item_key = ias.item_key
               AND i.begin_date >= ac.begin_date
               AND i.begin_date < nvl(ac.end_date, i.begin_date + 1) ) "Flow Process",
       lin.flow_status_code "Flow Status Code",             
       --decode(nvl(lin.transaction_phase_code, ''F''), ''N'', ''Negotiation'', ''F'', ''Fulfillment'') "Transaction Phase",
       lin.line_type_id                                   "Line Type ID",
       ( SELECT name
         FROM oe_transaction_types_tl
         WHERE transaction_type_id = lin.line_type_id
               AND language = ''US'' )                      "Line Type",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''LINE_CATEGORY''
               AND lookup_code = lin.line_category_code ) "Line Category",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''SOURCE_TYPE''
               AND lookup_code = lin.source_type_code ) "Source Type",
       nvl(lin.open_flag, ''N'')                            "Open",
       nvl(lin.booked_flag, ''N'')                          "Booked",
       nvl(lin.cancelled_flag, ''N'')                       "Cancelled",
       nvl(lin.shippable_flag, ''N'')                       "Shippable",
       nvl(lin.shipping_interfaced_flag, ''N'')             "Shipping Interfaced",
       nvl(lin.fulfilled_flag, ''N'')                       "Fulfilled",
       nvl(lin.invoice_interface_status_code, ''NO'')||'': ''||
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''INVOICE_INTERFACE_STATUS''
           AND lookup_code = nvl(lin.invoice_interface_status_code, ''NO'') ) "Invoice Interface Status",
       lin.inventory_item_id       "Item ID",
       substr(itm.segment1, 1, 80) "Item Name",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''ITEM_TYPE''
           AND lookup_code = lin.item_type_code ) "Item Type",
       lin.ordered_item_id  "Ordered Item ID",
       lin.ordered_item     "Ordered Item",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''ITEM_IDENTIFIER_TYPE''
           AND lookup_code = lin.item_identifier_type ) "Item Identifier", 		 
       --config
	   lin.top_model_line_id "Top Model Line ID",
       lin.ato_line_id       "ATO Line ID",
       lin.link_to_line_id   "Link to Line ID",
       nvl(lin.ship_model_complete_flag, ''N'') "Ship Model Complete",
       lin.model_remnant_flag                 "Model Remnant",
	   lin.config_header_id  "Config Header ID",
	   lin.config_rev_nbr    "Config Rev Nbr",
       --Qty
	   nvl(lin.ordered_quantity, 0)   "Ordered Qty",
       lin.order_quantity_uom         "Ordered UOM",
       ( SELECT SUM(r.primary_reservation_quantity)
         FROM mtl_reservations r
         WHERE r.demand_source_header_id = ##$$SALESORDERID$$##
		   AND r.demand_source_line_id = lin.line_id
           AND r.demand_source_type_id IN (2,8,9,21,22) ) "Reserved Qty",
       nvl(lin.shipping_quantity, 0)   "Shipping Qty",
       lin.shipping_quantity_uom       "Shipping UOM",
       nvl(lin.shipped_quantity, 0)    "Shipped Qty",
       nvl(lin.cancelled_quantity, 0)  "Cancelled Qty",	   
       nvl(fulfilled_quantity, 0)      "Fulfilled Qty",
       nvl(lin.invoiced_quantity, 0)   "Invoiced Qty",
       --Secondary Qty
       nvl(lin.ordered_quantity2, 0)   "Secondary Ordered Qty",
       lin.ordered_quantity_uom2       "Secondary Ordered UOM",
       nvl(lin.shipping_quantity2, 0)  "Secondary Shipping Qty",
       lin.shipping_quantity_uom2      "Secondary Shipping UOM",
       nvl(lin.shipped_quantity2, 0)   "Secondary Shipped Qty",
       nvl(lin.cancelled_quantity2, 0) "Secondary Cancelled Qty",
       nvl(fulfilled_quantity2, 0)     "Secondary Fulfilled Qty",
       --
       lin.unit_selling_price          "Unit Selling Price",
       --lin.unit_list_price             "Unit List Price",
       --lin.price_list_id               "Price List ID",
       ( SELECT name
         FROM qp_list_headers_tl
         WHERE list_header_id = lin.price_list_id
               AND language = ''US'' )   "Price List",
       lin.unit_cost                "Unit Cost",
       -- tax
	   decode(lin.tax_exempt_flag, 
	          ''E'', ''Exempt'', 
			  ''R'', ''Require'', 
			  ''S'', ''Standard'') "Tax Handling",
       lin.tax_value           "Tax Amount",			  
       lin.tax_code            "Tax Code",
	   lin.tax_date            "Tax Date",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''CALCULATE_PRICE_FLAG''
               AND lookup_code = lin.calculate_price_flag ) "Calculate Price",
       ( SELECT name
         FROM ra_terms_tl
         WHERE term_id = lin.payment_term_id
               AND language = ''US'' ) "Payment Term",
       ( SELECT name
         FROM jtf_rs_salesreps jrs
         WHERE jrs.salesrep_id = lin.salesrep_id
               AND jrs.org_id = lin.org_id ) "Salesperson",
       lin.org_id                                "Org ID",
       ( SELECT name
         FROM hr_operating_units hr
         WHERE lin.org_id = hr.organization_id ) "Operating Unit",
       lin.ship_from_org_id                      "Ship From Org ID",
       ( SELECT organization_code
         FROM mtl_parameters mp
         WHERE mp.organization_id = lin.ship_from_org_id ) "Warehouse",
       lin.subinventory                  "Subinventory",
       lin.sold_from_org_id              "Sold From Org ID",
       ( SELECT name
         FROM hr_all_organization_units hr
         WHERE lin.sold_from_org_id = hr.organization_id ) "Sold From",
	   --
	   lin.schedule_status_code          "Schedule Status",
       nvl(lin.visible_demand_flag, ''N'') "Visible Demand",
       lin.override_atp_date_code        "Override ATP",
       lin.delivery_lead_time            "Delivery Lead Time",
       to_char(lin.request_date, ''DD-MON-RR_HH24:MI:SS'')             "Request Date",
       to_char(lin.promise_date, ''DD-MON-YYYY_HH24:MI:SS'')             "Promise Date",
       to_char(lin.earliest_acceptable_date, ''DD-MON-RR_HH24:MI:SS'') "Earliest Acceptable Date",
       to_char(lin.latest_acceptable_date, ''DD-MON-RR_HH24:MI:SS'')   "Latest Acceptable Date",
       to_char(lin.schedule_ship_date, ''DD-MON-RR_HH24:MI:SS'')       "Schedule Ship Date",
       to_char(lin.actual_shipment_date, ''DD-MON-RR_HH24:MI:SS'')     "Actual Shipment Date",
       to_char(lin.schedule_arrival_date, ''DD-MON-RR_HH24:MI:SS'')    "Schedule Arrival Date",
       to_char(lin.actual_arrival_date, ''DD-MON-RR_HH24:MI:SS'')      "Actual Arrival Date",
       to_char(lin.fulfillment_date, ''DD-MON-RR_HH24:MI:SS'')         "Fulfillment Date",
       to_char(lin.actual_fulfillment_date, ''DD-MON-RR_HH24:MI:SS'')  "Actual Fulfillment Date",
	   lin.demand_class_code  "Demand Class",
       --lin.planning_priority       "Planning Priority",

       nvl2(lin.shipping_method_code, 
	   lin.shipping_method_code||'': ''||
       ( SELECT meaning
         FROM fnd_lookup_values_vl
         WHERE lookup_type = ''SHIP_METHOD''
               AND lookup_code = lin.shipping_method_code ), '''') "Shipping Method",
       --lin.shipment_priority_code  "Shipment Priority Code",			   
       lin.freight_carrier_code "Freight Carrier Code",
       lin.freight_terms_code||'': ''||
	   ( SELECT meaning
         FROM fnd_lookup_values_vl
         WHERE lookup_type = ''FREIGHT_TERMS''
               AND view_application_id = 660
               AND lookup_code = lin.freight_terms_code ) "Freight Terms",
       lin.fob_point_code                                 "FOB Point Code",
       lin.invoicing_rule_id                              "Invoicing Rule ID",
       ( SELECT name
         FROM ra_rules
         WHERE rule_id = lin.invoicing_rule_id
               AND type = ''I'' )                           "Invoicing Rule",
       lin.accounting_rule_id                             "Accounting Rule ID",
       ( SELECT name
         FROM ra_rules
         WHERE rule_id = lin.accounting_rule_id
               AND type = ''A'' )                           "Accounting Rule",
       lin.accounting_rule_duration "Accounting Rule Duration",
       lin.ship_tolerance_above     "Ship Tolerance Above",
       lin.ship_tolerance_below     "Ship Tolerance Below",
	   --Sets
  	   nvl2(lin.ship_set_id, lin.ship_set_id||'': ''||( SELECT set_name||'': ''||os.set_type FROM oe_sets os WHERE os.set_id = lin.ship_set_id ), '''') "Ship Set",
       nvl2(lin.arrival_set_id, lin.arrival_set_id||'': ''||( SELECT set_name||'': ''||os.set_type FROM oe_sets os WHERE os.set_id = lin.arrival_set_id ), '''') "Arrival Set",
       ( SELECT ols.set_id||'': ''||os.set_name||'': ''||os.set_type
         FROM oe_sets os, oe_line_sets ols
         WHERE os.set_id = ols.set_id
           AND ols.line_id = lin.line_id
           AND rownum=1) "Fulfillment Set",
       nvl2(lin.line_set_id, lin.line_set_id||'': ''||os.set_name||'': ''||os.set_type, '''') "Line Set",
	   lin.split_by                 "Split By",
       lin.split_from_line_id       "Split From Line",
       -- 
       lin.sold_to_org_id           "Sold To Org ID",
       party.party_name             "Customer",
       lin.ship_to_org_id           "Ship To Org ID",
       ship_su.location             "Ship To Location",
       lin.invoice_to_org_id        "Invoice To Org ID",
       bill_su.location             "Invoice To Location",
       --
       lin.reference_header_id      "Return Reference Header",
       lin.reference_line_id        "Return Reference Line",
	   lin.return_reason_code       "Return Reason",

       lin.blanket_number           "Blanket Number",
       lin.blanket_line_number      "Blanket Line Number",
       lin.cust_po_number           "Customer PO",
       ( SELECT name
         FROM oe_payment_types_tl opt
         WHERE opt.payment_type_code = lin.payment_type_code
               AND language = ''US''
               AND org_id = lin.org_id ) "Payment Type",
       lin.order_source_id             "Order Source ID",
       ( SELECT name
         FROM oe_order_sources
         WHERE order_source_id = lin.order_source_id ) "Order Source",
       lin.orig_sys_document_ref       "Orig Sys Document Ref",
       lin.orig_sys_line_ref           "Orig Sys Line Ref",
       lin.orig_sys_shipment_ref       "Orig Sys Shipment Ref",
       lin.source_document_id "Source Doc ID", 
       lin. source_document_line_id "Source Doc Line ID",
       lin.source_document_type_id "Source Doc Type ID", 
       lin.change_sequence             "Change Sequence",
       --service
       lin.service_number              "Service Number",
	   lin.service_start_date          "Service Start Date",
       lin.service_end_date            "Service End Date",
	   lin.service_period              "Service Period",
           lin.service_reference_type_code "Service Ref Type",
       lin.service_reference_line_id   "Service Ref Line", 
	   lin.service_coterminate_flag    "Service Coterminate",
       --
       lin.revrec_event_code           "Revenue Deferral",
       DECODE(NVL(lin.revrec_event_code,''X''),''X'', lin.revrec_implicit_flag||'': Not Applicable'',
       DECODE(NVL(lin.revrec_implicit_flag,''N''),''N'',lin.revrec_implicit_flag||'': Explicit'',''Y'',lin.revrec_implicit_flag||'': Implicit'')) "Implicit Acceptance",
       lin.accepted_quantity           "Accepted Qty",
       lin.accepted_by                 "Accepted By",
       --
       lin.project_id "Project Id",
       lin.task_id "Task Id",
       lin.created_by "Created By",
       to_char(lin.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Creation Date",
       lin.last_updated_by "Last Updated By",
       to_char(lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Last Update Date"
	   
FROM oe_order_lines_all    lin,
     mtl_system_items      itm,
     hz_cust_accounts      cust_acct,
     hz_parties            party,
     hz_cust_site_uses_all ship_su,
     hz_cust_site_uses_all bill_su,
	 oe_sets               os
WHERE lin.header_id = ##$$HEADERID$$##
      AND NVL(''##$$LINEID$$##'',0) in (0, lin.LINE_ID, lin.TOP_MODEL_LINE_ID, lin.ATO_LINE_ID, lin.LINK_TO_LINE_ID, lin.SERVICE_REFERENCE_LINE_ID)
      AND lin.ship_from_org_id = itm.organization_id (+)
      AND lin.inventory_item_id = itm.inventory_item_id (+)
      AND lin.sold_to_org_id = cust_acct.cust_account_id (+)
      AND cust_acct.party_id = party.party_id (+)
      AND lin.ship_to_org_id = ship_su.site_use_id (+)
      AND lin.invoice_to_org_id = bill_su.site_use_id (+)
	  AND lin.line_set_id = os.set_id (+)
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Line(s) ',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no sales order line(s).',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '69'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_DISPLAY');



debug('begin add_signature: SALES_ORDER_SET');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '705',
      p_sig_id                 => 'SALES_ORDER_SET',
      p_sig_sql                => 'SELECT * FROM (
SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number,lin.service_number) "Line",
       ols.line_id  "Line ID",
       os.set_id    "Set ID",
       os.set_name  "Set Name",
	   os.set_type  "Set Type Code",
       decode(os.set_status, ''C'', ''Closed'', os.set_status) "Status",	   
       os.ship_from_org_id  "Ship From Org ID",
       os.ship_to_org_id    "Ship To Org ID",
       to_char(os.schedule_ship_date, ''DD-MON-RR_HH24:MI:SS'')    "Schedule Ship Date",
       to_char(os.schedule_arrival_date, ''DD-MON-RR_HH24:MI:SS'') "Schedule Arrival Date",
       os.freight_carrier_code     "Freight Carrier",
       os.shipping_method_code     "Shipping Method",
	   os.shipment_priority_code   "Shipment Prioritity",
       os.inventory_item_id        "Item ID",
       os.ordered_quantity_uom     "UOM",
       os.line_type_id             "Line Type ID",
       os.ship_tolerance_above     "Ship Tolerance Above",
       os.ship_tolerance_below     "Ship Tolerance Below"
FROM oe_sets            os,
     oe_line_sets       ols,
     oe_order_lines_all lin
WHERE ols.set_id = os.set_id (+)
      AND ols.line_id = lin.line_id
      AND lin.header_id = ##$$HEADERID$$##
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1),
		 os.set_id
)      
UNION ALL
SELECT * FROM (
SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number,lin.service_number) "Line",
       lin.line_id  "Line ID",
       os.set_id    "Set ID",
       os.set_name  "Set Name",
	   os.set_type  "Set Type Code",
       decode(os.set_status, ''C'', ''Closed'', os.set_status) "Status",
       os.ship_from_org_id  "Ship From Org ID",
       os.ship_to_org_id    "Ship To Org ID",
       to_char(os.schedule_ship_date, ''DD-MON-RR_HH24:MI:SS'')    "Schedule Ship Date",
       to_char(os.schedule_arrival_date, ''DD-MON-RR_HH24:MI:SS'') "Schedule Arrival Date",
       os.freight_carrier_code     "Freight Carrier",
       os.shipping_method_code     "Shipping Method",
	   os.shipment_priority_code   "Shipment Prioritity",
       os.inventory_item_id        "Item ID",
       os.ordered_quantity_uom     "UOM",
       os.line_type_id             "Line Type ID",
       os.ship_tolerance_above     "Ship Tolerance Above",
       os.ship_tolerance_below     "Ship Tolerance Below"
FROM oe_sets            os,
     oe_order_lines_all lin
WHERE os.header_id =##$$HEADERID$$##
  AND( (os.set_type =''SHIP_SET'' AND os.set_id =lin.ship_set_id )
    OR (os.set_type =''SPLIT'' AND os.set_id =lin.line_set_id   )
    or (os.set_type =''ARRIVAL_SET'' AND os.set_id =lin.arrival_set_id   ))
ORDER BY os.set_id
)',
      p_title                  => 'Line Set(s)',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no line set(s).',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '15'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_SET');



debug('begin add_signature: SALES_ORDER_LINE_TYPE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15630',
      p_sig_id                 => 'SALES_ORDER_LINE_TYPE',
      p_sig_sql                => 'SELECT otta.transaction_type_id
       "Transaction Type ID"
       ,
       (SELECT NAME
        FROM   OE_TRANSACTION_TYPES_TL
        WHERE  transaction_type_id = otta.transaction_type_id
               AND language = ''US'')
       "Transaction Type Name",
       otta.org_id                                                "Org ID",
       (SELECT NAME
        FROM   HR_OPERATING_UNITS
        WHERE  organization_id = Nvl(otta.org_id, -99))
       "Operating Unit",
       (SELECT meaning
        FROM   OE_LOOKUPS
        WHERE  lookup_type = ''SALES_DOCUMENT_TYPE''
               AND lookup_code = otta.sales_document_type_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Sales Document Type",
       (SELECT meaning
        FROM   OE_LOOKUPS
        WHERE  lookup_type = ''ORDER_CATEGORY''
               AND lookup_code = otta.order_category_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Order Category",
       (SELECT meaning
        FROM   OE_LOOKUPS
        WHERE  lookup_type = ''TRANSACTION_TYPE''
               AND lookup_code = otta.transaction_type_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Transaction Type Code",
       To_char(otta.start_date_active, ''DD-MON-RR'')               "Start Date",
       To_char(otta.end_date_active, ''DD-MON-RR'')                 "End Date",
       --       decode(nvl(otta.USE_AME_APPROVAL,''N''),
       --              ''Y'', ''Yes'',
       --              ''N'', ''No'') "Use AME",
       (SELECT meaning
        FROM   QP_LOOKUPS
        WHERE  lookup_type = ''QP_AGREEMENT_TYPE''
               AND lookup_code = otta.agreement_type_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Agreement Type",
       Decode(Nvl(otta.enforce_line_prices_flag, ''N''), ''Y'', ''Yes'',
                                                       ''N'', ''No'')
       "Enforce List Price",
       (SELECT NAME
        FROM   OE_PRICE_LISTS
        WHERE  price_list_id = otta.price_list_id)                "Price List",
       otta.min_margin_percent
       "Minimum Margin Percent",
       (SELECT organization_name
        FROM   ORG_ORGANIZATION_DEFINITIONS
        WHERE  organization_id = otta.warehouse_id)               "Warehouse",
       (SELECT meaning
        FROM   FND_LOOKUP_VALUES
        WHERE  lookup_type = ''SHIP_METHOD''
               AND language = ''US''
               AND view_application_id = 3
               AND lookup_code = otta.shipping_method_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Shipping Method",
       otta.AUTO_SCHEDULING_FLAG "Auto Schedule"
       ,
       (SELECT meaning
        FROM   FND_LOOKUP_VALUES
        WHERE  lookup_type = ''SHIPMENT_PRIORITY''
               AND language = ''US''
               AND view_application_id = 660
               AND lookup_code = otta.shipment_priority_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Shipment Priority",
       (SELECT meaning
        FROM   FND_LOOKUP_VALUES
        WHERE  lookup_type = ''FREIGHT_TERMS''
               AND language = ''US''
               AND view_application_id = 660
               AND lookup_code = otta.freight_terms_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Freight Terms",
       (SELECT meaning
        FROM   FND_LOOKUP_VALUES
        WHERE  lookup_type = ''FOB''
               AND language = ''US''
               AND view_application_id = 222
               AND lookup_code = otta.fob_point_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate)) "FOB",
       (SELECT meaning
        FROM   OE_LOOKUPS
        WHERE  lookup_type = ''SOURCE_TYPE''
               AND lookup_code = otta.ship_source_type_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Shipping Source Type",
       (SELECT demand_class
        FROM   OE_DEMAND_CLASSES_V
        WHERE  demand_class_code = otta.demand_class_code)        "Demand Class"
       ,
       (SELECT meaning
        FROM   OE_LOOKUPS
        WHERE  lookup_type = ''SCHEDULING_LEVEL''
               AND lookup_code = otta.scheduling_level_code
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Scheduling Level",
       Decode(otta.inspection_required_flag, ''Y'', ''Yes'',
                                             ''N'', ''No'')
       "Inspection Required",
       --       decode(otta.BILL_ONLY,
       --              ''Y'', ''Yes'',
       --              ''N'', ''No'')  "Bill Only",
       (SELECT NAME
        FROM   RA_RULES
        WHERE  type = ''I''
               AND status = ''A''
               AND rule_id = otta.invoicing_rule_id)
       "Invoicing Rule",
       (SELECT NAME
        FROM   RA_RULES
        WHERE  status = ''A''
               AND type IN ( ''A'', ''ACC_DUR'', ''PP_DR_ALL'', ''PP_DR_PP'' )
               AND rule_id = otta.accounting_rule_id)
       "Accounting Rule",
       (SELECT NAME
        FROM   RA_BATCH_SOURCES_ALL
        WHERE  batch_source_id = otta.invoice_source_id
               AND org_id = otta.org_id
               AND status = ''A''
               AND sysdate BETWEEN Nvl(start_date, sysdate) AND
                                   Nvl(end_date, sysdate))
                                     "Invoice Source",
       (SELECT NAME
        FROM   RA_BATCH_SOURCES_ALL
        WHERE  batch_source_id = otta.non_delivery_invoice_source_id)
       "Non Delivery Invoice Source",
       (SELECT meaning
        FROM   FND_LOOKUP_VALUES
        WHERE  view_application_id = 222
               AND lookup_type = ''CREDIT_METHOD_FOR_RULES''
               AND language = ''US''
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate)
               AND lookup_code = otta.accounting_credit_method_code)
       "Credit Method: Accounting",
       (SELECT meaning
        FROM   FND_LOOKUP_VALUES
        WHERE  view_application_id = 222
               AND lookup_type = ''CREDIT_METHOD_FOR_RULES''
               AND language = ''US''
               AND enabled_flag = ''Y''
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate)
               AND lookup_code = otta.invoicing_credit_method_code)
       "Credit Method: Invoicing",
       (SELECT NAME
        FROM   RA_CUST_TRX_TYPES_ALL
        WHERE  org_id = otta.org_id
               AND cust_trx_type_id = otta.cust_trx_type_id
               AND sysdate BETWEEN Nvl(start_date, sysdate) AND
                                   Nvl(end_date, sysdate))
                                     "Receivables Transaction Type",
       (SELECT concatenated_segments
        FROM   GL_CODE_COMBINATIONS_KFV gcc
        WHERE  otta.cost_of_goods_sold_account = gcc.code_combination_id
               AND sysdate BETWEEN Nvl(start_date_active, sysdate) AND
                                   Nvl(end_date_active, sysdate))
       "Cost of Goods Sold Account"
FROM   OE_TRANSACTION_TYPES_ALL otta
WHERE  otta.transaction_type_id IN (SELECT DISTINCT lin.line_type_id
                                    FROM   OE_ORDER_LINES_ALL lin
                                    WHERE  LIN.header_id = ##$$HEADERID$$##
                                           AND Nvl(''##$$LINEID$$##'', 0) IN
                                                   ( 0, LIN.line_id,
                                                     LIN.top_model_line_id,
                                                     LIN.ato_line_id,
LIN.link_to_line_id,
LIN.service_reference_line_id ))
ORDER  BY 1  ',
      p_title                  => 'Order Line - Transaction Type',
