                                             2, ''Yes'') "Revision Control",
       decode(msi.reservable_type, 1, ''Yes'',
                                   2, ''No'') "Reservable",
       decode(msi.lot_control_code, 1, ''No Control'',
                                    2, ''Full Control'') "Lot Control",
       decode(msi.serial_number_control_code, 1, ''No Control'',
                                              5, ''At Receipt'',
                                              6, ''At Sales Order Issue'',
                                              2, ''Predefined'') "Serial Generation",
       msi.grade_control_flag "Grade Controlled",
       decode(msi.location_control_code, 1, ''No Control'',
                                         2, ''Prespecified'',
                                         3, ''Dynamic Entry'') "Locator Control",
       decode(msi.restrict_subinventories_code, 1, ''Yes'',
                                                2, ''No'') "Restrict Subinventories",
       decode(msi.restrict_locators_code, 1, ''Yes'',
                                          2, ''No'') "Restrict Locators",
       msi.lot_status_enabled "Lot Status Enabled",
