	   msi.bom_item_type||'': ''||
       (SELECT meaning
        FROM   fnd_lookup_values flv1
        WHERE  lookup_type = ''BOM_ITEM_TYPE''
               AND lookup_code = msi.bom_item_type
               AND language = ''US'') "BOM Item Type",
       msi.purchasing_item_flag "Purchased",
       msi.purchasing_enabled_flag "Purchasable",
       msi.list_price_per_unit "List Price",
