       msi.pick_components_flag "Pick Components",
       msi.replenish_to_order_flag "Assemble to Order",
       msi.ship_model_complete_flag "Ship Model Complete",
       msi.returnable_flag "Returnable",
       decode(msi.return_inspection_requirement, 1, ''Yes'',
                                                 2, ''No'') "RMA Inspection Required",
       msi.atp_flag "Check ATP",
       msi.picking_rule_id "Picking Rule ID",
       msi.default_shipping_org||'': ''||
