debug('begin add_signature: SALES_ORDER_SALES_CREDITS_LINE');
   l_info('##MASK##SALESREP'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '20321',
      p_sig_id                 => 'SALES_ORDER_SALES_CREDITS_LINE',
      p_sig_sql                => 'SELECT osc.line_id "Line ID",
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line #",
       osc.salesrep_id "Salesrep ID",
       ( SELECT name
           FROM jtf_rs_salesreps jrs
          WHERE jrs.salesrep_id = osc.salesrep_id
            AND sysdate between nvl(jrs.start_date_active, sysdate)
            AND nvl(jrs.end_date_active, sysdate)
            AND rownum=1 ) "Salesrep",
       osc.sales_credit_type_id "Sales Credit ID",
       nvl(( SELECT osct.name
               FROM oe_sales_credit_types osct
              WHERE osct.sales_credit_type_id = osc.sales_credit_type_id), osc.sales_credit_type_id) "Sales Credit",
       osc.sales_group_id "Sales Group ID",
       nvl(( SELECT group_name
               FROM jtf_rs_groups_tl
              WHERE group_id = sales_group_id
                AND language = ''US''), sales_group_id) "Group Name",
       osc.percent "Percent"
  FROM oe_sales_credits osc,
       oe_order_lines_all lin
 WHERE osc.header_id = ##$$HEADERID$$##    
   AND osc.line_id is not null
   AND NVL(''##$$LINEID$$##'',0) in (0, osc.LINE_ID)
   AND osc.line_id = lin.line_id
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Credits - Line Level',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no sales credits - line level.',
      p_solution               => 'Sales Credits exist at the line level.  If no Sales Credits at either Order nor Line refer to [726030/KB757900].',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_SALES_CREDITS_LINE');



