       lin.line_id "Line ID",
       ( SELECT meaning
             FROM oe_lookups
          WHERE lookup_type = ''LINE_FLOW_STATUS''
            AND lookup_code = lin.flow_status_code ) "Status",
       decode(nvl(lin.revrec_implicit_flag, ''N''),
              ''Y'', ''Implicit'',
              ''N'', ''Explicit'') "Revenue Recognition Acceptance",
       lin.contingency_id "Contigency ID",
       adr.contingency_name "Contigency Name",
