      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_PRE_OR_POST_BILLING_REVENUE_CONTINGENCY');



