      p_sig_repo_id            => '947',
      p_sig_id                 => 'SALES_ORDER_LINE_HOLDS',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line #",
       hld.line_id        "Line ID",
       hld.order_hold_id  "Order Hold ID",
       hdf.name           "Hold Name",
       ( SELECT meaning FROM oe_lookups WHERE lookup_type = ''HOLD_TYPE'' AND lookup_code = hdf.type_code ) "Hold Type",
       ( SELECT display_name FROM wf_item_types_vl WHERE name = hdf.item_type ) "Workflow Item",
       ( SELECT meaning FROM oe_lookups 
	     WHERE lookup_type = decode(hdf.item_type, ''OEOH'', ''HOLDABLE_HEADER_ACTIVITIES'', ''OEOL'', ''HOLDABLE_LINE_ACTIVITIES'')
           AND lookup_code = hdf.activity_name
           AND enabled_flag = ''Y''
           AND trunc(sysdate) BETWEEN nvl(start_date_active, trunc(sysdate)) AND nvl(end_date_active, trunc(sysdate)) ) "Workflow Activity",
hsr.hold_source_id "Hold Source ID",
       ( SELECT meaning FROM oe_lookups WHERE lookup_type = ''HOLD_ENTITY_DESC'' AND lookup_code = hsr.hold_entity_code ) "Hold Entity",
       hsr.hold_entity_id   "Hold Entity ID",
       --( SELECT meaning FROM oe_lookups WHERE lookup_type = ''HOLD_ENTITY_DESC'' AND lookup_code = hsr.hold_entity_code2) "Hold Entity 2",
       --hsr.hold_entity_id2  "Hold Entity ID 2",
       hsr.hold_until_date  "Hold Until",
       hld.creation_date    "Applied Date",
       ( SELECT user_name FROM fnd_user WHERE user_id = hld.created_by ) "Applied By",
       hsr.hold_comment   "Hold Comment",
       hld.released_flag  "Hold Released",
       hsr.released_flag  "Hold Source Released",
       ( SELECT meaning FROM oe_lookups WHERE lookup_type = ''RELEASE_REASON'' AND lookup_code = hrl.release_reason_code ) "Release Reason",
       hrl.creation_date    "Released Date",
       ( SELECT user_name FROM fnd_user WHERE user_id = hrl.created_by ) "Released By",
       hrl.release_comment  "Release Comment",
	   hdf.hold_included_items_flag "Hold Included Items",
       hdf.progress_wf_on_release_flag "Progress WF on Release"
FROM oe_order_holds_all  hld,
     oe_hold_sources_all hsr,
     oe_hold_definitions hdf,
     oe_hold_releases    hrl,
     oe_order_lines_all  lin
WHERE 
      lin.header_id = ##$$HEADERID$$##
      AND NVL(''##$$LINEID$$##'',0) in (0,lin.line_id,
                                      lin.top_model_line_id,
                                      lin.ato_line_id,
                                      lin.link_to_line_id,
                                      lin.reference_line_id,
                                      lin.service_reference_line_id)
      AND hld.header_id = lin.header_id
      AND hld.line_id = lin.line_id
      AND hld.line_id IS NOT NULL
      AND hld.hold_source_id = hsr.hold_source_id
      AND hsr.hold_id = hdf.hold_id
      AND hld.hold_release_id = hrl.hold_release_id (+)
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1),
         hld.creation_date, 
         hrl.creation_date',
      p_title                  => 'Line Specific Holds',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no line specific holds.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '19'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_HOLDS');



debug('begin add_signature: SALES_ORDER_LINE_PROCESS_MESSAGES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '948',
      p_sig_id                 => 'SALES_ORDER_LINE_PROCESS_MESSAGES',
      p_sig_sql                => 'select 
   om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
   MSG.line_id                                         "Line ID",
   MSG.header_id                                       "Header ID",
   decode(MSG.MESSAGE_SOURCE_CODE,
               ''U'',''U=On-Line(UI)'',
               ''C'',''C=Conc Process'',
               ''W'',''W=Workflow'',
               MSG.MESSAGE_SOURCE_CODE)                     "Message Source",
        MSG.PROCESS_ACTIVITY        "Process Activity",       
        MSG.request_id              "Request ID",
        MST.message_text                                    "Message Text"
 from oe_processing_msgs_vl     MSG,
      oe_processing_msgs_tl     MST,
      oe_order_lines_all        LIN,
      fnd_languages             FLA
 where  MSG.header_id    = ##$$HEADERID$$##
   and  MSG.HEADER_ID      = LIN.HEADER_ID
   and  msg.transaction_id = mst.transaction_id
   and  MST.LANGUAGE                  = FLA.LANGUAGE_CODE 
   and  FLA.INSTALLED_FLAG            = ''B'' 
   and  MSG.LINE_ID        = LIN.LINE_ID
   and  MSG.LINE_ID        is not NULL
   and  NVL(''##$$LINEID$$##'',0)  in (0,LIN.LINE_ID,
                                            LIN.TOP_MODEL_LINE_ID,
                                            LIN.ATO_LINE_ID,
                                            LIN.LINK_TO_LINE_ID,
                                            LIN.SERVICE_REFERENCE_LINE_ID)
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Sales Order Line Process Messages',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There are no sales order line process messages.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_PROCESS_MESSAGES');



