debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_WF_PEND_ACCEPT_CONTIGNCY_ACCEPTED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24084',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_WF_PEND_ACCEPT_CONTIGNCY_ACCEPTED',
      p_sig_sql                => 'select ol.line_id "Line ID",
om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line Number",
ol.invoice_interface_status_code "Invoice Interface Status",
ol.revrec_signature_date "Accepted or Rejected Date"
from oe_order_lines_all ol
where ol.header_id = ##$$HEADERID$$##
and    NVL(''##$$LINEID$$##'',0) in (0, ol.LINE_ID, ol.TOP_MODEL_LINE_ID, ol.ATO_LINE_ID, ol.LINK_TO_LINE_ID, ol.SERVICE_REFERENCE_LINE_ID)
and    ol.open_flag									= ''Y''
and    ol.ordered_quantity							> 0
and    nvl(ol.shipping_interfaced_flag,''N'')			= ''Y''
and    ol.flow_status_code							= ''PRE-BILLING_ACCEPTANCE''
and    nvl(ol.shipped_quantity,0)					= ol.ordered_quantity
and    ol.item_type_code							= ''STANDARD''
and    nvl(ol.fulfilled_flag,''N'')					= ''Y''
and    nvl(ol.fulfilled_quantity,0)					= ol.shipped_quantity
and    nvl(ol.invoice_interface_status_code, ''N'')	= ''ACCEPTANCE-PENDING''
and    nvl(ol.invoiced_quantity, 0)					= 0
and    ol.actual_shipment_date              IS NOT NULL
and    NVL(ol.accepted_quantity, 0)  > 0
and    ol.contingency_id                         IS NOT NULL
and    ol.revrec_event_code                  = ''INVOICING''               
and    exists (SELECT 1
                    FROM   wf_item_activity_statuses s,
                           wf_process_activities       p
                    WHERE  s.process_activity = p.instance_id
                    AND    s.item_type        = ''OEOL''
                    AND    s.item_key         = TO_CHAR(ol.line_id)
                    AND    p.activity_name    = ''INVOICE_INTERFACE''
                    AND    p.process_name     = ''LINE_INVOICE_INTERFACE_SUB''
					AND    s.activity_status  = ''COMPLETE''
                    AND   s.activity_result_code = ''PENDING_ACCEPTANCE''
                    AND    s.end_date is NOT NULL)
and	exists (SELECT 1 from wsh_delivery_details wdd
			WHERE	wdd.source_code					= ''OE''
			AND	wdd.source_line_id					= ol.line_id
			AND	wdd.released_status					= ''C''
			AND	nvl(wdd.oe_interfaced_flag,''N'')		= ''Y''
			AND	nvl(wdd.inv_interfaced_flag,''N'')	= ''Y''
			AND	nvl(wdd.shipped_quantity,0)			> 0
			and	exists 
				(SELECT 1 from mtl_material_transactions trn 
				WHERE	trn.trx_source_line_id	= wdd.source_line_id
				AND	trn.transaction_type_id		= 33
				AND trn.picking_line_id			= wdd.delivery_detail_id))',
      p_title                  => 'Line is Pending Revenue Contingency Acceptance but Acceptance has Occurred',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Line workflow is Pending Acceptance even though Acceptance has already occurred.  ',
      p_solution               => 'Log a service request with Order Management to review issue for a possible data fix.  Refer to [2385646/KB735097].',
      p_success_msg            => 'Pre or Post Billing (Revenue Contingency).  Refer to [863454/KB737882] for Customer Acceptance details.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_WF_PEND_ACCEPT_CONTIGNCY_ACCEPTED');



debug('begin add_signature: SALES_ORDER_LINES_OPEN_AND_CANCELLED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1668',
      p_sig_id                 => 'SALES_ORDER_LINES_OPEN_AND_CANCELLED',
      p_sig_sql                => 'SELECT lin.header_id "Header ID",
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       lin.open_flag "Open Flag",
       lin.cancelled_flag "Cancelled Flag",
       substr(lin.flow_status_code, 1, 22) "Workflow Status",
       nvl(lin.ordered_quantity, 0) "Ordered Qty",
       nvl(lin.shipped_quantity, 0) "Shipped Qty",
       nvl(fulfilled_quantity, 0) "Fulfilled Qty",
       nvl(lin.cancelled_quantity, 0) "Cancelled Qty"
  FROM oe_order_lines_all lin,
       oe_order_headers_all ord
 WHERE lin.header_id = ##$$HEADERID$$##
   AND ord.header_id = lin.header_id
   AND lin.open_flag = ''Y''
   AND lin.cancelled_flag = ''Y''
  AND NVL(lin.ordered_quantity,0) = 0
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id )
 ORDER BY lin.line_number,
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.component_number, - 1),
          nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Lines both Open and Cancelled',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Cancelled line(s) shown as open are an invalid status.  Once a line is Cancelled, it progresses to Closed.  Lines cannot be both open and cancelled, they should be open OR cancelled.  ',
      p_solution               => 'Refer to [2659146/KB737164] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_OPEN_AND_CANCELLED');



