  FROM oe_order_lines_all l,
       oe_order_headers_all h
 WHERE h.header_id = ##$$HEADERID$$##
   AND l.header_id = ##$$HEADERID$$##
   AND ( l.open_flag = ''Y''
   AND nvl(l.cancelled_flag, ''N'') = ''N'' )
   AND h.transaction_phase_code = ''F''
   AND NOT EXISTS (
  SELECT 1
    FROM wf_items itm
   WHERE itm.item_type = ''OEOL''
     AND itm.item_key = to_char(l.line_id) )
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, l.line_id, l.top_model_line_id, l.ato_line_id, l.link_to_line_id, l.service_reference_line_id )
 ORDER BY l.line_number,
          nvl(l.shipment_number, - 1),
          nvl(l.option_number, - 1),
          nvl(l.component_number, - 1),
          nvl(l.service_number, - 1)     ',
      p_title                  => 'Sales Order Lines with No Associated Workflow',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Open order line(s) exist with no associated workflow.  Open lines must have workflow in order for them to progress.',
      p_solution               => 'Refer to [2200940/KB769001] for details.',
      p_success_msg            => 'All open lines have an associated workflow.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '17'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_NO_WORKFLOW');



debug('begin add_signature: SALES_ORDER_LINE_NO_WF_ASSIGNMENT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12068',
      p_sig_id                 => 'SALES_ORDER_LINE_NO_WF_ASSIGNMENT',
      p_sig_sql                => 'SELECT 
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
       substr(lin.line_id, 1, 15) "Line ID",
       lin.item_type_code         "Item Type Code",
       lin.line_type_id           "Line Type ID",
       vl.name                    "Line Type"
FROM   oe_order_lines_all lin,
       oe_order_headers_all hed,
       oe_transaction_types_vl vl
WHERE  lin.header_id = ##$$HEADERID$$##
       AND NVL(''##$$LINEID$$##'',0)    in (0,lin.LINE_ID,
                                         lin.TOP_MODEL_LINE_ID,
                                         lin.ATO_LINE_ID,
                                         lin.LINK_TO_LINE_ID,
                                         lin.SERVICE_REFERENCE_LINE_ID)
       AND lin.line_type_id = vl.transaction_type_id
       AND lin.option_number IS NULL
       AND lin.item_type_code <> ''INCLUDED''
       AND lin.header_id = hed.header_id
       AND NOT EXISTS (SELECT 1
                       FROM   oe_workflow_assignments owa
                       WHERE  hed.order_type_id = owa.order_type_id
                              AND lin.line_type_id = owa.line_type_id
                              AND lin.item_type_code = nvl(owa.item_type_code, lin.item_type_code)
                              AND SYSDATE BETWEEN owa.start_date_active AND nvl(owa.end_date_active, SYSDATE))
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Sales Order Lines with no Transaction Type Workflow Assignment',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Based on [388233/KB757400]. The line(s) do not have a Transaction Type Workflow Assignment.
This will cause the line(s) to stop processing and not progress to Closure.

',
      p_solution               => 'Refer to [388233/KB757400]
On Transaction Type window, query the Transaction Type, select <b>Click Assign Line Flows</b>
Assign workflow based on Line Type & Item Type.
If you leave Item Type blank, the workflow applies to all item types for the line type.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_NO_WF_ASSIGNMENT');



debug('begin add_signature: SALES_ORDER_LINES_STUCK_AWAITING_RETURN_DISPOSITION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15138',
      p_sig_id                 => 'SALES_ORDER_LINES_STUCK_AWAITING_RETURN_DISPOSITION',
      p_sig_sql                => 'SELECT 
   om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
   LIN.line_id "Line ID",
substr(LIN.flow_status_code, 1, 22) "Workflow Status"
FROM oe_order_lines_all LIN
WHERE LIN.header_id = ##$$HEADERID$$##
and NVL(''##$$LINEID$$##'',0) in 
(0,
LIN.LINE_ID,
LIN.TOP_MODEL_LINE_ID,
LIN.ATO_LINE_ID,
LIN.LINK_TO_LINE_ID,
LIN.SERVICE_REFERENCE_LINE_ID)
AND LIN.line_category_code = ''RETURN''
AND LIN.flow_status_code = ''AWAITING_RETURN_DISPOSITION''
AND exists (select ''x''
            from   mtl_material_transactions MMT, rcv_transactions RCV
            where  MMT.trx_source_line_id = LIN.line_id
            and    MMT.transaction_type_id = 15
            and    RCV.oe_order_line_id   = LIN.line_id
            and    MMT.rcv_transaction_id = RCV.transaction_id)
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Sales Order Lines Stuck in Awaiting Return Disposition',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This shows the return line(s) stuck in status "Awaiting Return Disposition", even the item is received in the organization.
RMA order line status should be closed after receiving.',
      p_solution               => 'Refer to [2112848/KB712115] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_STUCK_AWAITING_RETURN_DISPOSITION');



debug('begin add_signature: SALES_ORDER_SUSPENDED_WORKFLOW');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14119',
      p_sig_id                 => 'SALES_ORDER_SUSPENDED_WORKFLOW',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(oel.line_number, oel.shipment_number, oel.option_number, oel.component_number, oel.service_number) "Line",
       oel.line_id "Line ID",
       oel.flow_status_code "Status"
  FROM oe_order_lines_all oel,
       oe_order_headers_all oeh
 WHERE oel.header_id = oeh.header_id
   AND oeh.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, oel.line_id, oel.top_model_line_id, oel.ato_line_id, oel.link_to_line_id, oel.service_reference_line_id )
   AND oel.flow_status_code = ''SHIPPED''
   AND oel.line_id IN (
  SELECT wf1.item_key
    FROM wf_item_activity_statuses wf1, wf_process_activities wf2
   WHERE wf1.item_type = ''OEOL''
     AND wf1.activity_status = ''SUSPEND''
     AND wf1.process_activity = wf2.instance_id
     AND wf2.process_name = ''SHIP_CONFIRM''
     AND wf2.activity_name = ''SHIP_LINE'' )
ORDER BY oel.line_number,
          nvl(oel.shipment_number, - 1),
          nvl(oel.option_number, - 1),
          nvl(oel.component_number, - 1),
          nvl(oel.service_number, - 1)          ',
      p_title                  => 'Order Line Stuck in SHIPPED Status. Line Workflow Suspended',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order has a stuck line that shows flow code = SHIPPED.
Shipped Quantity is updated but Fulfilled and Invoiced Qty = 0.
Unable to progress the line and cannot invoice the customer.
',
      p_solution               => 'Refer to  [1574598/KB753913] for solution.
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_SUSPENDED_WORKFLOW');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_SUPPLY_ELIGIBLE_AFTER_PR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22829',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_SUPPLY_ELIGIBLE_AFTER_PR',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''LINE_FLOW_STATUS''
               AND lookup_code = lin.flow_status_code )   "Status",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''LINE_CATEGORY''
               AND lookup_code = lin.line_category_code ) "Line Category",
       lin.ordered_item "Ordered Item",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''ITEM_TYPE''
           AND lookup_code = lin.item_type_code ) "Item Type",
	   nvl(lin.ordered_quantity, 0)   "Ordered Qty",
       lin.order_quantity_uom         "UOM"
