debug('begin add_signature: EBS_MFG_OM_SALES_ORDER_LINE_AWAITING_RETURN_DISP_INV_DLVD');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26453',
      p_sig_id                 => 'EBS_MFG_OM_SALES_ORDER_LINE_AWAITING_RETURN_DISP_INV_DLVD',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line Number",
       ol.line_id "Line ID",
       ol.flow_status_code "Status",
       ol.ordered_quantity "Ordered Qty",
       ol.shipped_quantity "Shipped Qty",
       rcv.quantity "Received Qty",
       mmt.transaction_date "Received Date"
  FROM oe_order_headers_all oh,
       oe_order_lines_all ol,
       rcv_transactions rcv,
       mtl_material_transactions mmt
 WHERE ol.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, ol.line_id, ol.top_model_line_id, ol.ato_line_id, ol.link_to_line_id, ol.service_reference_line_id )
   AND oh.header_id = ol.header_id
   AND ol.line_id = rcv.oe_order_line_id
   AND ol.line_id = mmt.trx_source_line_id
   AND mmt.transaction_type_id = 15
   AND mmt.rcv_transaction_id = rcv.transaction_id
   AND nvl(shipped_quantity, 0) = nvl(ordered_quantity, 0)
   AND nvl(fulfilled_quantity, 0) = nvl(shipped_quantity, 0)
   AND ol.flow_status_code = ''AWAITING_RETURN_DISPOSITION''
   AND EXISTS (
  SELECT 1
    FROM wf_item_activity_statuses st,
         wf_process_activities wpa
   WHERE wpa.instance_id = st.process_activity
     AND st.item_type = ''OEOL''
     AND wpa.activity_name = ''RMA_WAIT_FOR_INSPECTION''
     AND st.end_date IS NULL
     AND st.item_key = to_char(ol.line_id) )
 ORDER BY ol.line_number,
          nvl(ol.shipment_number, - 1),
          nvl(ol.option_number, - 1),
          nvl(ol.component_number, - 1),
          nvl(ol.service_number, - 1)  ',
      p_title                  => 'RMA Line is stuck in AWAITING_RETURN_DISPOSITION Status Though It Is Delivered Into Inventory',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Find an RMA Line is stuck in AWAITING_RETURN_DISPOSITION status though the line is delivered into inventory.<br>
Line workflow is stuck at AWAITING_INSPECTION with Notified status.',
      p_solution               => 'Refer to [1376263/KB774185] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_SALES_ORDER_LINE_AWAITING_RETURN_DISP_INV_DLVD');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_POSHIPMENT_SOLINE_LINKNOTREMOVED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27069',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_POSHIPMENT_SOLINE_LINKNOTREMOVED',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(ool.line_number, ool.shipment_number, ool.option_number, ool.component_number, ool.service_number) "Line",
       ool.line_id "Line ID"
  FROM oe_order_lines_all ool
 WHERE ool.source_type_code = ''EXTERNAL''
   AND ool.flow_status_code = ''AWAITING_RECEIPT''
   AND ool.open_flag = ''Y''
   AND nvl(ool.shipping_quantity, 0) = 0
   AND nvl(ool.shipped_quantity, 0) = 0
   AND nvl(ool.fulfilled_quantity, 0) = 0
   AND EXISTS (
  SELECT 1
    FROM oe_drop_ship_sources odss
   WHERE odss.line_id = ool.line_id
     AND EXISTS (
    SELECT 1
      FROM po_lines_all pl
     WHERE pl.po_line_id = odss.po_line_id
       AND ( pl.cancel_flag = ''Y''
       AND pl.cancel_date IS NOT NULL
       AND pl.closed_code = ''CLOSED''
        OR pl.quantity = 0 ) ) 
        )
    AND ool.header_id = ##$$HEADERID$$##
    AND NVL(''##$$LINEID$$##'',0) in (0, ool.LINE_ID, ool.TOP_MODEL_LINE_ID, ool.ATO_LINE_ID, ool.LINK_TO_LINE_ID, ool.SERVICE_REFERENCE_LINE_ID)
ORDER BY ool.line_number,
         nvl(ool.shipment_number, - 1),
         nvl(ool.option_number, - 1),
         nvl(ool.component_number, - 1),
         nvl(ool.service_number, - 1)		
',
      p_title                  => 'Link between PO Shipment and SO Line is not removed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'On cancelling Dropship Purchase Order (PO) Shipment, Order Management (OM) API OE_DROP_SHIP_GRP.Update_Drop_Ship_links is called to remove the PO shipment – Sales Order ( SO) line link from OE_DROP_SHIP_SOURCES.
Due to data corruption or code issue in previous file versions link between PO Shipment and SO Line is not removed.',
      p_solution               => 'Refer to [2759614/KB714068] for details',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_POSHIPMENT_SOLINE_LINKNOTREMOVED');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_INCORRECT_HIST_TYPE_CODE');
