debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_DROPSHIP_SALES_ORDER_LINE_STUCK_BOOKED_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27167',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_DROPSHIP_SALES_ORDER_LINE_STUCK_BOOKED_STATUS',
      p_sig_sql                => 'SELECT ooh.order_number "Order Number",
     om_order_analyzer_pkg.line_shipment_option( ool.line_number,  ool.shipment_number,  ool.option_number,  ool.component_number, ool.service_number) "Line Number",
     ool.line_id "Line ID",
     ool.flow_status_code "Flow Status Code",
     ool.source_type_code "Source Type Code",
    ool.ordered_item "Ordered Item",
    ods.requisition_header_id "Req Header ID",
    ods.requisition_line_id "Req Line ID",
    ods.po_header_id "PO Header ID",
    ods.po_line_id "PO Line ID",
    ods.line_location_id "Line Location ID"
FROM oe_drop_ship_sources    ods,
     oe_order_lines_all      ool,
     oe_order_headers_all    ooh
WHERE ool.header_id = ##$$HEADERID$$##
    AND    nvl(''##$$LINEID$$##'',0) IN (0,
                                   ool.line_id,
                                   ool.top_model_line_id,
                                   ool.ato_line_id,
                                   ool.link_to_line_id,
                                   ool.service_reference_line_id)
    AND ods.line_id = ool.line_id
    AND ool.header_id = ooh.header_id
	AND ool.org_id = ooh.org_id
    AND ool.source_type_code = ''EXTERNAL''
    AND ool.flow_status_code = ''BOOKED''
    AND ool.booked_flag = ''Y''
    AND ool.open_flag = ''Y''
    AND nvl(ool.cancelled_flag, ''N'') = ''N''
    AND nvl(ool.shipped_quantity, 0) = 0
    AND ods.po_header_id IS NOT NULL
	AND ods.po_line_id IS NOT NULL
    AND EXISTS (SELECT 1
                         FROM po_headers_all poh, po_lines_all pll 
                         WHERE poh.po_header_id = ods.po_header_id
						     AND poh.po_header_id = pll.po_header_id
                             AND poh.org_id = pll.org_id
                             AND pll.po_line_id = ods.po_line_id
                             AND NVL(poh.cancel_flag,''N'')= ''N''
                             AND poh.closed_code = ''OPEN'')',
      p_title                  => 'Dropship Order Lines Stuck In Booked Status Even Though PO Is In Open Status',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Drop Ship Sales Order Line status is Booked while there exists an open Purchase order against it',
      p_solution               => 'Refer to [2735093/KB766392]',
      p_success_msg            => 'Drop Ship Order Line are in correct status',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_DROPSHIP_SALES_ORDER_LINE_STUCK_BOOKED_STATUS');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_COMP_SALES_ORDER_LINE_STUCK_FULFILLED_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27239',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_COMP_SALES_ORDER_LINE_STUCK_FULFILLED_STATUS',
      p_sig_sql                => 'Select lin.line_id                          "Line Id",
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number,lin.service_number) "Line",
       lin.top_model_line_id                "Top Model Line Id",
	   lin.link_to_line_id                  "Link To Line Id",
	   lin.invoice_interface_status_code    "Invoice Interface Status",
	   lin.item_type_code                   "Item Type Code",
	   lin.flow_status_code                 "Line Status"
from oe_order_lines_all lin
where 1=1
and lin.header_id = ##$$HEADERID$$##
AND    nvl(''##$$LINEID$$##'',0) IN (0,
                                   lin.line_id,
                                   lin.top_model_line_id,
                                   lin.ato_line_id,
                                   lin.link_to_line_id,
                                   lin.service_reference_line_id)
and Upper(lin.flow_status_code) =''FULFILLED''
and lin.open_flag =''Y''
and lin.item_type_code in (''CLASS'',''OPTION'',''INCLUDED'')
and exists (  --Check if Corresponding MODEL and KIT is CLOSED
 Select 1
 from oe_order_lines_all ol2
 where ol2.line_id = lin.top_model_line_id
 and ol2.open_flag =''N''
and ol2.item_type_code in (''MODEL'',''KIT'')
 and upper(ol2.flow_status_code) =''CLOSED''
)
and exists
(
Select 1
from oe_line_sets ols
where ols.line_id =lin.line_id
)',
