debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_RECEIVING_RMA_VIA_MOBILE_DEVICE_ERROR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27511',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_RECEIVING_RMA_VIA_MOBILE_DEVICE_ERROR',
      p_sig_sql                => 'SELECT 
   om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
   LIN.line_id "Line ID",
substr(LIN.flow_status_code, 1, 22) "Workflow Status"
FROM oe_order_lines_all LIN
WHERE LIN.header_id = ##$$HEADERID$$##
and NVL(''##$$LINEID$$##'',0) in 
(0,
LIN.LINE_ID,
LIN.TOP_MODEL_LINE_ID,
LIN.ATO_LINE_ID,
LIN.LINK_TO_LINE_ID,
LIN.SERVICE_REFERENCE_LINE_ID)
AND LIN.line_category_code = ''RETURN''
AND LIN.booked_flag = ''Y''
AND LIN.ordered_quantity > nvl(LIN.shipped_quantity, 0)
AND ( trunc(sysdate) >= nvl(trunc(LIN.earliest_acceptable_date), trunc(sysdate)) )
AND ( trunc(sysdate) <= trunc(LIN.latest_acceptable_date) )
AND LIN.latest_acceptable_date is NOT NULL
AND LIN.flow_status_code = ''AWAITING_RETURN''
AND ( NULL IS NULL
OR ( NULL = - 9999 AND LIN.project_id IS NULL )
OR ( LIN.project_id IS NULL ) )
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Receiving RMA Via Mobile Device ERROR ',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Return line(s) that are stuck while attempting to receive RMA via mobile device',
      p_solution               => 'Refer To [1295666/KB756566] to determine why the Return line(s)  throws error while receiving RMA via mobile device',
      p_success_msg            => 'Receiving RMA Via Mobile Device Is successful',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_RECEIVING_RMA_VIA_MOBILE_DEVICE_ERROR');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_SALES_ORDER_SHIPPED_INVOICED_BUT_NO_SO_ISSUE_TXN_CREATED');
