      p_sig_sql                => 'SELECT ooh.header_id "Header ID",
       ooh.order_number "Order Number",
       om_order_analyzer_pkg.line_shipment_option(ool.line_number, ool.shipment_number, ool.option_number, ool.component_number, ool.service_number) "SO Line",
       ool.line_id "Line ID"
  FROM oe_workflow_assignments owa,
       oe_order_lines_all ool,
       oe_order_headers_all ooh
 WHERE ooh.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, ool.line_id, ool.top_model_line_id, ool.ato_line_id, ool.link_to_line_id, ool.reference_line_id, ool.service_reference_line_id )
