   AND ool.line_type_id = owa.line_type_id
   AND ool.header_id = ooh.header_id
   AND ooh.order_type_id = owa.order_type_id
   AND ool.open_flag = ''N''
   AND ool.flow_status_code <> ''CANCELLED''
   AND nvl(ool.cancelled_flag, ''N'') <> ''Y''
   AND NOT EXISTS (
  SELECT 1
    FROM mtl_material_transactions
   WHERE trx_source_line_id = ool.line_id
     AND transaction_source_type_id = 2 )
