      p_sig_sql                => 'SELECT ooh.order_number "Order Number",
ool.header_id "Header ID",
om_order_analyzer_pkg.line_shipment_option( ool.line_number, ool.shipment_number, ool.option_number, ool.component_number, ool.service_number) "Line Number",
ool.line_id "Line ID", 
msib.segment1 "Item Name",
(SELECT meaning
FROM fnd_lookup_values flv1
WHERE lookup_type = ''ITEM_TYPE''
AND lookup_code = msib.item_type
AND language = ''US'') "Item Type",
(SELECT meaning
FROM fnd_lookup_values flv1
WHERE lookup_type = ''BOM_ITEM_TYPE''
AND lookup_code = msib.bom_item_type
AND language = ''US'') "BOM Item Type"
FROM oe_order_lines_all ool,
oe_order_headers_all ooh,
mtl_system_items_b msib
WHERE ool.header_id = ##$$HEADERID$$##
 AND nvl(''##$$LINEID$$##'',0) IN (0,
                                   ool.line_id,
                                   ool.top_model_line_id,
                                   ool.ato_line_id,
                                   ool.link_to_line_id,
                                   ool.service_reference_line_id)
AND ool.ship_from_org_id = msib.organization_id
AND ool.inventory_item_id = msib.inventory_item_id
AND ool.flow_status_code = ''AWAITING_SHIPPING''
AND ooh.org_id = ool.org_id
AND ooh.header_id = ool.header_id
AND ool.shipping_interfaced_flag = ''Y''
AND ool.shippable_flag = ''Y''
AND ool.item_type_code = ''MODEL''
AND msib.shippable_item_flag = ''Y''
AND EXISTS (SELECT 1
FROM wsh_delivery_details wdd
WHERE wdd.source_line_id = ool.line_id)',
