debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_POST_BILLING_ACCEPTANCE');
   l_info('##MASK##ACCEPTED BY'):= 'REMOVE_COLUMN';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27525',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_POST_BILLING_ACCEPTANCE',
      p_sig_sql                => 'SELECT oeoh.order_number "Order Number",
       om_order_analyzer_pkg.line_shipment_option(oel.line_number, oel.shipment_number, oel.option_number, oel.component_number, oel.service_number) "Line Number",
       oel.line_id "Line ID", 
