   AND EXISTS ( SELECT 1
                  FROM ra_customer_trx_lines_all rac
                 WHERE rac.interface_line_attribute6 = to_char(oel.line_id)
            AND rac.sales_order = to_char(oeoh.order_number)
            AND rac.interface_line_context = ''ORDER ENTRY''
            AND rac.line_type = ''LINE''
            AND rac.sales_order_line IS NOT NULL)
    AND oel.header_id = ##$$HEADERID$$##
    AND nvl(''##$$LINEID$$##'',0) IN (0, oel.line_id, oel.top_model_line_id, oel.ato_line_id, oel.link_to_line_id, oel.service_reference_line_id) 
    ORDER BY oel.line_id',
