  oe_order_headers_all ord,
  mtl_system_items_b msi,
  ra_customer_trx_lines_all rctl
WHERE
    ord.header_id = ##$$HEADERID$$##
  AND ord.header_id = ol.header_id
  AND NVL(''##$$LINEID$$##'',0) in (0, ol.line_id, ol.top_model_line_id, ol.ato_line_id, ol.link_to_line_id, ol.service_reference_line_id)
  AND   ol.flow_status_code in (''SHIPPED'',''FULFILLED'')
  AND   ol.inventory_item_id = msi.inventory_item_id
  AND   ol.ship_from_org_id = msi.organization_id
  AND   rctl.interface_line_attribute1 = ''##$$ORDERNO$$##''
  AND   rctl.interface_line_attribute6 = ol.line_id
  AND   rctl.line_type = ''LINE''
  AND   rctl.sales_order_line IS NOT NULL
  AND   rctl.interface_line_context = ''ORDER ENTRY''
ORDER BY 1',
      p_title                  => 'Line Invoiced Yet Status Shows Shipped or Fulfilled',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Line Status is in Shipped and/or Fulfilled Status; however, the Line Workflow progressed to Close Line Complete.  This is preventing the Order Header from Closing.',
      p_solution               => 'Log an SR with Oracle Support with this output and request data fix solution from [2811739/KB741092].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONTONESO_INVOICED_YET_STATUS_SHIPPED');



debug('begin add_signature: EBS_MFG_OM_ONT_LINE_ENTERED_SHIPPING_WF_ERR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '32283',
      p_sig_id                 => 'EBS_MFG_OM_ONT_LINE_ENTERED_SHIPPING_WF_ERR',
      p_sig_sql                => 'select oh.order_number "Order Number", 
ol.header_id "Header ID", 
line_id "Line ID",
om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line",
ol.flow_status_code "Line Status Code"
from oe_order_lines_all ol,
oe_order_headers_all oh
where oh.header_id = ##$$HEADERID$$##
and NVL(''##$$LINEID$$##'',0) in (0, ol.LINE_ID, ol.TOP_MODEL_LINE_ID, ol.ATO_LINE_ID, ol.LINK_TO_LINE_ID, ol.SERVICE_REFERENCE_LINE_ID)
and ol.header_id = oh.header_id
and oh.open_flag = ''Y''
and oh.booked_flag =''Y''
and oh.flow_status_code = ''BOOKED''
and ol.open_flag = ''Y''
and ol.booked_flag =''N''
and ol.ordered_quantity > 0
and nvl(ol.shippable_flag,''N'') = ''Y''
and NVL(ol.shipping_interfaced_flag,''Y'') =''N''
and ol.source_type_code = ''INTERNAL''
and exists
(select 1 from wf_process_activities p, wf_item_activity_statuses s
where p.instance_id = s.process_activity
and item_type = ''OEOL''
and item_key = to_char(ol.line_id)
and p.activity_name = ''SHIP_LINE''
and p.process_name = ''SHIP_CONFIRM''
and s.activity_status = ''ERROR''
and s.end_date IS NULL)
and NOT exists
( select 1 from wsh_delivery_details
WHERE source_code = ''OE''
AND source_line_id = ol.line_id)',
      p_title                  => 'Order Line in Entered Status With Ship - Line Workflow Error',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are order line(s) after Booking, where the line status remains in an Entered status and the booked flag = N.

Shipping interface flag = N for the order line(s) and there is no delivery detail created for the order line(s).',
      p_solution               => 'Log an SR and request data fix script from [3010796/KB745499]. ',
      p_success_msg            => 'There are no ENTERED Sales Order Lines with Ship - Line Workflow errors.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_LINE_ENTERED_SHIPPING_WF_ERR');



debug('begin add_signature: SALES_ORDER_LINES_ORD_QTY_NOT_EQUAL_FULFILL_QTY');
