debug('begin add_signature: SALES_ORDER_LINE_AWAITING_RETURN_DISPOSITION_INSPECTION');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15316',
      p_sig_id                 => 'SALES_ORDER_LINE_AWAITING_RETURN_DISPOSITION_INSPECTION',
      p_sig_sql                => 'SELECT 
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
       lin.line_id "Line ID",
       substr(lin.flow_status_code, 1, 22) "Workflow Status",
       nvl(lin.open_flag, ''N'') "Open",
       lin.line_category_code "Line Category"
from   oe_order_lines_all lin,
       mtl_system_items itm,
       mtl_reservations res,
       oe_transaction_types_tl t
WHERE  lin.header_id = ##$$HEADERID$$##
AND    nvl(''##$$LINEID$$##'',0) IN (0,
                                   lin.line_id,
                                   lin.top_model_line_id,
                                   lin.ato_line_id,
                                   lin.link_to_line_id,
                                   lin.service_reference_line_id)
AND    lin.open_flag = ''Y''
AND    lin.line_category_code = ''RETURN''
AND    lin.flow_status_code = ''AWAITING_RETURN_DISPOSITION''
AND    EXISTS
       (
              SELECT 1
              FROM   wf_item_activity_statuses st,
                     wf_process_activities pa
              WHERE  st.process_activity = pa.instance_id
              AND    st.item_type = ''OEOL''
              AND    st.item_key = to_char(lin.line_id)
              AND    pa.activity_name = ''RMA_WAIT_FOR_INSPECTION''
              AND    st.activity_status IN ( ''NOTIFIED'' )
              AND    st.end_date IS NOT NULL)
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Sales Order Lines Stuck in Awaiting Return Disposition Waiting on Inspection',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Return line stuck in AWAITING_RETURN_DISPOSITION status and line workflow status in RMA_WAIT_FOR_INSPECTION Notified status.
',
      p_solution               => 'Refer to [454617/KB765241] for details.
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_AWAITING_RETURN_DISPOSITION_INSPECTION');



debug('begin add_signature: SALES_ORDER_LINE_STUCK_BOOKED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14943',
      p_sig_id                 => 'SALES_ORDER_LINE_STUCK_BOOKED',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line Number",
       l.line_id "Line ID",
       nvl(l.shipped_quantity, 0) "Shipped QTY",
       nvl(l.open_flag, ''N'') "Open",
       l.flow_status_code "Workflow Status"
  FROM oe_order_lines_all l
 WHERE l.flow_status_code = ''BOOKED''
   AND nvl(l.shipped_quantity, 0) = 0
   AND l.open_flag = ''Y''
   AND header_id = ##$$HEADERID$$##
   AND l.shipping_interfaced_flag = ''Y''
   AND EXISTS (
  SELECT 1
    FROM wsh_delivery_details wdd
   WHERE wdd.source_line_id = l.line_id )
   AND EXISTS (
  SELECT 1
    FROM wf_item_activity_statuses wias,
         wf_process_activities wpa
   WHERE item_type = ''OEOL''
     AND item_key = to_char(l.line_id)
     AND wias.process_activity = wpa.instance_id
     AND wpa.activity_name = ''SHIP_LINE''
     AND wias.activity_status = ''NOTIFIED''
     AND wpa.process_name = ''SHIP_CONFIRM'' )
 ORDER BY l.line_number,
          nvl(l.shipment_number, - 1),
          nvl(l.option_number, - 1),
          nvl(l.component_number, - 1),
          nvl(l.service_number, - 1)',
      p_title                  => 'Order Line stuck as Booked',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Order Line(s) are stuck as Booked not Awaiting Shipping',
      p_solution               => '<ul>
<li>Log a Service Request with Oracle Order Management</li>
<li>For more information regarding this issue, review [2173870/KB749639] for instructions and details.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_STUCK_BOOKED');



