debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_RMA_WITH_CREDIT_MEMO_STUCK_IN_FULFILLED_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27382',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_RMA_WITH_CREDIT_MEMO_STUCK_IN_FULFILLED_STATUS',
      p_sig_sql                => 'SELECT  ol.header_id "Header ID", 
        ol.line_id "Line ID", 
        om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line Number"
from oe_order_lines_all ol
WHERE   ol.header_id = ##$$HEADERID$$##
AND    nvl(''##$$LINEID$$##'',0) IN (0,
                                   ol.line_id,
                                   ol.top_model_line_id,
                                   ol.ato_line_id,
                                   ol.link_to_line_id,
                                   ol.service_reference_line_id)
AND ol.open_flag                                  = ''Y''
AND     ol.ordered_quantity                           > 0
AND     ol.flow_status_code                           = ''FULFILLED''
AND     NVL(ol.shippable_flag, ''Y'')                   = ''Y''
AND     NVL(ol.shipping_interfaced_flag, ''Y'')         = ''N''
AND     NVL(ol.shipped_quantity,0)                    = 0
AND     ol.item_type_code                             = ''STANDARD''
AND     ol.line_category_code                         = ''RETURN''
AND     NVL(ol.fulfilled_flag,''N'')                    = ''Y''
AND     NVL(ol.fulfilled_quantity,0)                  = ol.ordered_quantity
AND     NVL(ol.invoice_interface_status_code, ''N'')    = ''N''
AND     NVL(ol.invoiced_quantity, 0)                  = 0
AND     ol.actual_shipment_date                       IS NULL
AND     NOT EXISTS (SELECT 1 FROM wf_items wfi
                                WHERE 1               = 1
                                AND wfi.item_type     = ''OEOL''
                                AND wfi.item_key      = TO_CHAR(ol.line_id)
                                AND wfi.end_date      IS NULL
                               )
AND EXISTS (SELECT 1 FROM ra_interface_lines_all rai
                    WHERE 1                           = 1
                    AND rai.interface_line_attribute6 = TO_CHAR(ol.line_id)
                    AND rai.line_type                 = ''LINE''
                    AND rai.sales_order_line          IS NOT NULL
                    AND rai.interface_line_context    = ''ORDER ENTRY''
  OR EXISTS (SELECT 1 FROM ra_customer_trx_lines_all rctl
                    WHERE 1                            = 1
                    AND rctl.interface_line_attribute6 = TO_CHAR(ol.line_id)
                    AND rctl.line_type                 = ''LINE''
                    AND rctl.sales_order_line          IS NOT NULL
                    AND rctl.interface_line_context    = ''ORDER ENTRY''))',
      p_title                  => 'RMA Line Is Stuck In Status "Fulfilled" For Which Credit Memo Is Already Generated',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Return Order Line is stuck at Fulfilled Status for which Receiving is not done as Receiving is not eligible. For this Line, Credit Memo is generated',
      p_solution               => 'Refer To [2895372/KB768118]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_RMA_WITH_CREDIT_MEMO_STUCK_IN_FULFILLED_STATUS');



