       to_char(lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Last Update Date"	   
FROM oe_order_lines_all    lin
WHERE lin.header_id = ##$$HEADERID$$##
      AND NVL(''##$$LINEID$$##'',0) in (0, lin.LINE_ID, lin.TOP_MODEL_LINE_ID, lin.ATO_LINE_ID, lin.LINK_TO_LINE_ID, lin.SERVICE_REFERENCE_LINE_ID)
	  AND ( lin.tax_exempt_number IS NOT NULL
      OR lin.tax_exempt_reason_code IS NOT NULL )
      AND lin.tax_exempt_flag = ''S''
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Lines Update Or Copy Error',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Error While Copying Or Updating The SO Line',
      p_solution               => 'Refer to [874232/KB791426] to determine why  Update Order lines/Copy migrated order(s) from 11i to R12  fails having Tax handling as ''Standard'' and Tax Exempt Number or Tax Exempt Reason code.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_SALES_ORDER_LINES_UPDATE_COPY_ERROR');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_SO_LINE_BLANKET_LINE_MISSING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27404',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_SO_LINE_BLANKET_LINE_MISSING',
      p_sig_sql                => 'Select ol.line_id "Line Id",
       om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number,ol.service_number) "SO Line Num",       
       ol.flow_status_code "Line Status",
       ol.booked_flag "Booked Flag",
       ol.open_flag  "Open Flag",
       ol.cancelled_flag "Cancel Flag",
       ooh.header_id "Header Id",
       ooh.order_number "Sales Order Number",
       ooh.flow_status_code "Header Status",
       ol.blanket_number "Sales Agreement Number", 
       ol.blanket_line_number "Sales Agreement Line No" 
from oe_order_lines_all ol,
     oe_order_headers_all ooh
where 1=1
and ol.header_id = ##$$HEADERID$$##
and  nvl(''##$$LINEID$$##'',0) IN (0,
                                   ol.line_id,
                                   ol.top_model_line_id,
                                   ol.ato_line_id,
                                   ol.link_to_line_id,
                                   ol.service_reference_line_id)
and ol.header_id = ooh.header_id 
and exists
(select 1   --Checking if Blanket Number is present
 from oe_blanket_headers_All obh
 where obh.order_number = ol.blanket_number
 and not exists 
    (select 1
     from oe_blanket_lines_all obl
where obh.header_id = obl.header_id
and obl.line_number =ol.blanket_line_number)
 )',
      p_title                  => 'Sales Order Line With Blanket Agreement Number Failing Fulfillment As Blanket Line Number is Missing',
