debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_LINE_STUCK_SCHEDULE_SHIPPING_COMPLETE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27535',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_LINE_STUCK_SCHEDULE_SHIPPING_COMPLETE',
      p_sig_sql                => 'SELECT
    ooh.order_number "Sales Order Number",
    ol.header_id "Order Header Id",
    ol.line_id "SO Line Id",
     om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number,ol.service_number) "SO Line Num",       
       ol.flow_status_code "Line Status",
       ol.booked_flag "Booked Flag",
       ol.open_flag  "Open Flag",
       ol.cancelled_flag "Cancel Flag",      
    ol.ordered_quantity "Ordered Quantity",
    ol.inventory_item_id "Item Id",
    ol.creation_date "Line Creation Date",
    ol.shipping_quantity "Shipping Quantity",
    ol.shipped_quantity "Shipped Quantity",
    ol.cancelled_quantity "Cancelled Quantity",
    ol.fulfilled_quantity "Fulfilled Quantity",
    ol.ordered_quantity2 "Ordered Quantity2",
    ol.shipping_quantity2 "Shipping Quantity2",
    ol.shipped_quantity2 "Shipped Quantity2",
    ol.fulfilled_quantity2"Fufilled Quantity2"
FROM
    oe_order_lines_all ol,
    oe_order_headers_all ooh
WHERE
    ol.shipping_interfaced_flag = ''Y''
    AND ol.flow_status_code = ''SHIPPED''
    AND ol.header_id = ooh.header_id
     and ol.header_id = ##$$HEADERID$$##
and  nvl(''##$$LINEID$$##'',0) IN (0,
                                   ol.line_id,
                                   ol.top_model_line_id,
                                   ol.ato_line_id,
                                   ol.link_to_line_id,
                                   ol.service_reference_line_id)
    AND ol.open_flag = ''Y''
   and exists ( select 1 from wf_item_activity_statuses s2,
 wf_process_activities p2
 where  s2.item_key = to_char(ol.line_id)
 and s2.item_type = ''OEOL''
 and p2.instance_id = s2.process_activity
 and p2.activity_name = ''LINE_SCHEDULING''
 and s2.activity_status = ''ERROR'')',
      p_title                  => 'Shipped Sales Order Line Stuck At Schedule Activity With Error',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Line Workflow was retried and brought back to Root activity even though line is Shipped, and Shipping attributes are populated.',
      p_solution               => 'Refer to [842626/KB793407] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_LINE_STUCK_SCHEDULE_SHIPPING_COMPLETE');



