debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_DROPSHIP_NONEXPENSE_ITEM');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27860',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_DROPSHIP_NONEXPENSE_ITEM',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(oel.line_number, oel.shipment_number, oel.option_number, oel.component_number, oel.service_number) "Line",
       oel.line_id,
       rcv.transaction_id
  FROM rcv_transactions rcv,
       po_line_locations_all poll,
       oe_drop_ship_sources oed,
       oe_order_lines_all oel,
       mtl_system_items_b msib
 WHERE oel.source_type_code = ''EXTERNAL''
   AND nvl(oel.shipped_quantity, 0) = 0
   AND oed.line_id = oel.line_id
   AND oed.line_location_id IS NOT NULL
   AND poll.line_location_id = oed.line_location_id
   AND rcv.po_line_location_id = poll.line_location_id
   AND oel.flow_status_code = ''AWAITING_RECEIPT''
   AND oel.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, oel.line_id, oel.top_model_line_id, oel.ato_line_id, oel.link_to_line_id, oel.reference_line_id, oel.service_reference_line_id )
   AND rcv.transaction_type = ''DELIVER''
  AND oel.split_from_line_id IS NULL
   AND EXISTS (
  SELECT 1
    FROM mtl_material_transactions mmt
   WHERE mmt.rcv_transaction_id = rcv.transaction_id)
   AND oel.ship_from_org_id = msib.organization_id
   AND oel.inventory_item_id = msib.inventory_item_id
   AND msib.inventory_asset_flag = ''Y''',
      p_title                  => 'Progress Dropship Order Line For Non-Expense Item Stuck In Awaiting Receipt After Receiving Is Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Drop ship order line for non-expense item is stuck in Awaiting Receipt status.<br>
The linked PO is received and delivered and is closed for receiving.
',
      p_solution               => 'Refer To [2938204/KB710189] for details',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_DROPSHIP_NONEXPENSE_ITEM');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_INVOICED_LINES_SHIPPED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '27822',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_INVOICED_LINES_SHIPPED',
      p_sig_sql                => 'SELECT l.header_id,
    l.line_id,
    l.ordered_quantity,
    l.shipped_quantity,
    l.fulfilled_quantity,
    l.invoiced_quantity,
    l.fulfilled_flag,
    l.flow_status_code,
    l.invoice_interface_status_code,
    l.fulfillment_date,
    l.creation_date,
    l.last_update_date,
    l.actual_shipment_date
FROM oe_order_lines_all   l
WHERE l.header_id = ##$$HEADERID$$##
  AND nvl(''##$$LINEID$$##'', 0) IN ( 0, l.line_id, l.top_model_line_id, l.ato_line_id, l.link_to_line_id, l.service_reference_line_id )
   AND l.open_flag = ''Y''
    AND l.flow_status_code =  ''SHIPPED''
    AND NVL(l.SHIPPED_QUANTITY,0) > 0
    AND EXISTS (SELECT 1
        FROM wsh_delivery_details wdd
        WHERE wdd.source_line_id = l.line_id
            AND wdd.source_code = ''OE''
            AND wdd.released_status = ''C''
            AND wdd.oe_interfaced_flag = ''Y''
            AND wdd.inv_interfaced_flag = ''Y'')
    AND
     ( EXISTS (
        SELECT 1
        FROM ra_customer_trx_lines_all
        WHERE line_type = ''LINE''
            AND interface_line_context = ''ORDER ENTRY''
            AND interface_line_attribute6 = to_char(l.line_id)
    ) OR EXISTS (SELECT 1
        FROM ra_interface_lines_all
        WHERE line_type = ''LINE''
            AND interface_line_context = ''ORDER ENTRY''
            AND interface_line_attribute6 = to_char(l.line_id)
                       ))
    AND NOT EXISTS (
        SELECT ''Line workflow.''
        FROM wf_items wfi_2
        WHERE wfi_2.item_type = ''OEOL''
            AND wfi_2.item_key = to_char(l.line_id)
    )
',
      p_title                  => 'Sales Order Lines In Shipped Status. Line Is Shipped, Invoiced And Workflow Purged',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Line Stuck In Shipped Status Where As Line Is Shipped, Invoiced And Workflow Purged',
      p_solution               => 'Refer to [2388373/KB752943] for details',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_INVOICED_LINES_SHIPPED');



