debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_CANCELLED_FLAG_Y_STATUS_INCORRECT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '28384',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_CANCELLED_FLAG_Y_STATUS_INCORRECT',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line",
       l.line_id "Line ID", 
       l.flow_status_code "Line Status", 
       l.header_id "Header ID"
FROM oe_order_lines_all l
WHERE nvl(l.cancelled_flag,''N'') = ''Y''
AND l.open_flag = ''N''
AND l.cancelled_quantity > 0
AND l.flow_status_code <> ''CANCELLED''
AND l.booked_flag = ''Y''
AND NVL(l.INVOICE_INTERFACE_STATUS_CODE,''NO'') <> ''YES''
AND l.header_id = ##$$HEADERID$$##
AND nvl(''##$$LINEID$$##'', 0) IN ( 0, l.line_id, l.top_model_line_id, l.ato_line_id, l.link_to_line_id, l.service_reference_line_id )
AND EXISTS
  (
  SELECT 1 FROM wf_items wfi
  WHERE wfi.item_type = ''OEOL''
  AND wfi.item_key = to_char(l.line_id)
  AND wfi.end_date IS NULL
  )
ORDER BY l.line_number,
          nvl(l.shipment_number, - 1),
          nvl(l.option_number, - 1),
          nvl(l.component_number, - 1),
          nvl(l.service_number, - 1)',
      p_title                  => 'Cancelled Flag Y Open Flag N But Line Flow Status Code Not Changed To Cancelled',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Order line is cancelled with open flag as N but the line status has not changed to CANCELLED',
      p_solution               => 'Refer to [2429345/KB767048] for details.',
      p_success_msg            => 'Cancelled lines have correct flow status code and cancelled flag ',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_CANCELLED_FLAG_Y_STATUS_INCORRECT');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_OPEN_SO_LINES_WF_CREATED_NOT_STARTED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29255',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_OPEN_SO_LINES_WF_CREATED_NOT_STARTED',
      p_sig_sql                => 'SELECT ooh.order_number "Order Number",
ool.header_id "Header ID",
ool.line_id "Line ID",
om_order_analyzer_pkg.line_shipment_option(ool.line_number, ool.shipment_number, ool.option_number, ool.component_number, ool.service_number) "SO Line",
ool.flow_status_code "Line Status",
ool.open_flag "Open Flag"
FROM wf_items wit,
oe_order_lines_all ool,
oe_order_headers_all ooh
WHERE wit.item_type = ''OEOL''
AND to_number(wit.item_key) = ool.line_id
AND ool.open_flag = ''Y''
AND ool.flow_status_code IN (''BOOKED'',''ENTERED'')
AND NVL(ool.shipped_quantity,0) = 0
AND NVL(ool.fulfilled_quantity,0) = 0
AND NVL(ool.invoiced_quantity,0) = 0
AND ool.transaction_phase_code = ''F''
AND ool.header_id=ooh.header_id
AND NOT EXISTS
(SELECT 1
FROM wf_item_activity_statuses wias
WHERE wias.item_type = wit.item_type
AND wias.item_key = wit.item_key
)
AND ool.header_id = ##$$HEADERID$$## 
