debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_LINE_STUCK_IN_FULFILLED_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '30896',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_LINE_STUCK_IN_FULFILLED_STATUS',
      p_sig_sql                => 'SELECT
  line_id,
  ordered_item,
  ordered_quantity,
  shipping_quantity,
  shipped_quantity,
  shipping_quantity2,
  shipped_quantity2,
  invoiced_quantity,
  (
  SELECT
  wias.activity_result_code
  FROM
  wf_item_activity_statuses wias,
  wf_process_activities wpa
  WHERE
  wias.item_type = ''OEOL''
  AND wias.item_key = to_char(l.line_id)
  AND wpa.process_item_type = ''OEOL''
  AND wpa.instance_id = wias.process_activity
  AND wpa.instance_label = ''INVOICE_INTERFACE''
  AND wias.activity_status = ''COMPLETE''
  ) invoice_status,
  (
  SELECT
  ''Y''
  FROM
  ra_customer_trx_lines_all ral
  WHERE
  ral.interface_line_context = ''ORDER ENTRY''
  AND ral.line_type = ''LINE''
  AND ral.interface_line_attribute6 = to_char(l.line_id)
  ) invoice_created,
(
  SELECT
  sum(nvl(QUANTITY_INVOICED,0))
  FROM
  ra_customer_trx_lines_all ral
  WHERE
  ral.interface_line_context = ''ORDER ENTRY''
  AND ral.line_type = ''LINE''
  AND ral.interface_line_attribute6 = to_char(l.line_id)
  )invoiced_qty,
(SELECT
  root_activity
  FROM
  wf_items itm
  WHERE
  itm.item_type = ''OEOL''
  AND itm.item_key = to_char(l.line_id)
  AND itm.end_date IS NOT NULL
  )root_activity
  FROM
  oe_order_lines_all l
  WHERE
  header_id = ##$$HEADERID$$##
  AND nvl(invoice_interface_status_code, ''N'') = ''N''
  AND flow_status_code = ''FULFILLED''
  AND open_flag = ''Y''
  AND booked_flag = ''Y''
  AND EXISTS (
  SELECT
  1
  FROM
  wf_item_activity_statuses wias,
  wf_process_activities wpa
  WHERE
  wias.item_type = ''OEOL''
  AND wias.item_key = to_char(l.line_id)
  AND wpa.process_item_type = ''OEOL''
  AND wpa.instance_id = wias.process_activity
  AND wpa.instance_label = ''CLOSE_LINE''
  AND wias.activity_status = ''COMPLETE''
  AND wias.activity_result_code = ''COMPLETE''
  )
  AND EXISTS (
  SELECT
  1
  FROM
  wf_item_activity_statuses wias,
  wf_process_activities wpa
  WHERE
  wias.item_type = ''OEOL''
  AND wias.item_key = to_char(l.line_id)
  AND wpa.process_item_type = ''OEOL''
  AND wpa.instance_id = wias.process_activity
  AND wpa.instance_label = ''FULFILL_LINE''
  AND wias.activity_status = ''COMPLETE''
  )
  AND EXISTS (
  SELECT
  1
  FROM
  wf_items itm
  WHERE
  itm.item_type = ''OEOL''
  AND itm.item_key = to_char(l.line_id)
  AND itm.end_date IS NOT NULL)',
      p_title                  => 'Sales Order Lines Stuck in "Fulfilled" Status',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Lines Stuck With "Fulfilled" Status',
      p_solution               => '[2887086/KB753115]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_LINE_STUCK_IN_FULFILLED_STATUS');



debug('begin add_signature: SALES_ORDER_LINES_PRICING_DISPLAY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13464',
      p_sig_id                 => 'SALES_ORDER_LINES_PRICING_DISPLAY',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id                               "Line ID",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''LINE_FLOW_STATUS''
               AND lookup_code = lin.flow_status_code )   "Status",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''CALCULATE_PRICE_FLAG''
               AND lookup_code = lin.calculate_price_flag ) "Calculate Price",
	   --	   
       substr(itm.segment1, 1, 80)                        "Item Name",
              lin.inventory_item_id                              "Item ID",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''ITEM_TYPE''
               AND lookup_code = lin.item_type_code )     "Item Type",
       --
       lin.unit_selling_price          "Unit Selling Price",
       lin.unit_list_price             "Unit List Price",
       to_char(lin.pricing_date, ''DD-MON-RR_HH24:MI:SS'')    "Pricing Date",
	   lin.price_list_id               "Price List ID",
       ( SELECT name
         FROM qp_list_headers_tl
         WHERE list_header_id = lin.price_list_id
               AND language = ''US'' )   "Price List",
       ----
       nvl(lin.ordered_quantity, 0)    "Ordered Qty",
       lin.order_quantity_uom          "Ordered UOM",
       lin.pricing_quantity        "Pricing Qty",
       lin.pricing_quantity_uom        "Pricing Qty UOM",
       nvl(lin.cancelled_quantity, 0)  "Cancelled Qty",
       nvl(lin.shipping_quantity, 0)   "Shipping Qty",
       lin.shipping_quantity_uom       "Shipping UOM",
       nvl(lin.shipped_quantity, 0)    "Shipped Qty",
       nvl(fulfilled_quantity, 0)      "Fulfilled Qty",
       nvl(lin.invoiced_quantity, 0)   "Invoiced Qty",
       --
              lin.line_type_id                                   "Line Type ID",
       ( SELECT name
         FROM oe_transaction_types_tl
         WHERE transaction_type_id = lin.line_type_id
               AND language = ''US'' )                      "Line Type",
       ( SELECT meaning
         FROM oe_lookups
         WHERE lookup_type = ''LINE_CATEGORY''
               AND lookup_code = lin.line_category_code ) "Line Category",
           ( SELECT name
         FROM ra_terms_tl
         WHERE term_id = lin.payment_term_id
               AND language = ''US'' ) "Payment Term",
       lin.freight_terms_code || '': '' ||
       (SELECT meaning 
           FROM fnd_lookup_values_vl 
           WHERE lookup_type = ''FREIGHT_TERMS'' AND view_application_id = 660 AND lookup_code = lin.freight_terms_code) "Freight Terms",
       lin.agreement_id              "Agreement ID",
       ( SELECT name
         FROM oe_agreements
         WHERE agreement_id = lin.agreement_id)  "Pricing Agreement",
       --Secondary Qty
       nvl(lin.ordered_quantity2, 0)   "Secondary Ordered Qty",
       lin.ordered_quantity_uom2       "Secondary Ordered UOM",
       nvl(lin.cancelled_quantity2, 0) "Secondary Cancelled Qty",
       nvl(lin.shipping_quantity2, 0)  "Secondary Shipping Qty",
       lin.shipping_quantity_uom2      "Secondary Shipping UOM",
       nvl(lin.shipped_quantity2, 0)   "Secondary Shipped Qty",
       nvl(fulfilled_quantity2, 0)     "Secondary Fulfilled Qty",
       --
       lin.unit_selling_price_per_pqty "Selling Price per Pricing UOM",
       lin.unit_list_price_per_pqty    "List Price Per Pricing UOM",
       lin.price_request_code          "Price Request",
       --
              nvl(lin.open_flag, ''N'')                     "Open",
       nvl(lin.booked_flag, ''N'')                          "Booked",
       nvl(lin.cancelled_flag, ''N'')                       "Cancelled",
       nvl(lin.shippable_flag, ''N'')                       "Shippable",
       nvl(lin.shipping_interfaced_flag, ''N'')             "Shipping Interfaced",
       nvl(lin.fulfilled_flag, ''N'')                       "Fullfilled",
       nvl(lin.invoice_interface_status_code, ''N'')        "Invoice Interface",
       --
       lin.org_id                      "Org ID",
       ( SELECT name
         FROM hr_operating_units hr
         WHERE lin.org_id = hr.organization_id ) "Operating Unit",
       lin.ship_from_org_id            "Ship From Org ID",
       ( SELECT organization_code
         FROM mtl_parameters mp
         WHERE mp.organization_id = lin.ship_from_org_id ) "Warehouse",
       lin.subinventory                "Subinventory"
	   
FROM oe_order_lines_all    lin,
     mtl_system_items      itm
WHERE LIN.header_id = ##$$HEADERID$$##
      AND NVL(''##$$LINEID$$##'',0) in (0, LIN.LINE_ID, LIN.TOP_MODEL_LINE_ID,LIN.ATO_LINE_ID,LIN.LINK_TO_LINE_ID,LIN.SERVICE_REFERENCE_LINE_ID)
      AND lin.ship_from_org_id = itm.organization_id (+)
      AND lin.inventory_item_id = itm.inventory_item_id (+)
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Pricing Line(s)',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no sales order pricing line(s).',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_PRICING_DISPLAY');



