debug('begin add_signature: SALES_ORDER_LINE_NO_PRICE_LIST');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14789',
      p_sig_id                 => 'SALES_ORDER_LINE_NO_PRICE_LIST',
      p_sig_sql                => 'SELECT 
   om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
   substr(lin.line_id, 1, 15) "Line ID",
   lin.item_type_code "Item Type Code",
   lin.line_type_id "Line Type ID",
   tl.name "Line Type"
FROM oe_order_lines_all lin,
oe_order_headers_all hed,
oe_transaction_types_tl tl
WHERE lin.header_id = ##$$HEADERID$$##
AND NVL(''##$$LINEID$$##'',0) in (0,lin.LINE_ID,
lin.TOP_MODEL_LINE_ID,
lin.ATO_LINE_ID,
lin.LINK_TO_LINE_ID,
lin.SERVICE_REFERENCE_LINE_ID)
AND lin.line_type_id = tl.transaction_type_id
AND tl.LANGUAGE=''US''
AND lin.option_number IS NULL
AND lin.item_type_code <> ''INCLUDED''
AND lin.item_type_code <> ''CONFIG'' 
AND lin.header_id = hed.header_id
AND lin.price_list_id is NULL
ORDER BY lin.line_number, 
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Sales Order Lines with no Price List',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The line(s) do not have a Price List assigned.  This will cause error in Receiving Receipt and/or Invoicing.',
      p_solution               => 'Refer to [1379682/KB793431] Assign price list to the order line<br>
Navigate to Orders, Returns > Order Organizer > Query return order > Click on the line items tab > Click on the Pricing tab > Enter the price list on the line ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_NO_PRICE_LIST');



