debug('begin add_signature: PRICING_SEEDED_ATTR_SOURCING_CHECK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '16351',
      p_sig_id                 => 'PRICING_SEEDED_ATTR_SOURCING_CHECK',
      p_sig_sql                => 'SELECT A.prc_context_type,
       A.prc_context_code,
       A.enabled_flag,
       B.segment_code,
       B.segment_mapping_column,
       C.request_type_code,
       C.attribute_sourcing_level,
       C.seeded_sourcing_type,
       C.seeded_value_string,
       C.user_sourcing_type,
       C.user_value_string,
       C.enabled_flag
FROM   QP_PRC_CONTEXTS_B A,
       QP_SEGMENTS_B B,
       QP_ATTRIBUTE_SOURCING C
WHERE  A.prc_context_type IN ( ''PRODUCT'', ''QUALIFIER'', ''PRICING_ATTRIBUTE'' )
       AND A.seeded_flag = ''Y''
       AND B.prc_context_id = A.prc_context_id
       AND B.seeded_flag = ''Y''
       AND C.segment_id = B.segment_id
       AND C.seeded_flag = ''Y''
       AND Nvl(C.seeded_value_string, ''X'') <> Nvl(C.user_value_string, ''X'')
       AND C.user_value_string IS NOT NULL
ORDER  BY A.prc_context_type,
          A.prc_context_code,
          B.segment_code,
          C.request_type_code
',
      p_title                  => 'Incorrect Sourcing For Seeded Attributes',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Attributes where the seeded value string differs from the user value string.',
      p_solution               => 'Seeded values are replaced with custom (user) values.
To restore default seed values, Refer to [2914789/KB714003]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: PRICING_SEEDED_ATTR_SOURCING_CHECK');



