  FROM wip_discrete_jobs wip,
       wip_discrete_jobs_v wiv,
       mtl_reservations mr,
       mtl_system_items_b itm,
       oe_order_lines_all lin
 WHERE wip.wip_entity_id = wiv.wip_entity_id
   AND wip.primary_item_id = itm.inventory_item_id
   AND wip.organization_id = itm.organization_id
   AND mr.demand_source_line_id = lin.line_id
   AND mr.supply_source_header_id = wip.wip_entity_id
   AND mr.demand_source_type_id = 2 -- Sales order
   AND mr.supply_source_type_id = 5 -- WIP discrete job
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
 ORDER BY lin.line_number, 
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.component_number, - 1),
          nvl(lin.service_number, - 1),
          wip.wip_entity_id
	',
      p_title                  => 'WIP Discrete Jobs',
