debug('begin add_signature: SALES_ORDER_WSH_FREIGHT_COSTS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1098',
      p_sig_id                 => 'SALES_ORDER_WSH_FREIGHT_COSTS',
      p_sig_sql                => 'SELECT wfc.freight_cost_id "Freight Cost ID",
       wfc.freight_cost_type "Freight Name",
       lkp.meaning "Freight Type",
       ''DELIV_DETAIL'' "Freight Level",
       wfc.quantity qty,
       wfc.currency_code "Currency Code",
       wfc.unit_amount "Unit Amount",
       wfc.total_amount "Total Amount",
       wfc.delivery_detail_id "Entity ID"
  FROM wsh_freight_costs_v wfc,
       wsh_freight_cost_types wft,
       fnd_lookup_values lkp,
       oe_order_lines_all lin,
       wsh_delivery_details det
 WHERE wfc.freight_cost_type_id = wft.freight_cost_type_id
   AND wft.freight_cost_type_code = lkp.lookup_code
   AND lkp.lookup_type = ''FREIGHT_COST_TYPE''
   AND det.source_line_id = lin.line_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
   AND wfc.delivery_detail_id = det.delivery_detail_id
UNION ALL
SELECT wfc.freight_cost_id "Freight Cost ID",
       wfc.freight_cost_type "Freight Name",
       lkp.meaning "Freight Type",
       ''DELIVERY'' "Freight Level",
       wfc.quantity qty,
       wfc.currency_code "Currency Code",
       wfc.unit_amount "Unit Amount",
       wfc.total_amount "Total Amount",
       wfc.delivery_id "Entity ID"
  FROM wsh_freight_costs_v wfc,
       wsh_freight_cost_types wft,
       fnd_lookup_values lkp,
       oe_order_lines_all lin,
       wsh_delivery_details det,
       wsh_delivery_assignments asg
 WHERE wfc.freight_cost_type_id = wft.freight_cost_type_id
   AND wft.freight_cost_type_code = lkp.lookup_code
   AND lkp.lookup_type = ''FREIGHT_COST_TYPE''
   AND asg.delivery_detail_id = det.delivery_detail_id
   AND det.source_line_id = lin.line_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
   AND wfc.delivery_id = asg.delivery_id
   AND wfc.delivery_detail_id IS NULL
UNION ALL
SELECT wfc.freight_cost_id "Freight Cost ID",
       wfc.freight_cost_type "Freight Name",
       lkp.meaning "Freight Type",
       ''LEG'' "Freight Level",
       wfc.quantity qty,
       wfc.currency_code "Currency Code",
       wfc.unit_amount "Unit Amount",
       wfc.total_amount "Total Amount",
       wfc.delivery_leg_id "Entity ID"
  FROM wsh_freight_costs_v wfc,
       wsh_freight_cost_types wft,
       fnd_lookup_values lkp,
       oe_order_lines_all lin,
       wsh_delivery_details det,
       wsh_new_deliveries del,
       wsh_delivery_legs leg,
     --wsh_trip_stops stp,
       wsh_delivery_assignments asg
 WHERE wfc.freight_cost_type_id = wft.freight_cost_type_id
   AND wft.freight_cost_type_code = lkp.lookup_code
   AND lkp.lookup_type = ''FREIGHT_COST_TYPE''
   AND del.delivery_id = asg.delivery_id
   AND asg.delivery_detail_id = det.delivery_detail_id
   AND det.source_line_id = lin.line_id
   AND leg.delivery_id = del.delivery_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
   AND wfc.delivery_leg_id = leg.delivery_leg_id
   AND wfc.delivery_detail_id IS NULL
   AND wfc.delivery_id IS NULL
UNION ALL
SELECT wfc.freight_cost_id "Freight Cost ID",
       wfc.freight_cost_type "Freight Name",
       lkp.meaning "Freight Type",
       ''STOP'' "Freight Level",
       wfc.quantity qty,
       wfc.currency_code "Currency Code",
       wfc.unit_amount "Unit Amount",
       wfc.total_amount "Total Amount",
       wfc.stop_id "Entity ID"
  FROM wsh_freight_costs_v wfc,
       wsh_freight_cost_types wft,
       fnd_lookup_values lkp,
       oe_order_lines_all lin,
       wsh_delivery_details det,
       wsh_new_deliveries del,
       wsh_delivery_legs leg,
       wsh_trip_stops stp,
       wsh_delivery_assignments asg
 WHERE wfc.freight_cost_type_id = wft.freight_cost_type_id
   AND wft.freight_cost_type_code = lkp.lookup_code
   AND lkp.lookup_type = ''FREIGHT_COST_TYPE''
   AND del.delivery_id = asg.delivery_id
   AND asg.delivery_detail_id = det.delivery_detail_id
   AND det.source_line_id = lin.line_id
   AND stp.stop_id = leg.pick_up_stop_id
   AND leg.delivery_id = del.delivery_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
   AND wfc.stop_id = stp.stop_id
   AND wfc.delivery_detail_id IS NULL
   AND wfc.delivery_id IS NULL
   AND wfc.delivery_leg_id IS NULL
UNION ALL
SELECT wfc.freight_cost_id "Freight Cost ID",
       wfc.freight_cost_type "Freight Name",
       lkp.meaning "Freight Type",
       ''TRIP'' "Freight Level",
       wfc.quantity qty,
       wfc.currency_code "Currency Code",
       wfc.unit_amount "Unit Amount",
       wfc.total_amount "Total Amount",
       wfc.trip_id "Entity ID"
  FROM wsh_freight_costs_v wfc,
       wsh_freight_cost_types wft,
       fnd_lookup_values lkp,
       oe_order_lines_all lin,
       wsh_delivery_details det,
       wsh_new_deliveries del,
       wsh_delivery_legs leg,
       wsh_trip_stops stp,
       wsh_delivery_assignments asg
 WHERE wfc.freight_cost_type_id = wft.freight_cost_type_id
   AND wft.freight_cost_type_code = lkp.lookup_code
   AND lkp.lookup_type = ''FREIGHT_COST_TYPE''
   AND del.delivery_id = asg.delivery_id
   AND asg.delivery_detail_id = det.delivery_detail_id
   AND det.source_line_id = lin.line_id
   AND stp.stop_id = leg.pick_up_stop_id
   AND leg.delivery_id = del.delivery_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
   AND wfc.trip_id = stp.trip_id
   AND wfc.delivery_detail_id IS NULL
   AND wfc.delivery_id IS NULL
   AND wfc.stop_id IS NULL
   AND wfc.delivery_leg_id IS NULL',
      p_title                  => 'Freight Costs',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no freight costs.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_WSH_FREIGHT_COSTS');



