debug('begin add_signature: SALES_ORDER_LINE_SHIPPED_INTERFACED_QTY_ZERO');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8530',
      p_sig_id                 => 'SALES_ORDER_LINE_SHIPPED_INTERFACED_QTY_ZERO',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       lin.inventory_item_id "Item ID",
       substr(lin.flow_status_code, 1, 22) "Workflow Status",
       nvl(lin.ordered_quantity, 0) "Ordered Qty",
       lin.order_quantity_uom "Ordered UOM",
       nvl(lin.shipped_quantity, 0) "Shipped Qty",
       nvl(lin.shipping_quantity, 0) "Shipping Qty",
       nvl(fulfilled_quantity, 0) "Fulfilled Qty",
       nvl(lin.cancelled_quantity, 0) "Cancelled Qty",
       nvl(lin.invoiced_quantity, 0) "Invoiced Qty",
       nvl(lin.open_flag, ''N'') "Open",
       nvl(lin.booked_flag, ''N'') "Booked",
       nvl(lin.shippable_flag, ''N'') "Shipped",
       nvl(lin.cancelled_flag, ''N'') "Cancelled",
       nvl(lin.fulfilled_flag, ''N'') "Fullfilled",
       nvl(lin.shipping_interfaced_flag, ''N'') "Shipping Interface",
       lin.ship_from_org_id "Ship From",
       nvl(lin.invoice_interface_status_code, ''N'') "Invoice Interface",
       lin.ship_tolerance_above "Ship Tolerance Above",
       lin.ship_tolerance_below "Ship Tolerance Below",
       to_char(lin.actual_shipment_date, ''DD-MON-RR_HH24:MI:SS'') "Actual Ship",
       to_char(lin.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Create Date",
       to_char(lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Update Date"
  FROM oe_order_headers_all ord,
       oe_order_lines_all lin,
       wsh_delivery_details det
 WHERE ord.header_id = ##$$HEADERID$$##
   AND lin.header_id = ##$$HEADERID$$##
   AND det.source_line_id = lin.line_id
   AND det.source_code = ''OE''
   AND det.oe_interfaced_flag = ''Y''
   AND lin.shippable_flag = ''Y''
   AND nvl(lin.shipped_quantity, 0) = 0
   AND lin.flow_status_code = ''AWAITING_SHIPPING'' 
   AND NVL(lin.shipped_quantity,0) = 0 
   AND det.shipped_quantity > 0 
   AND EXISTS (SELECT 1 
                 FROM wf_item_activity_statuses wias,
                      wf_process_activities wpa
                WHERE wias.item_type = ''OEOL''
                  AND wias.item_key = TO_CHAR(lin.line_id)
                  AND wias.process_activity = wpa.instance_id
                  AND wias.end_date IS NULL
                  AND wias.activity_status =''NOTIFIED''
                  AND wpa.process_name =''SHIP_CONFIRM''
                  AND wpa.activity_name =''SHIP_LINE'')
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id )
 ORDER BY lin.line_number,
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.component_number, - 1),
          nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Line has been Shipped, Interfaced but Shipped Qty not updated',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Line has been interfaced to Order Management but shipped quantity was not updated.',
      p_solution               => 'Refer to [2336712/KB627398] for details.',
      p_success_msg            => 'Any shipped quantities have been interfaced to Order Management.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_SHIPPED_INTERFACED_QTY_ZERO');



debug('begin add_signature: SALES_ORDER_TRAILING_WSH_DELIVERY_DETAILS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12072',
      p_sig_id                 => 'SALES_ORDER_TRAILING_WSH_DELIVERY_DETAILS',
      p_sig_sql                => 'SELECT
     DELIVERY_DETAIL_ID "Delivery Detail ID",
     RELEASED_STATUS "Release Status Code",
     decode(RELEASED_STATUS,
     ''Y'',''Y=Staged'',
     ''R'',''R=Ready to Release'',
     ''S'',''S=Rel to Warhouse'',
     ''B'',''B=Backorder'',
     ''P'',''P=Pending Inv'',
     ''C'',''C=Shipped'',
     ''N'',''N=Not Ready'',
     ''D'',''D=Cancelled'',
     ''X'',''X=Not Applicable'',''Unknown: ''||RELEASED_STATUS) "Release Status",
     nvl(INV_INTERFACED_FLAG,''N'') "Inv Interfaced",
     nvl(OE_INTERFACED_FLAG,''N'') "OM Interfaced",
     SOURCE_LINE_ID "Line ID",
     INVENTORY_ITEM_ID "Item ID"
 FROM
     wsh_delivery_details
 WHERE
     source_header_id = ##$$HEADERID$$##
     AND ( nvl(length(ltrim(rtrim(source_code) ) ),0) != length(source_code)
           OR nvl(length(ltrim(rtrim(source_header_type_name) ) ),0) != length(source_header_type_name)
           OR nvl(length(ltrim(rtrim(cust_po_number) ) ),0) != length(cust_po_number)
           OR nvl(length(ltrim(rtrim(item_description) ) ),0) != length(item_description)
           OR nvl(length(ltrim(rtrim(hold_code) ) ),0) != length(hold_code)
           OR nvl(length(ltrim(rtrim(ship_model_complete_flag) ) ),0) != length(ship_model_complete_flag)
           OR nvl(length(ltrim(rtrim(country_of_origin) ) ),0) != length(country_of_origin)
           OR nvl(length(ltrim(rtrim(classification) ) ),0) != length(classification)
           OR nvl(length(ltrim(rtrim(src_requested_quantity_uom) ) ),0) != length(src_requested_quantity_uom)
           OR nvl(length(ltrim(rtrim(requested_quantity_uom) ) ),0) != length(requested_quantity_uom)
           OR nvl(length(ltrim(rtrim(subinventory) ) ),0) != length(subinventory)
           OR nvl(length(ltrim(rtrim(revision) ) ),0) != length(revision)
