debug('begin add_signature: SALES_ORDER_PICKABLE_FLAG_NOT_MATCH');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14161',
      p_sig_id                 => 'SALES_ORDER_PICKABLE_FLAG_NOT_MATCH',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       det.delivery_detail_id "Delivery Detail ID",
       wda.delivery_id "Delivery ID",
       det.source_line_id "Line ID",
       det.pickable_flag "Pickable Flag",
       nvl(itm.mtl_transactions_enabled_flag, ''N'') "Transactable Flag"
  FROM oe_order_lines_all lin,
       wsh_delivery_details det,
       wsh_delivery_assignments wda,
       mtl_system_items itm
 WHERE det.source_line_id = lin.line_id
   AND det.organization_id = itm.organization_id (+)
   AND det.inventory_item_id = itm.inventory_item_id (+)
   AND det.pickable_flag <> nvl(itm.mtl_transactions_enabled_flag, ''N'')
   AND det.delivery_detail_id = wda.delivery_detail_id (+)
   AND det.source_code = ''OE''
   AND det.released_status <>''D'' 
   AND lin.open_flag = ''Y''
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
 ORDER BY det.source_line_id,
          det.delivery_detail_id',
      p_title                  => 'Item is Not Under Inventory Controls yet Ship Confirm Errors with Delivery Details in this Delivery Do Not Satisfy Inventory Controls',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Item is Not Under Inventory Controls yet Ship Confirm Errors with Delivery Details in this Delivery Do Not Satisfy Inventory Controls',
      p_solution               => 'Refer to [1910428/KB716338] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_PICKABLE_FLAG_NOT_MATCH');



debug('begin add_signature: SALES_ORDER_WSH_READY_HAS_MOVE_ORDER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14945',
      p_sig_id                 => 'SALES_ORDER_WSH_READY_HAS_MOVE_ORDER',
      p_sig_sql                => 'SELECT
    source_header_number "Order Number",
    source_line_number   "Line Number",
    source_line_id       "Line ID",
    delivery_detail_id   "Delivery Detail ID",
    picked_quantity      "Picked Qty",
    shipped_quantity     "Shipped Qty",
    decode(released_status,
           ''Y'',''Y=Staged'',
           ''R'',''R=Ready to Release'',
           ''S'',''S=Rel to Warhouse'',
           ''B'',''B=Backorder'',
           ''P'',''P=Pending Inv'',
           ''C'',''C=Shipped'',
           ''N'',''N=Not Ready'',
           ''D'',''D=Cancelled'',
           ''X'',''X=Not Applicable'',''Unknown: ''||released_status) "Release Status"
FROM
    wsh_delivery_details
WHERE
    source_code = ''OE''
    AND released_status IN (
        ''R'',
        ''B''
    )
    AND source_header_id = ##$$HEADERID$$##
    AND move_order_line_id IS NOT NULL',
      p_title                  => 'Delivery Detail Ready to Release has Move Order',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Delivery Detail is R=Ready to Release but has MOVE ORDER ID',
      p_solution               => '<ul>
<li>Log a Service Request with Oracle Order Management</li>
<li>For more information regarding this issue, review [2195623/KB710551] for instructions and details.</li>
</ul>',
      p_success_msg            => 'No data found of Delivery Detail is R=Ready to Release but has MOVE ORDER ID.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_WSH_READY_HAS_MOVE_ORDER');



