   AND wdd.source_header_id = ##$$HEADERID$$##
   AND wdd.source_line_id = nvl(''##$$LINEID$$##'', wdd.source_line_id)
 ORDER BY ol.line_number,
          nvl(ol.shipment_number, - 1),
          nvl(ol.option_number, - 1),
          nvl(ol.component_number, - 1),
