debug('begin add_signature: ONT_WSH_INV_PENDING_INTERFACE_MTL_TXN_DONE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15250',
      p_sig_id                 => 'ONT_WSH_INV_PENDING_INTERFACE_MTL_TXN_DONE',
      p_sig_sql                => 'SELECT ooh.HEADER_ID "Sales Order Header Id",
ooh.order_number "Order Number",
wdd.source_line_number  "Line Number",
lin.line_id  "Line ID",
wdd.delivery_detail_id    "Delivery Detail ID" ,
wts.stop_id "Stop ID",
wdd.inv_interfaced_flag   "INV Interface",
wts.pending_interface_flag "Pending Interface",
wdd.creation_date  "Creation Date"
FROM wsh_delivery_details wdd ,
wsh_delivery_assignments wda ,
wsh_new_deliveries wnd ,
wsh_delivery_legs wdl ,
wsh_trip_stops wts,
oe_order_headers_all ooh,
oe_order_lines_all lin
WHERE lin.header_id = ##$$HEADERID$$##
AND NVL(''##$$LINEID$$##'',0) in (0,
                                       LIN.LINE_ID, 
                                       LIN.TOP_MODEL_LINE_ID, 
                                       LIN.ATO_LINE_ID, 
                                       LIN.LINK_TO_LINE_ID, 
                                       LIN.SERVICE_REFERENCE_LINE_ID)
AND wdd.source_line_id  = lin.line_id
AND lin.header_id = ooh.header_id
AND wdd.inv_interfaced_flag = ''P''
AND wdd.oe_interfaced_flag = ''Y''
AND wdd.source_code = ''OE''
AND wdd.released_status = ''C''
AND wdd.delivery_detail_id = wda.delivery_detail_id
AND wda.delivery_id = wnd.delivery_id
AND wnd.delivery_id = wdl.delivery_id
AND wts.stop_id = wdl.pick_up_stop_id
AND NVL (wts.pending_interface_flag, ''N'') = ''Y''
AND NOT EXISTS
       ( SELECT 1
         FROM mtl_transactions_interface MTI
         WHERE MTI.PICKING_LINE_ID = WDD.DELIVERY_DETAIL_ID
           AND ( MTI.error_code is not null or MTI.error_explanation is not null )
         UNION
         SELECT 1
         FROM MTL_MATERIAL_TRANSACTIONS MMT
         WHERE MMT.picking_line_id = WDD.delivery_detail_id )',
      p_title                  => 'Inventory Interface Delivery Lines',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This issue keeps the Interface Trip Stop from finding the delivery detail to interface. This can be seen in the sales order output in the WSH_DELIVERY_DETAILS where INV_INTERFACED_FLAG = P for the affected delivery detail and also in the WSH_TRIP_STOPS table shows the PENDING_INTERFACE Flag = Y for the Trip Stop.
',
      p_solution               => 'Log an SR and provide this Sales Order Analyzer and the Interface Trip Stop log file so a data fix can be provided.
<ul><li>Refer to [1994535/KB161357] for details.</li></ul>',
      p_success_msg            => 'There are no pending delivery lines.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: ONT_WSH_INV_PENDING_INTERFACE_MTL_TXN_DONE');



debug('begin add_signature: SALES_ORDER_WSH_OPEN_ ERROR_EXCEPTIONS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14781',
      p_sig_id                 => 'SALES_ORDER_WSH_OPEN_ ERROR_EXCEPTIONS',
      p_sig_sql                => '-- Delivery Detail
SELECT
     exception_id            "Exception ID",
     exception_name          "Exception Name",
     logging_entity          "Logging Entity",
     created_by              "Logging User ID",
     logged_at_location_id   "Logged At Location",
     exception_location_id   "Exception Location",
     severity                "Exception Behavior",
     status                  "Status",
     DECODE(manually_logged,''F'',''Off'',''T'',''On'',NULL) "Manually Logged", -- F False, T True
     trip_id                 "Trip ID",
     trip_name               "Trip Name",
     trip_stop_id            "Stop Location",
     departure_date          "Departure Date",
     arrival_date            "Arrival Date",
     delivery_id             "Delivery ID",
     delivery_name           "Delivery Name",
     delivery_detail_id      "Delivery Detail ID"
 FROM
     wsh_exceptions
 WHERE
     status IN (
         ''OPEN'',
         ''ERROR'',
         ''IN_PROGRESS''
     )
	 AND severity = ''ERROR''
     AND delivery_detail_id IN ( SELECT
                                det.delivery_detail_id
                            FROM
                                oe_order_lines_all lin,
                                wsh_delivery_details det
                            WHERE
         det.source_line_id = lin.line_id
         AND det.source_code = ''OE''
             AND lin.header_id = ##$$HEADERID$$##
             AND NVL(''##$$LINEID$$##'',0) IN (
                 0,
                 lin.line_id,
                 lin.top_model_line_id,
                 lin.ato_line_id,
                 lin.link_to_line_id,
                 lin.reference_line_id,
                 lin.service_reference_line_id
             )
		 AND det.released_status <> ''C'' 
     )
 UNION -- Delivery
 SELECT
     exception_id            "Exception ID",
     exception_name          "Exception Name",
     logging_entity          "Logging Entity",
     created_by              "Logging User ID",
     logged_at_location_id   "Logged At Location",
     exception_location_id   "Exception Location",
     severity                "Exception Behavior",
     status                  "Status",
     DECODE(manually_logged,''F'',''Off'',''T'',''On'',NULL) "Manually Logged", -- F False, T True
     trip_id                 "Trip ID",
     trip_name               "Trip Name",
     trip_stop_id            "Stop Location",
     departure_date          "Departure Date",
     arrival_date            "Arrival Date",
     delivery_id             "Delivery ID",
     delivery_name           "Delivery Name",
     delivery_detail_id      "Delivery Detail ID"
 FROM
     wsh_exceptions
 WHERE
     status IN (
         ''OPEN'',
         ''ERROR'',
         ''IN_PROGRESS''
     )
	 AND severity = ''ERROR''
     AND delivery_id IN (
         SELECT
             del.delivery_id   "Delivery ID"
         FROM
             oe_order_lines_all lin,
             wsh_delivery_details det,
             wsh_new_deliveries del,
             wsh_delivery_assignments asg
         WHERE
             del.delivery_id = asg.delivery_id
             AND asg.delivery_detail_id = det.delivery_detail_id
             AND det.source_line_id = lin.line_id
             AND lin.header_id = ##$$HEADERID$$##
             AND NVL(''##$$LINEID$$##'',0) IN (
                 0,
                 lin.line_id,
                 lin.top_model_line_id,
                 lin.ato_line_id,
                 lin.link_to_line_id,
                 lin.reference_line_id,
                 lin.service_reference_line_id
			              )
			  AND del.status_code <> ''CL''
     )
 UNION -- Trip
 SELECT
     exception_id            "Exception ID",
     exception_name          "Exception Name",
     logging_entity          "Logging Entity",
     created_by              "Logging User ID",
     logged_at_location_id   "Logged At Location",
     exception_location_id   "Exception Location",
     severity                "Exception Behavior",
     status                  "Status",
     DECODE(manually_logged,''F'',''Off'',''T'',''On'',NULL) "Manually Logged", -- F False, T True
     trip_id                 "Trip ID",
     trip_name               "Trip Name",
     trip_stop_id            "Stop Location",
     departure_date          "Departure Date",
     arrival_date            "Arrival Date",
     delivery_id             "Delivery ID",
     delivery_name           "Delivery Name",
     delivery_detail_id      "Delivery Detail ID"
 FROM
     wsh_exceptions
 WHERE
     status IN (
         ''OPEN'',
         ''ERROR'',
         ''IN_PROGRESS''
     )
	 AND severity = ''ERROR''
	     AND trip_id IN (
         SELECT
             stp.trip_id
         FROM
             oe_order_lines_all lin,
             wsh_delivery_details det,
             wsh_deliverable_stops_v stp
         WHERE
             det.source_line_id = lin.line_id
             AND det.source_code = ''OE''
             AND det.delivery_detail_id = stp.delivery_detail_id
             AND lin.header_id = ##$$HEADERID$$## AND nvl(''##$$LINEID$$##'',0) IN (
    0,
    lin.line_id,
    lin.top_model_line_id,
    lin.ato_line_id,
    lin.link_to_line_id,
    lin.reference_line_id,
    lin.service_reference_line_id) 
     AND stp.status_code <> ''CL''
   )',
      p_title                  => 'Shipping Exceptions with Error Type in Sales Order',
      p_fail_condition         => 'RS',
      p_problem_descr          => '<li> When attempting to Ship confirm a delivery the following error/Warning occurs</li>

<li>Error/Warning</li>

<li>Some deliveries selected for Ship Confirm have errors or warnings</li>',
      p_solution               => '<ul>
<li>From Order Management: Run Resolve/Purge Exceptions.</li>
<li>For more information regarding this issue, review [433021/KB779217] for instructions and details.</li>
<li> Note: The note discusses one specific type of exception name but the solution is applicable for any type of exception </li>
</ul>',
      p_success_msg            => 'No Open Error Shipping Exceptions associated with this sales order.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_WSH_OPEN_ ERROR_EXCEPTIONS');



debug('begin add_signature: EBS_MFG_OM_WSHSTOPS_KIT_LINE_CLOSED_INCLUDED_AWAITING_SHIPPING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24993',
      p_sig_id                 => 'EBS_MFG_OM_WSHSTOPS_KIT_LINE_CLOSED_INCLUDED_AWAITING_SHIPPING',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(ool.line_number, ool.shipment_number, ool.option_number, ool.component_number, ool.service_number) "Line",
       ool.line_id "Line ID",
       ool.item_type_code "Item Type",
       ool.model_remnant_flag "Model Remnant Flag",
       ool.top_model_line_id "Top Model Line ID",
       ool.link_to_line_id "Link to Line ID"
  FROM oe_order_lines_all ool,
       oe_order_headers_all ooh
 WHERE ooh.header_id = ##$$HEADERID$$##
   AND ooh.header_id = ool.header_id
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, ool.line_id, ool.top_model_line_id, ool.ato_line_id, ool.link_to_line_id, ool.service_reference_line_id )
   AND ooh.org_id = ool.org_id
   AND ool.link_to_line_id IS NOT NULL
   AND ool.flow_status_code = ''AWAITING_SHIPPING''
   AND ool.open_flag = ''Y''
   AND EXISTS (
  SELECT 1
    FROM oe_order_lines_all ool1
   WHERE ool1.line_id = ool.link_to_line_id
     AND ool1.flow_status_code = ''CLOSED''
     AND ool1.open_flag = ''N''
     AND ool1.item_type_code = ''KIT'' )
   AND EXISTS (
  SELECT 1
    FROM wsh_delivery_details wdd
   WHERE wdd.source_line_id = ool.line_id
     AND wdd.oe_interfaced_flag = ''N''
     AND wdd.inv_interfaced_flag = ''N''
     AND wdd.released_status = ''C'' )
 ORDER BY ool.line_number,
          nvl(ool.shipment_number, - 1),
          nvl(ool.option_number, - 1),
          nvl(ool.component_number, - 1),
          nvl(ool.service_number, - 1)     ',
      p_title                  => 'Parent KIT Line Closed but Included Lines are Awaiting Shipping',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The parent KIT order line is closed but the included item lines are stuck in Awaiting Shipping status, when Interface trip stop is executed for the delivery following error can be observed in the log file for program Interface Trip Stop

ERROR
ORA-01086: savepoint ''PROCESS_ORDER'' never established in this session or is invalid in Package OE_Delayed_Requests_PVT Procedure Process_Request_Pvt',
      p_solution               => 'A data fix will be required.<br>
Refer to [2916104/KB792698] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_WSHSTOPS_KIT_LINE_CLOSED_INCLUDED_AWAITING_SHIPPING');



debug('begin add_signature: SALES_ORDER_LINE_SHIPPED_WORKFLOW_STUCK _AT_SHIPLINE_NOTIFIED_STATUS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15570',
      p_sig_id                 => 'SALES_ORDER_LINE_SHIPPED_WORKFLOW_STUCK _AT_SHIPLINE_NOTIFIED_STATUS',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line",
       l.line_id,
       l.ship_tolerance_above,
       l.ship_tolerance_below,
       l.line_set_id,
       l.ordered_quantity,
       l.shipped_quantity
  FROM oe_order_lines_all l
 WHERE l.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, l.line_id, l.top_model_line_id, l.ato_line_id, l.link_to_line_id, l.service_reference_line_id )
   AND l.open_flag = ''Y''
   AND nvl(l.cancelled_flag, ''N'') = ''N''
   AND l.shipped_quantity > 0
   AND l.actual_shipment_date IS NOT NULL
   AND nvl(l.fulfilled_flag, ''N'') = ''N''
   AND nvl(fulfilled_quantity, 0) = 0
   AND EXISTS (
  SELECT 1
    FROM wf_item_activity_statuses st,
         wf_process_activities wpa
   WHERE wpa.instance_id = st.process_activity
     AND st.item_type = ''OEOL''
     AND st.item_key = to_char(l.line_id)
     AND wpa.activity_name = ''SHIP_LINE''
     AND wpa.process_name = ''SHIP_CONFIRM''
     AND st.activity_status = ''NOTIFIED'' )
   AND EXISTS (
  SELECT 1
    FROM wsh_delivery_details
   WHERE source_line_id = line_id
     AND source_code = ''OE''
     AND released_status = ''C''
     AND oe_interfaced_flag = ''Y'' )
 ORDER BY l.line_number,
          nvl(l.shipment_number, - 1),
          nvl(l.option_number, - 1),
          nvl(l.component_number, - 1),
          nvl(l.service_number, - 1)     
',
      p_title                  => 'Order Line Workflow is Stuck at Ship Line Notified Status',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Shipped Quantity and Actual Shipment Date on the Order Line is also updated.
Line workflow is stuck at Ship Line activity in Notified status.
Unable to progress the line and cannot invoice the customer.',
      p_solution               => 'Please log a service request for datafix provided in [1354799/KB727780] ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_SHIPPED_WORKFLOW_STUCK _AT_SHIPLINE_NOTIFIED_STATUS');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_PENDING_SHIPPING_TRX');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22606',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_PENDING_SHIPPING_TRX',
      p_sig_sql                => 'select 
om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
lin.flow_status_code,
wdd.source_line_id,
wdd.delivery_detail_id,
wnd.delivery_id,
Decode(wdd.released_status, ''Y'', ''Y=Staged'',
                            ''R'', ''R=Ready to Release'',
                            ''S'', ''S=Rel to Warhouse'',
                            ''B'', ''B=Backorder'',
                            ''P'', ''P=Pending Inv'',
                            ''C'', ''C=Shipped'',
                            ''N'', ''N=Not Ready'',
                            ''D'', ''D=Cancelled'',
                            ''X'', ''X=Not Applicable'',
                            ''Unknown: ''|| released_status) REL_STATUS,
wdd.oe_interfaced_flag,
wdd.inv_interfaced_flag,
wdd.creation_date,
wdl.PICK_UP_STOP_ID,
wdl.drop_off_stop_id,
wts.pending_interface_flag,
wts.actual_departure_date
from wsh_new_deliveries wnd,
wsh_delivery_assignments wda,
wsh_delivery_details wdd,
wsh_delivery_legs wdl,
wsh_trip_stops wts,
oe_order_lines_all lin,
oe_order_headers_all oh
where LIN.header_id = ##$$HEADERID$$##
and NVL(''##$$LINEID$$##'',0) in (0,
                                       LIN.LINE_ID, 
                                       LIN.TOP_MODEL_LINE_ID, 
                                       LIN.ATO_LINE_ID, 
                                       LIN.LINK_TO_LINE_ID, 
                                       LIN.SERVICE_REFERENCE_LINE_ID)
and wnd.delivery_id=wda.delivery_id
and wda.delivery_detail_id = wdd. delivery_detail_id
and wdd.source_header_id = oh.header_id
and lin.line_id = wdd.source_line_id
and wnd.delivery_id = wdl.delivery_id
and wdl.pick_up_stop_id = wts.stop_id
and wdd.source_code = ''OE''
and wdd.released_status = ''C''
and (wdd.oe_interfaced_flag =''N'' or wdd.inv_interfaced_flag in (''P'',''N''))
order by 1',
      p_title                  => 'Unprocessed Shipping Transactions Preventing Period Close',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Unprocessed shipping transactions in current open period that cannot be processed.  These transactions may prevent the period close to complete. ',
      p_solution               => 'These transactions can TEMPORARILY be moved to the next open period to allow the period to close.  <ul><li>Refer to [1197057/KB626119] for details.</li> </ul> ',
      p_success_msg            => 'No unprocessed shipping transactions.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_PENDING_SHIPPING_TRX');



