debug('begin add_signature: EBS_MFG_OM_SEWSHANL_DD_STATUS_STAGED_PICKCONFIRMED_SO_LINE_CLOSED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22732',
      p_sig_id                 => 'EBS_MFG_OM_SEWSHANL_DD_STATUS_STAGED_PICKCONFIRMED_SO_LINE_CLOSED',
      p_sig_sql                => 'SELECT wdd.source_header_number "Order Number",
       wdd.source_header_id "Source Header ID",
       om_order_analyzer_pkg.line_shipment_option(oola.line_number, oola.shipment_number, oola.option_number, oola.component_number, oola.service_number) "Line Number",
       oola.flow_status_code "Line Status",
       wdd.delivery_detail_id "Delivery Detail ID",
       wdd.released_status "Released Status",
       wnd.delivery_id "Delivery ID",
       wnd.status_code "Delivery Status"
  FROM wsh_new_deliveries wnd,
       wsh_delivery_assignments wda,
       wsh_delivery_details wdd,
       oe_order_lines_all oola,
       wsh_delivery_legs wdl,
       wsh_trip_stops wts,
       wsh_trips wt
 WHERE wdd.source_header_id = ##$$HEADERID$$##
   AND oola.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, oola.line_id, oola.top_model_line_id, oola.ato_line_id, oola.link_to_line_id, oola.reference_line_id, oola.service_reference_line_id )
   AND oola.line_id = wdd.source_line_id
   AND wdd.source_code = ''OE''
   AND wdd.released_status = ''Y''
   AND wdd.delivery_detail_id = wda.delivery_detail_id
   AND wda.delivery_id = wdl.delivery_id
   AND wnd.delivery_id = wdl.delivery_id
   AND wnd.status_code = ''CL''
   AND wdl.pick_up_stop_id = wts.stop_id
   AND wts.status_code = ''CL''
   AND wts.trip_id = wt.trip_id
   AND wt.status_code = ''CL''
   AND wnd.delivery_id = wda.delivery_id
   AND wdd.oe_interfaced_flag = ''Y''
   AND nvl(wts.pending_interface_flag, ''N'') <> ''Y''
   AND oola.open_flag = ''N''
 ORDER BY oola.line_number,
          nvl(oola.shipment_number, - 1),
          nvl(oola.option_number, - 1),
          nvl(oola.component_number, - 1),
          nvl(oola.service_number, - 1)     ',
      p_title                  => 'Delivery Detail Staged / Pick Confirmed but SO Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Delivery Detail Status Staged / Pick Confirmed but Sales Order Already Closed',
      p_solution               => 'Refer to [2117490/KB723480] for details',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_SEWSHANL_DD_STATUS_STAGED_PICKCONFIRMED_SO_LINE_CLOSED');



debug('begin add_signature: EBS_MFG_OM_DUPLICATE_DELIVERY_DETAIL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24209',
      p_sig_id                 => 'EBS_MFG_OM_DUPLICATE_DELIVERY_DETAIL',
      p_sig_sql                => 'SELECT wdd.source_line_number "Line Number",
       wdd.source_line_id "Line ID",
       wdd.delivery_detail_id "Del Detail ID",
       wdd.organization_id "Org ID",
       wdd.customer_item_id "Cust Item ID",
       wdd.inventory_item_id "Inventory Item ID",
       wdd.released_status "Release Status",
       wdd.oe_interfaced_flag "OE Interfaced",
       wdd.inv_interfaced_flag "INV Interfaced",
       wdd.picked_quantity "Picked QTY",
       wdd.shipped_quantity "Shipped QTY",
       ool.flow_status_code "Line Staus",
       ool.open_flag "Line Open",
       ool.cancelled_flag "Line Cancelled",
       ool.ordered_quantity "Ordered Qty",
       ool.shipped_quantity "Shipped Qty"
  FROM wsh_delivery_details wdd,
       oe_order_lines_all ool,
       wsh_delivery_assignments wda,
       wsh_delivery_legs wdl,
       wsh_trip_stops wts
 WHERE wdd.source_code = ''OE''
   AND wdd.oe_interfaced_flag = ''N''
   AND wdd.released_status <> ''D''
   AND wdd.source_line_id = ool.line_id
   AND wdd.delivery_detail_id = wda.delivery_detail_id
   AND wda.delivery_id = wdl.delivery_id
   AND wdl.pick_up_stop_id = wts.stop_id
   AND ool.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, ool.line_id, ool.top_model_line_id, ool.ato_line_id, ool.link_to_line_id, ool.reference_line_id, ool.service_reference_line_id )
   AND EXISTS (
  SELECT 1
    FROM wsh_delivery_details wdd1
   WHERE wdd1.source_code = ''OE''
     AND wdd.source_line_id = wdd1.source_line_id
     AND wdd1.oe_interfaced_flag = ''Y''
   GROUP BY wdd1.source_line_id
  HAVING SUM(wdd1.shipped_quantity) = ool.ordered_quantity )
  ',
      p_title                  => 'Duplicate Delivery Details',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Trip Stop/Delivery consists of  Invalid/Duplicate Delivery Details in WSH_DELIVERY_DETAILS table, but the Sales Order Line is fully Shipped and Closed.',
      p_solution               => 'There should not exist two Details for the problematic Order Line, because the entire ordered quantity was Shipped on a single Delivery Detail.
<ul><li>Refer to [2030732/KB737210] for details.</li> </ul> ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_DUPLICATE_DELIVERY_DETAIL');



debug('begin add_signature: EBS_MFG_OM_ONTONESO_INI_P_MTL_ISSUED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24307',
      p_sig_id                 => 'EBS_MFG_OM_ONTONESO_INI_P_MTL_ISSUED',
      p_sig_sql                => 'SELECT
wdd.source_line_number "Line Number",
wdd.delivery_detail_id "Del Detail ID",
wda.delivery_id "Delivery ID",
trp.trip_id "Trip ID",
wts.stop_id "Pick Up Stop ID",
       wdd.released_status|| '': ''
       || ( SELECT meaning
            FROM wsh_lookups
            WHERE lookup_type = ''PICK_STATUS''
              AND lookup_code = wdd.released_status ) "Status",
       wdd.oe_interfaced_flag|| '': ''
       || decode(nvl(wdd.oe_interfaced_flag, ''N''),
                 ''Y'', ''Yes'',
                 ''N'', ''No'',
                 ''P'', ''Pending'',
                 ''X'', ''Not Applicable'',
                 ''Unknown'') "OE Interfaced",
       wdd.inv_interfaced_flag|| '': ''
       || decode(nvl(wdd.inv_interfaced_flag, ''N''),
                 ''Y'', ''Yes'',
                 ''N'', ''No'',
                 ''P'', ''Pending'',
                 ''X'', ''Not Applicable'',
                 ''Unknown'') "INV Interfaced"      
FROM
wsh_delivery_details wdd,
wsh_delivery_assignments wda,
wsh_new_deliveries wnd,
wsh_delivery_legs wdl,
wsh_trips trp,
wsh_trip_stops wts
WHERE
wdd.inv_interfaced_flag <> ''Y''
AND wdd.oe_interfaced_flag = ''Y''
AND wdd.source_code = ''OE''
AND wdd.released_status = ''C''
AND wdd.delivery_detail_id = wda.delivery_detail_id
AND wda.delivery_id = wnd.delivery_id
AND wnd.delivery_id = wdl.delivery_id
AND wts.stop_id = wdl.pick_up_stop_id
AND wts.trip_id = trp.trip_id (+)
AND NVL (wts.pending_interface_flag, ''N'') = ''Y''
AND EXISTS (SELECT 1
FROM mtl_material_transactions mmt
WHERE mmt.picking_line_id = wdd.delivery_detail_id)
AND wdd.source_header_id = ##$$HEADERID$$##
AND NVL(''##$$LINEID$$##'',0) in (0, wdd.SOURCE_LINE_ID)
',
      p_title                  => 'Inventory Interface Is Pending but Material Has Been Issued',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Delivery Details are showing as Pending Inventory Interface Interface ( INV_INTERFACED_FLAG = ''P''(INI=P)) with related Trip Stop closed and pending interface flag = Y.  However, the inventory interface did occur and sales order issue exists in inventory for the items.  Expect that the Inventory interface flag would be ''Y''(yes) and the related trip stop pending interface flag would be null.',
      p_solution               => 'The issue is caused by data corruption in the WSH_DELIVERY_DETAILS table where the INVENTORY_INTERFACE_FLAG = ''P'' and should reflect as ''Y'',
since there exists sales order issue for the lines in the MTL_MATERUAL_TRANSACTIONS table.  A data fix will need to be provided from Support.  Refer to [2258159/KB741832] for details. ',
      p_success_msg            => 'No data corruption exist.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONTONESO_INI_P_MTL_ISSUED');



debug('begin add_signature: EBS_MFG_OM_ONTONESO_SUPPLY_ELIGIBLE_NOT_INTERFACED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24309',
      p_sig_id                 => 'EBS_MFG_OM_ONTONESO_SUPPLY_ELIGIBLE_NOT_INTERFACED',
      p_sig_sql                => 'select 
om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line",
ol.line_id "Line ID",
ol.ordered_quantity "Ordered Qty",
ol.shipped_quantity "Shipped Qty",
ol.flow_status_code "Flow Status"
from oe_order_lines_all ol
where ol.open_flag = ''Y''
and ol.flow_status_code = ''SUPPLY_ELIGIBLE''
and nvl(ol.shippable_flag,''N'') = ''Y''
and nvl(ol.shipping_interfaced_flag,''N'') = ''Y''
and nvl(ol.ato_line_id,-99) = ol.line_id
and nvl(ol.ordered_quantity,0) > 0
and nvl(ol.shipped_quantity,0) = 0
and nvl(ol.fulfilled_flag,''N'') = ''N''
and nvl(ol.fulfilled_quantity,0) = 0
and exists
(select 1 from wf_process_activities p, wf_item_activity_statuses s
where p.instance_id = s.process_activity
and item_type = ''OEOL''
and item_key = to_char(ol.line_id)
and p.activity_name = ''CREATE_SUPPLY_ORDER_ELIGIBLE''
and p.process_name = ''CREATE_SUPPLY_ORDER_PROCESS''
and s.activity_status = ''NOTIFIED'')
and exists (select 1 from wsh_delivery_details dt
WHERE dt.source_code = ''OE''
AND dt.source_line_id = ol.line_id
AND dt.released_status = ''C''
AND nvl(dt.oe_interfaced_flag,''N'') = ''N''
AND nvl(dt.shipped_quantity,0) = ol.ordered_quantity)
AND ol.header_id = ##$$HEADERID$$##
AND NVL(''##$$LINEID$$##'',0) in (0, ol.LINE_ID, ol.TOP_MODEL_LINE_ID, ol.ATO_LINE_ID, ol.LINK_TO_LINE_ID, ol.SERVICE_REFERENCE_LINE_ID)
',
      p_title                  => 'Lines are SUPPLY_ELIGIBLE, Shipped but not Interfaced',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Order Line status is in SUPPLY_ELIGIBLE and associated delivery details are shipped but NOT interfaced to OM or INV.',
      p_solution               => 'A data fix will need to be provided from Support.  Refer to [732842/KB716412] for details. ',
      p_success_msg            => 'No data corruption exist.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONTONESO_SUPPLY_ELIGIBLE_NOT_INTERFACED');



debug('begin add_signature: EBS_MFG_OM_ONTONESO_DD_NOT_INTF_TRIP_CLOSED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24335',
      p_sig_id                 => 'EBS_MFG_OM_ONTONESO_DD_NOT_INTF_TRIP_CLOSED',
      p_sig_sql                => 'SELECT DISTINCT wdd.source_line_id "Source Line ID",
                wts.stop_id "Stop ID",
                wts.trip_id "Trip ID",
                wdd.oe_interfaced_flag "OE Interface",
                wdd.inv_interfaced_flag "INV Interface",
                wts.pending_interface_flag "Pending Interface"
  FROM wsh_delivery_details wdd,
       wsh_delivery_assignments wda,
       wsh_new_deliveries wnd,
       wsh_delivery_legs wdl,
       wsh_trip_stops wts
 WHERE wdd.source_code = ''OE''
   AND wdd.released_status = ''C''
   AND ( wdd.oe_interfaced_flag IN ( ''N'', ''P'' )
    OR wdd.inv_interfaced_flag IN ( ''N'', ''P'' ) )
   AND wdd.delivery_detail_id = wda.delivery_detail_id
   AND wda.delivery_id = wnd.delivery_id
   AND wnd.delivery_id = wdl.delivery_id
   AND wdl.pick_up_stop_id = wts.stop_id
   AND wts.pending_interface_flag IS NULL
   AND wdd.source_header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN (0, wdd.source_line_id)',
      p_title                  => 'Delivery Nor Trip Stop Are Available For ITS Run',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are delivery details showing as SHIPPED with next step as RUN INTERFACE.  When attempting to run the Interface Trip Stop (ITS) to interface these delivery details, the corresponding delivery id and/or trip stop are not available.',
      p_solution               => 'The pending_interface flag in the WSH_TRIP_STOPS table is either NULL or has a value of P.   Only trip stops which have a pending_interface  flag value = ''Y'' will be displayed in the ITS LOV to select in the Interface Trip Stop SRS parameters form.  Refer to [885949/KB745367] for details. ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONTONESO_DD_NOT_INTF_TRIP_CLOSED');



