       nvl(lin.shipped_quantity, 0) "Shipped Qty",
       nvl(lin.shipping_quantity, 0) "Shipping Qty",
       nvl(fulfilled_quantity, 0) "Fulfilled Qty",
       nvl(lin.cancelled_quantity, 0) "Cancelled Qty",
       nvl(lin.invoiced_quantity, 0) "Invoiced Qty",
       nvl(lin.open_flag, ''N'') "Open",
       nvl(lin.booked_flag, ''N'') "Booked",
       nvl(lin.shippable_flag, ''N'') "Shipped",
       nvl(lin.cancelled_flag, ''N'') "Cancelled",
       nvl(lin.fulfilled_flag, ''N'') "Fullfilled",
       nvl(lin.shipping_interfaced_flag, ''N'') "Shipping Interface",
       lin.ship_from_org_id "Ship From",
       nvl(lin.invoice_interface_status_code, ''N'') "Invoice Interface",
       lin.ship_tolerance_above "Ship Tolerance Above",
       lin.ship_tolerance_below "Ship Tolerance Below",
       to_char(lin.actual_shipment_date, ''DD-MON-RR_HH24:MI:SS'') "Actual Ship",
       to_char(lin.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Create Date",
       to_char(lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Update Date"
  FROM oe_order_headers_all ord,
       oe_order_lines_all lin
 WHERE ord.header_id = ##$$HEADERID$$##
   AND lin.header_id = ##$$HEADERID$$##
   AND lin.shipped_quantity IS NOT NULL
   AND lin.ordered_quantity != lin.shipped_quantity
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id )
 ORDER BY nvl(lin.line_set_id, 0),
          lin.line_number,
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Line Ordered Qty does not equal Shipped Qty',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Shipped Qty does not equal Ordered Qty.',
      p_solution               => '<p>Verify the Shipped Qty is within tolerance based on your profile option settings: </p>
<ul>
<li>OM: Over Shipment Tolerance </li>
<li>OM: Under Shipment Tolerance </li>
<li>OM: Over Return Tolerance </li>
<li>OM: Under Return Tolerance</li>
</ul>
<p>Refer to [209023/KB478488] for details.</p>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_ORD_QTY_NOT_EQUAL_SHIPPED_QTY');



debug('begin add_signature: SALES_ORDER_LINE_SHIPPED_NOT_INTERFACED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2413',
      p_sig_id                 => 'SALES_ORDER_LINE_SHIPPED_NOT_INTERFACED',
      p_sig_sql                => 'SELECT det.delivery_detail_id "Del Det ID",
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "SO Line",
       lin.line_id "SO Line ID",
       det.released_status|| '': ''|| (
         SELECT meaning FROM wsh_lookups WHERE lookup_type = ''PICK_STATUS'' AND lookup_code = det.released_status) "Status",
       det.oe_interfaced_flag|| '': '' 
       || decode(nvl(det.oe_interfaced_flag, ''N''),
                 ''Y'', ''Yes'',
                 ''N'', ''No'',
                 ''P'', ''Pending'',
                 ''X'', ''Not Applicable'',
                 ''Unknown'') "OE Interfaced",
       det.inv_interfaced_flag|| '': ''
       || decode(nvl(det.inv_interfaced_flag, ''N''),
                 ''Y'', ''Yes'',
                 ''N'', ''No'',
                 ''P'', ''Pending'',
                 ''X'', ''Not Applicable'',
                 ''Unknown'') "INV Interfaced",
       wnd.delivery_id "Delivery ID",       
       lin.inventory_item_id "Item ID",
       substr(lin.flow_status_code, 1, 22) "Workflow Status",
       nvl(lin.ordered_quantity, 0) "Ordered QTY",
       lin.order_quantity_uom "Ordered UOM",
       nvl(lin.shipped_quantity, 0) "Shipped QTY",
       nvl(lin.shipping_quantity, 0) "Shipping QTY",
       nvl(fulfilled_quantity, 0) "Fulfilled QTY",
       nvl(lin.cancelled_quantity, 0) "Cancelled QTY",
       nvl(lin.invoiced_quantity, 0) "Invoiced QTY",
       nvl(lin.open_flag, ''N'') "Open",
       nvl(lin.booked_flag, ''N'') "Booked",
       nvl(lin.shippable_flag, ''N'') "Shipped",
       nvl(lin.cancelled_flag, ''N'') "Cancelled",
       nvl(lin.fulfilled_flag, ''N'') "Fullfilled",
       nvl(lin.shipping_interfaced_flag, ''N'') "Shipping Interface",
       lin.ship_from_org_id "Ship From",
       nvl(lin.invoice_interface_status_code, ''N'') "Invoice Interface",
       lin.ship_tolerance_above "Ship Tolerance Above",
       lin.ship_tolerance_below "Ship Tolerance Below",
       to_char(lin.actual_shipment_date, ''DD-MON-RR_HH24:MI:SS'') "Actual Ship",
       to_char(lin.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Create Date",
       to_char(lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Update Date"
  FROM oe_order_headers_all ord,
       oe_order_lines_all lin,
       wsh_delivery_details det,
       wsh_new_deliveries wnd,
       wsh_delivery_assignments wda
 WHERE
       ord.header_id = ##$$HEADERID$$##
   AND lin.header_id = ##$$HEADERID$$##
   AND det.source_line_id = lin.line_id
   AND det.source_code = ''OE''
   AND det.delivery_detail_id = wda.delivery_detail_id
   AND wda.delivery_id = wnd.delivery_id
   AND wnd.status_code = ''CO''
   AND det.oe_interfaced_flag = ''N''
   AND lin.shippable_flag = ''Y''
   AND nvl(det.released_status, ''N'') NOT IN ( ''C'', ''I'' )
   AND nvl(lin.shipped_quantity, 0) > 0
   AND NVL(''##$$LINEID$$##'',0) in (0,LIN.LINE_ID, LIN.TOP_MODEL_LINE_ID, LIN.ATO_LINE_ID, LIN.LINK_TO_LINE_ID, LIN.SERVICE_REFERENCE_LINE_ID)
ORDER BY lin.line_number,
         nvl(lin.shipment_number, - 1),
         nvl(lin.option_number, - 1),
         nvl(lin.component_number, - 1),
         nvl(lin.service_number, - 1),
         det.delivery_detail_id',
      p_title                  => 'Delivery is Shipped Confirmed but not Shipped',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Delivery is ship confirmed successfully, but delivery details do not progress to SHIPPED or INTERFACED',
      p_solution               => 'Refer to [1147826/KB627126] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_SHIPPED_NOT_INTERFACED');



debug('begin add_signature: SALES_ORDER_LINE_CLOSED_SHIPPED_NOT_INTERFACED_INI');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2415',
      p_sig_id                 => 'SALES_ORDER_LINE_CLOSED_SHIPPED_NOT_INTERFACED_INI',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option (lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       lin.inventory_item_id "Item ID",
       substr (lin.flow_status_code, 1, 22) "Workflow Status",
       nvl (lin.ordered_quantity, 0) "Ordered QTY",
       lin.order_quantity_uom "Ordered UOM",
       nvl (lin.shipped_quantity, 0) "Shipped QTY",
       nvl (lin.shipping_quantity, 0) "Shipping QTY",
       nvl (fulfilled_quantity, 0) "Fulfilled QTY",
       nvl (lin.cancelled_quantity, 0) "Cancelled QTY",
       nvl (lin.invoiced_quantity, 0) "Invoiced QTY",
       nvl (lin.open_flag, ''N'') "Open",
       nvl (lin.booked_flag, ''N'') "Booked",
       nvl (lin.shippable_flag, ''N'') "Shipped",
       nvl (lin.cancelled_flag, ''N'') "Cancelled",
       nvl (lin.fulfilled_flag, ''N'') "Fullfilled",
       nvl (lin.shipping_interfaced_flag, ''N'') "Shipping Interface",
       lin.ship_from_org_id "Ship From",
       nvl (lin.invoice_interface_status_code, ''N'') "Invoice Interface",
       lin.ship_tolerance_above "Ship Tolerance Above",
       lin.ship_tolerance_below "Ship Tolerance Below",
       to_char (lin.actual_shipment_date, ''DD-MON-RR_HH24:MI:SS'') "Actual Ship",
       to_char (lin.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Create Date",
       to_char (lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Update Date"
  FROM oe_order_headers_all ord,
       oe_order_lines_all lin,
       wsh_delivery_details det
 WHERE ORD.HEADER_ID = ##$$HEADERID$$##
   AND LIN.HEADER_ID = ##$$HEADERID$$##
   AND det.source_line_id = lin.line_id
   AND det.source_code = ''OE''
   AND det.inv_interfaced_flag = ''N''
   AND det.oe_interfaced_flag = ''Y''
   AND nvl (det.released_status, ''N'') <> ''D''
   AND lin.shippable_flag = ''Y''
   AND nvl (lin.shipped_quantity, 0) > 0
   AND lin.flow_status_code = ''CLOSED''
   AND NVL(''##$$LINEID$$##'',0) in (0,LIN.LINE_ID, LIN.TOP_MODEL_LINE_ID, LIN.ATO_LINE_ID, LIN.LINK_TO_LINE_ID, LIN.SERVICE_REFERENCE_LINE_ID)
 ORDER BY nvl (lin.line_set_id, 0),
          lin.line_number,
          nvl (lin.shipment_number, - 1),
          nvl (lin.option_number, - 1),
          nvl (lin.service_number, - 1)',
      p_title                  => 'Sales Order Line Closed, Shipped, not Interfaced to Inventory',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Line is Closed, Shipped but not interfaced to Inventory.',
      p_solution               => '<p>Delivery Details can still be interfaced even when the line is CLOSED.  Try to run Interface Trip Stop.  </p>
<ul>
<li>Navigation:  Shipping > Interfaces > Run > Single Request > Interface Trip Stop - SRS</li>
<li>Mode = Inventory</li>
</ul>
<p>Refer to [2332638/KB626952] for details.</p>


',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_CLOSED_SHIPPED_NOT_INTERFACED_INI');



debug('begin add_signature: EBS_MFG_OM_SHIP_NOTIFIED_SO_LINE_CLOSE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24197',
      p_sig_id                 => 'EBS_MFG_OM_SHIP_NOTIFIED_SO_LINE_CLOSE',
      p_sig_sql                => 'select 
wdd.source_line_id "Source Line ID",
wdd.delivery_detail_id "Delivery Detail ID", 
wdd.released_status "Release Status"
from wsh_delivery_details wdd,oe_order_lines_all ol
where wdd.source_code = ''OE''
and wdd.released_status <> ''D''
and wdd.oe_interfaced_flag in (''N'',''P'')
and wdd.source_line_id = ol.line_id
and ol.open_flag = ''N''
and ol.cancelled_flag = ''N''
and not exists ( select ''x''
from wsh_delivery_details wdd1
where wdd1.source_code = ''OE''
and wdd1.source_line_id = wdd.source_line_id
and wdd1.oe_interfaced_flag = ''Y'')
and ol.header_id = ##$$HEADERID$$##
and nvl(''##$$LINEID$$##'',0) in (0, ol.LINE_ID, ol.TOP_MODEL_LINE_ID, ol.ATO_LINE_ID, ol.LINK_TO_LINE_ID)',
      p_title                  => 'Ship Notified But Sales Order Line Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Trip Stop and/or Delivery consists of Sales Order Lines which are in a Closed status.<br>
This will cause the Interface Trip Stop - SRS execution to end in a ''SHIP_LINE'' is not a notified activity error.',
      p_solution               => 'A Datafix from Oracle Support is required.  Log a Service Request (SR) with Oracle Shipping Execution.<br>
Upload this Analyzer output to the SR to assist Oracle Support in providing a Datafix.
Refer to [1628955/KB784765] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_SHIP_NOTIFIED_SO_LINE_CLOSE');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_DELIVERY_SEQUENCE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23858',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_DELIVERY_SEQUENCE',
      p_sig_sql                => 'SELECT sequence_owner "Owner",
       sequence_name "Name",
       last_number "Last Number",
       max_value "Max Value",
       round((100 / max_value) * last_number, 2) AS "% Used",
       round(100 -((100 / max_value) * last_number), 2) AS "% Available"
  FROM dba_sequences
 WHERE sequence_owner IN ( ''WSH'', ''WMS'' )
   AND round((100 / max_value) * last_number, 2) >= 70
   AND cycle_flag <> ''Y''
 ORDER BY 5 DESC, 2',
      p_title                  => 'Shipping Sequences Max Value Checks',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'ID is getting close (=>70%) to Max Value defined in sequences.


',
      p_solution               => 'Refer to [2989870/KA1025] for additional details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_DELIVERY_SEQUENCE');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTSO_MISSING_WSH_DELIVERY_DETAILS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '25964',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTSO_MISSING_WSH_DELIVERY_DETAILS',
      p_sig_sql                => 'select 
om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line",
ol.line_id "Line ID", 
ol.shippable_flag "Shippable", 
ol.booked_flag "Booked", 
ol.cancelled_flag "Cancelled", 
ol.authorized_to_ship_flag "Authorized to Ship",
ol.shipping_interfaced_flag "Shipping Interfaced",
ol.item_type_code "Item Type", 
ol.ship_model_complete_flag "Ship Model Complete", 
ol.ato_line_id "ATO Line ID", 
ol.top_model_line_id "Top Model Line ID"
from 
     oe_order_lines_all ol,
     oe_order_headers_all oh
where 
     oh.header_id = ##$$HEADERID$$##
     and ol.header_id = ##$$HEADERID$$##
     and oh.open_flag = ''Y''
     and ol.open_flag = ''Y''
     and ol.booked_flag =''Y''
     and ol.ordered_quantity > 0
     and nvl(ol.shippable_flag,''N'') = ''Y''
     and NVL(ol.shipping_interfaced_flag,''Y'') =''Y''
     and ol.source_type_code = ''INTERNAL''
     and exists
     (select 1 from wf_process_activities p, wf_item_activity_statuses s
          where p.instance_id = s.process_activity
          and item_type = ''OEOL''
          and item_key = to_char(ol.line_id)
          and p.activity_name = ''SHIP_LINE''
          and s.activity_status in(''ERROR'',''NOTIFIED'')
          and s.end_date IS NULL)
     and NOT exists
          ( select 1 from wsh_delivery_details
           where source_code = ''OE''
           and source_line_id = ol.line_id)',
      p_title                  => 'Delivery Details do not exist for Ship Eligible Line(s)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing WSH_DELIVERY_DETAILS Data for Shipping Interfaced Line(s)',
      p_solution               => 'Log a Service Request to obtain datafix for the line.</br>
For more information regarding this issue, review [2851213/KB723286] for instructions and details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTSO_MISSING_WSH_DELIVERY_DETAILS');



