debug('begin add_signature: SALES_ORDER_DROP_SHIP_SOURCES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1015',
      p_sig_id                 => 'SALES_ORDER_DROP_SHIP_SOURCES',
      p_sig_sql                => 'SELECT src.drop_ship_source_id  "Drop Ship Source ID",
       src.line_id              "SO Line ID",
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "SO Line No",
       src.requisition_header_id       "Req Header ID",
       src.requisition_line_id         "Req Line ID",
       ( SELECT segment1 FROM po_requisition_headers_all WHERE requisition_header_id = src.requisition_header_id) "Req No",
       ( SELECT line_num FROM po_requisition_lines_all WHERE requisition_line_id = src.requisition_line_id) "Req Line No",
       src.po_header_id                "PO Header ID",
       src.po_line_id                  "PO Line ID",
       ( SELECT segment1 FROM po_headers_all WHERE po_header_id = src.po_header_id) "PO No",
       ( SELECT line_num FROM po_lines_all WHERE po_line_id = src.po_line_id) "PO Line No",
       src.org_id               "Org ID",
       ( SELECT name
           FROM hr_operating_units hr
          WHERE src.org_id = hr.organization_id) "Operating Unit",
       src.destination_organization_id "Destination Org ID",
       ( SELECT organization_code 
         FROM mtl_parameters par
         WHERE src.destination_organization_id = par.organization_id ) "Destination Org",
       src.line_location_id            "Line Location ID",
       src.po_release_id               "PO Release ID"
  FROM oe_drop_ship_sources src,
       oe_order_lines_all   lin
 WHERE src.line_id = lin.line_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'',0) in (0,
                                   lin.line_id,
                                   lin.top_model_line_id,
                                   lin.ato_line_id,
                                   lin.link_to_line_id,
                                   lin.service_reference_line_id)
ORDER BY lin.line_number,
         nvl(lin.shipment_number, -1),
         nvl(lin.option_number, -1),
         nvl(lin.component_number, -1),
         nvl(lin.service_number, -1)',
      p_title                  => 'Drop Ship Sources',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no drop ship sources.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
