       financials_system_params_all fsp
 WHERE plc1.lookup_code = nvl(prh.authorization_status, ''INCOMPLETE'')
   AND plc1.lookup_type = ''AUTHORIZATION STATUS''
   AND podb.document_type_code = ''REQUISITION''
   AND podb.document_subtype = prh.type_lookup_code
   AND podb.document_type_code = podt.document_type_code
   AND podb.document_subtype = podt.document_subtype
   AND podt.language = ''US''
   AND podt.org_id = podb.org_id
   AND podb.org_id = prh.org_id
   AND sob.set_of_books_id = fsp.set_of_books_id
   AND fsp.org_id = prh.org_id
   AND src.requisition_header_id = prh.requisition_header_id
   AND src.header_id = ##$$HEADERID$$##
