       ( SELECT vendor_site_code FROM po_vendor_sites_all WHERE vendor_site_id (+) = poh.vendor_site_id ) "Site",
       ( SELECT location_code FROM hr_locations_all_tl WHERE location_id (+) = poh.ship_to_location_id AND language = ''US'' ) "Ship-To",
       ( SELECT location_code FROM hr_locations_all_tl WHERE location_id (+) = poh.bill_to_location_id AND language = ''US'' ) "Bill-To",
       poh.currency_code  "Currency",
       poh.acceptance_required_flag  "Acceptance Required",
       poh.confirming_order_flag     "Confirm Order",
       poh.frozen_flag               "Frozen",
