       poh.freight_terms_lookup_code "Freight Terms",
       poh.pay_on_code               "Pay On"
  FROM po_headers_all       poh,
       oe_drop_ship_sources src
 WHERE src.po_header_id = poh.po_header_id
   AND src.header_id = ##$$HEADERID$$##
UNION ALL
SELECT /* Back-to-Back Orders */
	   DISTINCT
       poh.po_header_id "PO Header ID",
       poh.segment1              "PO Number",
       poh.org_id                "Org ID",
       ( SELECT name FROM hr_operating_units hr WHERE poh.org_id = hr.organization_id ) "Operating Unit",
       ( SELECT meaning FROM fnd_lookup_values_vl WHERE lookup_type = ''POXMUB_DOCUMENT_TYPE'' AND lookup_code = poh.type_lookup_code ) "Type",
       po_headers_sv3.get_po_status(poh.po_header_id) "Status",
       poh.authorization_status "Authorization",
       poh.closed_code          "Closure",
       ( SELECT vendor_name FROM po_vendors WHERE vendor_id (+) = poh.vendor_id ) "Supplier",
       ( SELECT vendor_site_code FROM po_vendor_sites_all WHERE vendor_site_id (+) = poh.vendor_site_id ) "Site",
       ( SELECT location_code FROM hr_locations_all_tl WHERE location_id (+) = poh.ship_to_location_id AND language = ''US'' ) "Ship-To",
       ( SELECT location_code FROM hr_locations_all_tl WHERE location_id (+) = poh.bill_to_location_id AND language = ''US'' ) "Bill-To",
       poh.currency_code  "Currency",
       poh.acceptance_required_flag  "Acceptance Required",
       poh.confirming_order_flag     "Confirm Order",
       poh.frozen_flag               "Frozen",
       poh.fob_lookup_code           "FOB",
