debug('begin add_signature: SALES_ORDER_EXPENSE_DROP_SHIP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15356',
      p_sig_id                 => 'SALES_ORDER_EXPENSE_DROP_SHIP',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(oel.line_number, oel.shipment_number, oel.option_number, oel.component_number, oel.service_number) "Line",
       oel.line_id "Line ID",
       rcv.transaction_id "Transaction ID"
FROM
    rcv_transactions rcv,
    po_line_locations_all poll,
    oe_drop_ship_sources oed,
    oe_order_lines_all oel,
    mtl_system_items_b msib
WHERE
    oel.source_type_code = ''EXTERNAL''
    AND oel.header_id = ##$$HEADERID$$##
    AND NVL(''##$$LINEID$$##'',0) in (0, oel.LINE_ID, oel.TOP_MODEL_LINE_ID, oel.ATO_LINE_ID, oel.LINK_TO_LINE_ID, oel.SERVICE_REFERENCE_LINE_ID)
    AND nvl(oel.shipped_quantity,0) = 0
    AND oed.line_id = oel.line_id
    AND oed.line_location_id IS NOT NULL
    AND poll.line_location_id = oed.line_location_id
    AND rcv.po_line_location_id = poll.line_location_id
    AND oel.flow_status_code = ''AWAITING_RECEIPT''
    AND rcv.transaction_type = ''DELIVER''
    AND oel.split_from_line_id IS NULL
    AND EXISTS (
        SELECT 1
        FROM mtl_material_transactions
        WHERE rcv_transaction_id = rcv.transaction_id )
   AND oel.ship_from_org_id = msib.organization_id
   AND oel.inventory_item_id = msib.inventory_item_id
   AND msib.inventory_asset_flag = ''N''
 ORDER BY oel.line_number,
          nvl(oel.shipment_number, - 1),
          nvl(oel.option_number, - 1),
          nvl(oel.component_number, - 1),
          nvl(oel.service_number, - 1)     ',
      p_title                  => 'Drop Ship Stuck Awaiting Receipt',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Drop Ship Line is Stuck in Awaiting Receipt.',
      p_solution               => '<ul>
<li>Log a Service Request to obtain datafix for the line.</li>
<li>For more information regarding this issue, review [2110685/KB763202] for instructions and details.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_EXPENSE_DROP_SHIP');



debug('begin add_signature: SALES_ORDER_PO_REQUISITIONS_INTERFACE_ALL_IN_PROCESS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '16346',
      p_sig_id                 => 'SALES_ORDER_PO_REQUISITIONS_INTERFACE_ALL_IN_PROCESS',
      p_sig_sql                => 'Select
     RQI.INTERFACE_SOURCE_LINE_ID           "Drop Ship ID",
     om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
     RQI.PROCESS_FLAG                       "Process Flag",
     RQI.REQUEST_ID                         "Request ID",
     RQI.AUTHORIZATION_STATUS               "Authorization Status",   
     RQI.DELIVER_TO_LOCATION_ID             "Delivery To Loc",
     RQI.PREPARER_ID                        "Preparer ID",
     RQI.DESTINATION_ORGANIZATION_ID        "Destination Org ID",
     RQI.DESTINATION_TYPE_CODE              "Destination Type",
     RQI.INTERFACE_SOURCE_CODE              "Source Code",
     RQI.SOURCE_TYPE_CODE                   "Source Type Code",
     RQI.ITEM_ID                            "Item ID",
     to_char(RQI.NEED_BY_DATE,''DD-MON-RR_HH24:MI:SS'')  "Need By",                               
     RQI.QUANTITY                           "Qty",                  
     RQI.UNIT_PRICE                         "Price"
from  PO_REQUISITIONS_INTERFACE_ALL   RQI,
      OE_DROP_SHIP_SOURCES            SRC,
      OE_ORDER_LINES_ALL              LIN
where  SRC.LINE_ID                      = LIN.LINE_ID
  and  RQI.INTERFACE_SOURCE_CODE        = ''ORDER ENTRY'' 
  and  RQI.PROCESS_FLAG                 = ''IN PROCESS''
  and  RQI.REQUEST_ID IS NOT NULL 
  and  SRC.DROP_SHIP_SOURCE_ID          = RQI.INTERFACE_SOURCE_LINE_ID
  and  LIN.HEADER_ID                    = ##$$HEADERID$$##
  and  NVL(''##$$LINEID$$##'',0)    in (0,LIN.LINE_ID,
                                           LIN.TOP_MODEL_LINE_ID,
                                           LIN.ATO_LINE_ID,
                                           LIN.LINK_TO_LINE_ID,
                                           LIN.SERVICE_REFERENCE_LINE_ID)
order by
     NVL(LIN.TOP_MODEL_LINE_ID,            LIN.LINE_ID),
     NVL(LIN.ATO_LINE_ID,               LIN.LINE_ID),
     NVL(LIN.SORT_ORDER,                ''0000''),
     NVL(LIN.LINK_TO_LINE_ID,           LIN.LINE_ID),
     NVL(LIN.SOURCE_DOCUMENT_LINE_ID,   LIN.LINE_ID),
     LIN.LINE_ID',
      p_title                  => 'PO Requisitions Interface is IN PROCESS',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'In process data for the drop ship line exists in PO_REQUISITIONS_INTERFACE_ALL',
      p_solution               => 'Log a Service Request to obtain datafix for the line.  For more information regarding this issue, review [2100484/KB773225] for instructions and details.
',
      p_success_msg            => 'No issues found.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_PO_REQUISITIONS_INTERFACE_ALL_IN_PROCESS');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_SALES_ORDER_CANCEL_FAILURE_REQ_NOT_EXIST');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '23339',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_SALES_ORDER_CANCEL_FAILURE_REQ_NOT_EXIST',
      p_sig_sql                => 'SELECT oeh.order_number "Order Number",
       oeh.header_id "Header ID",
       porh.authorization_status "PO Authorization",
       porh.cancel_flag "PO Cancelled Flag",
       oeh.flow_status_code "Header Status",
       oeh.booked_flag "Booked Flag"
  FROM oe_order_headers_all oeh,
       po_requisition_headers_all porh,
       po_requisition_lines_all porl
 WHERE oeh.source_document_id = porh.requisition_header_id
   AND porh.requisition_header_id = porl.requisition_header_id
   AND oeh.order_source_id = 10
   AND nvl(porl.transferred_to_oe_flag, ''N'') = ''Y''
   AND nvl(porh.transferred_to_oe_flag, ''N'') = ''Y''
   AND oeh.header_id = ##$$HEADERID$$##
   AND oeh.open_flag = ''Y''
   AND nvl(oeh.cancelled_flag, ''N'') = ''N''
   AND nvl(porl.cancel_flag, ''N'') = ''Y''
   AND NOT EXISTS (
  SELECT 1
    FROM oe_order_lines_all oel
   WHERE oeh.header_id = oel.header_id
     AND oel.source_document_id = porh.requisition_header_id
     AND oel.source_document_line_id = porl.requisition_line_id
     AND porh.requisition_header_id = porl.requisition_header_id
     AND oel.order_source_id = 10
     AND oel.org_id = porh.org_id ) ',
      p_title                  => 'Internal SO with no Line(s) and Cancelled Associated Requisition',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Internal Sales Order Header Cancellation Failure',
      p_solution               => 'Internal sales order cancellation fails as line is missing for associated requisition line. Associated requisition line is marked as cancelled and shows it was transferred to Order Management.  To progress the problematic line(s), a data fix is required. Log a service request with Oracle Order Management Support and provide this analyzer. <br><br>

Refer to: [2889377/KB739059] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_SALES_ORDER_CANCEL_FAILURE_REQ_NOT_EXIST');



debug('begin add_signature: EBS_MFG_OM_ONTONESO_DROP_SHIP_DUPLICATES');
