debug('begin add_signature: SALES_ORDER_WF_REQ_APPROVAL_ERRORS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1160',
      p_sig_id                 => 'SALES_ORDER_WF_REQ_APPROVAL_ERRORS',
      p_sig_sql                => 'SELECT ias.item_key             "Item Key",
       ap.display_name          "Process Name",
       ac.display_name          "Activity Name",
       ias.activity_status      "Activity Status",
       ias.activity_result_code "Activity Result",
       pa.process_name          "Process",
       pa.activity_name         "Activity",
       ias.error_name           "Error Name",
       ias.error_message        "Error Message",
       ias.error_stack          "Error Stack",
       ias.begin_date,
       ias.execution_time
  FROM wf_item_activity_statuses ias,
       wf_process_activities     pa,
       wf_activities_vl          ac,
       wf_activities_vl          ap,
       wf_items                  i
 WHERE ias.process_activity = pa.instance_id
   AND pa.activity_name = ac.name
   AND pa.activity_item_type = ac.item_type
   AND pa.process_name = ap.name
   AND pa.process_item_type = ap.item_type
   AND pa.process_version = ap.version
   AND i.item_type = ias.item_type
   AND i.item_key = ias.item_key
   AND i.begin_date >= ac.begin_date
   AND i.begin_date < nvl(ac.end_date, i.begin_date + 1)
   AND ias.activity_status = ''ERROR''
   AND ias.item_type = ''REQAPPRV''
   AND ias.item_key IN 
       ( SELECT /* Dropship */ 
             prh.wf_item_key
           FROM po_requisition_headers_all prh, oe_drop_ship_sources src
          WHERE src.requisition_header_id = prh.requisition_header_id
            AND src.header_id = ##$$HEADERID$$##
         UNION ALL
         SELECT /* Back-to-Back Orders */ 
             prh.wf_item_key
           FROM po_requisition_headers_all prh, mtl_reservations res
          WHERE res.demand_source_type_id = 2  -- Sales order
            AND res.supply_source_type_id = 17 -- External Requisition
            AND res.supply_source_header_id = prh.requisition_header_id
            AND res.demand_source_header_id = ##$$SALESORDERID$$##
         UNION ALL
         SELECT /* Internal Order */ 
             prh.wf_item_key
           FROM po_requisition_headers_all prh, oe_order_lines_all lin
          WHERE lin.order_source_id = 10
            AND lin.source_document_id = prh.requisition_header_id
            AND lin.header_id = ##$$HEADERID$$##       
       )
ORDER BY 1, 11, 12',
      p_title                  => 'Requisition Approval Errors',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Review the Approval Errors.',
      p_solution               => 'For any Requisition Approval issues, you can run the EBS Procurement Approval Analyzer [1525670/KB169264] for additional details and troubleshooting tips.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_WF_REQ_APPROVAL_ERRORS');



