debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_ON_HAND_QTY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24070',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_ON_HAND_QTY',
      p_sig_sql                => 'SELECT msik.concatenated_segments "Item Name",
       moq.organization_id "Org ID",
       mp.organization_code "Org",
       moq.subinventory_code "Sub",
       moq.locator_id "Locator ID",
       moq.lpn_id "LPN ID",
       itm.primary_uom_code "Primary UOM",
       itm.secondary_uom_code "Secondary UOM",
       SUM(moq.transaction_quantity) "Primary On Hand Qty",
       SUM(moq.secondary_transaction_quantity) "Secondary On Hand Qty"
  FROM mtl_onhand_quantities_detail moq,
       oe_order_lines_all lin,
       mtl_parameters mp,
       mtl_system_items itm,
       mtl_system_items_kfv msik
 WHERE lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'',0) in (0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id)
   AND lin.ship_from_org_id = moq.organization_id
   AND lin.inventory_item_id = moq.inventory_item_id
   AND lin.ship_from_org_id = mp.organization_id
   AND lin.inventory_item_id = itm.inventory_item_id
   AND lin.ship_from_org_id = itm.organization_id
   AND lin.ship_from_org_id = msik.organization_id
   AND lin.inventory_item_id = msik.inventory_item_id
 GROUP BY msik.concatenated_segments,
          moq.organization_id,
          mp.organization_code,
          moq.subinventory_code,
          moq.locator_id,
          moq.lpn_id,
          itm.primary_uom_code,
          itm.secondary_uom_code
 ORDER BY 1,2,4,5,6
