       to_char(oac.schedule_close_date, ''DD-MON-RR_HH24:MI:SS'') "Schedule Close Date"
  FROM mtl_transactions_interface tmp,
       wsh_delivery_details det,
       oe_order_lines_all lin,
       mtl_system_items itm,
       org_acct_periods oac,
       wsh_delivery_assignments asg
 WHERE tmp.source_line_id = lin.line_id
   AND lin.line_category_code = ''ORDER''
   AND lin.ship_from_org_id = itm.organization_id (+)
   AND lin.inventory_item_id = itm.inventory_item_id (+)
   AND det.source_line_id = lin.line_id
   AND tmp.picking_line_id = det.delivery_detail_id (+)
   AND tmp.acct_period_id = oac.acct_period_id (+)
   AND det.delivery_detail_id = asg.delivery_detail_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
UNION ALL
SELECT tmp.transaction_interface_id "Transaction Interface ID",
       tmp.transaction_header_id "Transaction Header ID",
       om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       det.delivery_detail_id "Delivery Det ID",
       asg.delivery_id "Delivery ID",
       itm.segment1 "Item",
       tmp.picking_line_id "Pick Line ID",
       decode(tmp.transaction_type_id, 
              52, ''Stage Trans'', 
              33, ''SO Issue'',
              15, ''RMA Receipt'', 
              18, ''PO Receipt'', 
              tmp.transaction_type_id) "Transaction Type",
       tmp.transaction_date "Transaction Date",
       tmp.primary_quantity "Primary Qty",
       tmp.subinventory_code "From Subinventory",
       tmp.locator_id "From LOcator ID",
       tmp.process_flag process,
       tmp.lock_flag "Lock",
       tmp.transaction_mode "Transaction Mode",
       tmp.content_lpn_id "LPN ID",
       tmp.error_code "Error Code",
       tmp.error_explanation "Error Explanation",
       tmp.secondary_uom_code "Secondary UOM Code",
       tmp.secondary_transaction_quantity "Secondary Trx Qty",
       tmp.acct_period_id "Accounting Period",
       oac.period_name "Per Name",
       oac.open_flag "Open Flag",
       to_char(oac.period_start_date, ''DD-MON-RR_HH24:MI:SS'') "Period Start Date",
       to_char(oac.period_close_date, ''DD-MON-RR_HH24:MI:SS'') "Period Close Date",
       to_char(oac.schedule_close_date, ''DD-MON-RR_HH24:MI:SS'') "Schedule Close Date"
  FROM mtl_transactions_interface tmp,
       wsh_delivery_details det,
       oe_order_lines lin,
       mtl_system_items itm,
       org_acct_periods oac,
       wsh_delivery_assignments asg
 WHERE tmp.trx_source_line_id = lin.line_id
   AND lin.line_category_code = ''RETURN''
   AND lin.ship_from_org_id = itm.organization_id (+)
   AND lin.inventory_item_id = itm.inventory_item_id (+)
   AND det.source_line_id = lin.line_id
   AND tmp.picking_line_id = det.delivery_detail_id (+)
   AND tmp.acct_period_id = oac.acct_period_id (+)
   AND det.delivery_detail_id = asg.delivery_detail_id
   AND lin.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id )
',
      p_title                  => 'Material Transactions Interface Lock Flag Stops Process',
      p_fail_condition         => '[Lock] = [1]',
      p_problem_descr          => 'Material Transaction Interface contains lock flag record which halts transactions from being processed.',
      p_solution               => 'Refer to [1063689/KB559654#LOCK_FLAG] for the script to reset locked MTI transactions to resolve this interface lock flag issue.',
      p_success_msg            => 'The material transaction interface record associated with this sales order shows that the lock flag is set properly.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_MTL_TRX_INT_LOCK');



debug('begin add_signature: SALES_ORDER_RELEASE_DETAIL_MOVE_ORDER_CLOSED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '20252',
      p_sig_id                 => 'SALES_ORDER_RELEASE_DETAIL_MOVE_ORDER_CLOSED',
      p_sig_sql                => 'SELECT source_header_id "Order Header Id", 
       SOURCE_HEADER_NUMBER "Order Number",
       SOURCE_LINE_ID "Line id", 
       source_line_number "Line Number",
       DELIVERY_DETAIL_ID,
       MOVE_ORDER_LINE_ID,
       ( SELECT MEANING
           FROM MFG_LOOKUPS ML,
                MTL_TXN_REQUEST_LINES MTRL,
                MTL_TXN_REQUEST_HEADERS MTRH
          WHERE MTRL.HEADER_ID = MTRH.HEADER_ID
            and mtrl.line_id = wdd.move_order_line_id
            AND ML.LOOKUP_TYPE=''MOVE_ORDER_TYPE'' 
            AND ml.lookup_code=mtrh.move_order_type) "MO Type",
       released_status,       
       oe_interfaced_flag,
       inv_interfaced_flag,
       MOVE_ORDER_LINE_ID,
       wdd.SHIP_SET_ID,
       wdd.inventory_item_id,
       item_description
FROM   WSH_DELIVERY_DETAILS WDD,
       OE_ORDER_LINES_ALL OOL
WHERE WDD.SOURCE_LINE_ID = OOL.LINE_ID
  and wdd.source_code = ''OE'' 
  AND WDD.RELEASED_STATUS = ''S''
  AND  WDD.OE_INTERFACED_FLAG = ''N''
  AND WDD.SOURCE_HEADER_ID = ##$$HEADERID$$##  
  AND nvl( ''##$$LINEID$$##'', 0) IN ( 0, ool.line_id, ool.top_model_line_id, ool.ato_line_id, ool.link_to_line_id, ool.reference_line_id, ool.service_reference_line_id )
  AND ( NOT EXISTS (SELECT 1
                       FROM   MTL_TXN_REQUEST_LINES MTRL1
                       WHERE  MTRL1.LINE_ID = WDD.MOVE_ORDER_LINE_ID)
           OR
              EXISTS (SELECT 1
                       FROM   MTL_TXN_REQUEST_LINES MTRL2
                       WHERE  MTRL2.LINE_ID = WDD.MOVE_ORDER_LINE_ID
                         AND  MTRL2.LINE_STATUS = 5)
       )
  AND NOT EXISTS ( SELECT 1
                     FROM MTL_MATERIAL_TRANSACTIONS MMT
                    WHERE MMT.TRX_SOURCE_LINE_ID = WDD.SOURCE_LINE_ID
                      AND MMT.PICKING_LINE_ID = WDD.DELIVERY_DETAIL_ID
                  )',
      p_title                  => 'Released Delivery Details where Move Order is Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Check for detail lines showing status of Released to Warehouse but not able to progress due to move order line/number being closed or deleted. ',
      p_solution               => 'Refer to [1583914/KB627141] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_RELEASE_DETAIL_MOVE_ORDER_CLOSED');



debug('begin add_signature: EBS_MFG_OM_ONTONESO_RMA_RECEIVING_STUCK');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24429',
      p_sig_id                 => 'EBS_MFG_OM_ONTONESO_RMA_RECEIVING_STUCK',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(ol.line_number, ol.shipment_number, ol.option_number, ol.component_number, ol.service_number) "Line",
       ol.line_id "LINE ID", 
       ol.flow_status_code "LINE STATUS",
       ol.ordered_quantity "ORDER QTY",
       decode(nvl(rcv.INSPECTION_STATUS_CODE,0), 
             ''0'',''N'', ''NOT INSPECTED'',''N'', ''INSPECTED'',''Y'', 
              rcv.INSPECTION_STATUS_CODE) "INSPECTED",
       ol.shipped_quantity "RECEIVED QTY",
       ol.fulfilled_quantity "DELIVERED QTY",
       hou.name "OPERATING UNIT"  
FROM oe_order_headers_all oh, 
     oe_order_lines_all ol, 
     rcv_transactions rcv, 
     hr_operating_units hou 
WHERE oh.header_id            = ol.header_id 
    AND ol.header_id = ##$$HEADERID$$##
    AND NVL(''##$$LINEID$$##'',0) in (0, ol.LINE_ID, ol.TOP_MODEL_LINE_ID, ol.ATO_LINE_ID, ol.LINK_TO_LINE_ID, ol.SERVICE_REFERENCE_LINE_ID)
    AND ol.line_id              = rcv.oe_order_line_id 
    AND oh.org_id = hou.organization_id
    AND ol.open_flag			 = ''Y'' 
    AND (( ol.ordered_quantity = 
       (SELECT Sum(rcv.quantity) FROM rcv_transactions rcv 
        WHERE rcv.transaction_type    = ''DELIVER'' 
        AND rcv.oe_order_line_id=ol.line_id)
        AND ol.flow_status_code in (''AWAITING_RETURN_DISPOSITION'',''AWAITING_RETURN'')) 
        OR ( rcv.quantity            = ol.ordered_quantity 
	    and rcv.transaction_type    = ''RECEIVE'' 
	    and ol.flow_status_code     in (''AWAITING_RETURN'')))',
      p_title                  => 'RMA with Stuck Receiving Transaction',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Open SO Lines with stuck receiving transaction.',
      p_solution               => 'Refer to [378221/KB627858] for assistance in progressing the RMA Receipt(s).',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONTONESO_RMA_RECEIVING_STUCK');



