debug('begin add_signature: SALES_ORDER_RA_CUSTOMER_TRX');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1023',
      p_sig_id                 => 'SALES_ORDER_RA_CUSTOMER_TRX',
      p_sig_sql                => 'SELECT rah.customer_trx_id "Customer Trx ID",
       rah.trx_number "Transaction Number",
       rah.batch_source_id "Batch Source ID",
       rbs.name "Batch Source",
       rah.batch_id "Batch ID",
       rah.cust_trx_type_id "Cust Trx Type ID",
       rctt.name "Type Name",
       rctt.type "Invoice Class",
       ( SELECT meaning FROM ar_lookups WHERE lookup_type = ''INVOICE_TRX_STATUS'' AND lookup_code = rah.status_trx ) "Status",
       rah.complete_flag "Complete",
       rah.trx_date "Transaction Date",
       rah.ship_to_customer_id "Ship To Cust ID",
       rah.ship_to_site_use_id "Ship To Site Use ID",
       rah.bill_to_customer_id "Bill To Cust ID",
       rah.bill_to_site_use_id "Bill To Site ID",
       rah.sold_to_customer_id "Sold To Cust ID",
       rah.sold_to_site_use_id "Sold To Site Use ID",
       --rah.term_id "Term ID",
       ( SELECT name FROM ra_terms_tl WHERE language = ''US'' AND term_id = rah.term_id ) "Payment Term",
       rah.term_due_date "Term Due Date",
       --rah.invoicing_rule_id "Invoice Rule ID",
       ( SELECT name FROM ra_rules WHERE rule_id = rah.invoicing_rule_id AND type = ''I'' ) "Invoicing Rule",
       rah.primary_salesrep_id "Sales Rep ID",
       rah.purchase_order "PO Number",
       rah.invoice_currency_code "Currency",
       rah.agreement_id "Agreement ID",
       rah.ship_via "Ship Via",
       rah.waybill_number "Waybill",
       rah.org_id "Org ID"
  FROM ra_customer_trx_all rah,
       ra_batch_sources_all rbs,
       ra_cust_trx_types_all rctt
 WHERE rbs.batch_source_id (+) = rah.batch_source_id
   AND rbs.org_id (+) = rah.org_id
   AND rctt.cust_trx_type_id = rah.cust_trx_type_id
   AND rctt.org_id = rah.org_id
   AND rah.customer_trx_id IN ( --Line
                                SELECT rctl.customer_trx_id
                                FROM ra_customer_trx_lines_all rctl, 
								     oe_order_lines_all lin, 
									 oe_order_headers_all ord, 
									 oe_transaction_types_tl typ
                                WHERE rctl.interface_line_context = fnd_profile.value(''ONT_SOURCE_CODE'')
                                  AND rctl.interface_line_attribute1 = ''##$$ORDERNO$$##''
                                  AND rctl.interface_line_attribute2 = typ.name
                                  AND typ.transaction_type_id = ord.order_type_id
                                  AND typ.language = ''US''
                                  AND rctl.sales_order = ''##$$ORDERNO$$##''
                                  AND ord.header_id = lin.header_id
                                  AND rctl.line_type = ''LINE''
                                  AND rctl.interface_line_attribute6 = lin.line_id
                                  AND ord.header_id = ##$$HEADERID$$##
                                  AND nvl(''##$$LINEID$$##'',0) in (0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id)
                                UNION ALL
                                -- Freight
								SELECT rctl.customer_trx_id
                                FROM ra_customer_trx_lines_all rctl, 
								     oe_order_lines_all lin,
                                     oe_order_headers_all ord, 
									 oe_transaction_types_tl typ, 
									 oe_charge_lines_v ocl
                                WHERE rctl.interface_line_context = fnd_profile.value(''ONT_SOURCE_CODE'')
                                  AND rctl.interface_line_attribute1 = ''##$$ORDERNO$$##''
                                  AND rctl.interface_line_attribute2 = typ.name
                                  AND typ.transaction_type_id = ord.order_type_id
                                  AND typ.language = ''US''
                                  AND rctl.sales_order = ''##$$ORDERNO$$##''
                                  AND ord.header_id = lin.header_id
                                  AND ord.header_id = ocl.header_id
                                  AND lin.line_id = ocl.line_id
                                  AND rctl.line_type = ''FREIGHT''
                                  AND rctl.interface_line_attribute6 = ocl.charge_id
                                  AND ord.header_id = ##$$HEADERID$$##
                                  AND nvl(''##$$LINEID$$##'',0) in (0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.reference_line_id, lin.service_reference_line_id)
                              )
ORDER BY 1',
      p_title                  => 'Invoice Headers',
