debug('begin add_signature: CUST_TRX_TYPE_ID IS REQUIRED FOR INVOICE INTERFACE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '13997',
      p_sig_id                 => 'CUST_TRX_TYPE_ID IS REQUIRED FOR INVOICE INTERFACE',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
       --msg.header_id "Header ID",
       msg.line_id "Line ID",
       decode(msg.message_source_code, 
              ''U'', ''U=On-Line(UI)'', 
              ''C'', ''C=Conc Process'',
              ''W'', ''W=Workflow'', 
              msg.message_source_code) "Message Source",
       msg.process_activity "Process Activity",
       msg.request_id "Request ID",
       mst.message_text "Message Text"
  FROM oe_processing_msgs_vl msg,
       oe_processing_msgs_tl mst,
       oe_order_lines_all lin,
       fnd_languages fla
 WHERE lin.open_flag = ''Y''
   AND lin.invoice_interface_status_code = ''NO''
   AND msg.header_id = ##$$HEADERID$$##
   AND msg.header_id = lin.header_id
   AND msg.transaction_id = mst.transaction_id
   AND mst.language = fla.language_code
   AND fla.installed_flag = ''B''
   AND msg.line_id = lin.line_id
   AND msg.line_id IS NOT NULL
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id )
   AND mst.message_text = ''Cust_Trx_Type_Id is required for Invoice Interface.''
   AND EXISTS (
  SELECT item_key
    FROM wf_item_activity_statuses_v
   WHERE item_key = to_char(lin.line_id)
     AND activity_status_code = ''NOTIFIED''
     AND activity_name = ''INVOICE_INTERFACE_ELIGIBLE''
     AND activity_end_date IS NULL
     AND EXISTS (
    SELECT item_key
      FROM wf_item_activity_statuses_v
     WHERE item_key = to_char(lin.line_id)
       AND activity_status_code = ''COMPLETE''
       AND activity_name = ''INVOICE_INTERFACE''
       AND activity_result_code = ''INCOMPLETE''
       AND activity_end_date IS NOT NULL ) )
 ORDER BY lin.line_number,
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.component_number, - 1),
          nvl(lin.service_number, - 1)  ',
      p_title                  => 'CUST_TRX_TYPE_ID Is Required For Invoice Interface',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales order line status is Awaiting Invoice Interface - Incomplete Data and will not progress,<br>
The following processing error message occurs:<br><br>

ERROR<br>
Order Line Processing messages<br>
Cust_Trx_Type_id is required for Invoice Interface.',
      p_solution               => '1. Please download cust_trx_type.sql  from note: Receiving Error: Cust_Trx_Type_id is required for Invoice Interface. <ul><li>[1951706/KB739013]</li></ul> < br>
2. Login to SQLPLUS using user APPS and Execute the attached  cust_trx_type.sql for problematic Line ID<br><br>
Please follow below steps to fetch Line ID from the form <br>
A. Query the Sales Order from Sales Order form.<br>
B. Go to Line Items tab. Place your cursor on problematic Sales Order Line and then, go to Help > Diagnostics > Examine
For Block = LINE, Select the Field as LINE_ID and note down the value.<br>
3. The script cust_trx_type.sql output will print the action plan which will guide you with the missing setup and what needs to be setup and where needs to be setup.<br>
4. Complete the Setup as suggested and then Open the Sales Order and go to Line Items tab. Place Your cursor on problematic sales order line then Click on Actions Button and then Select Progress Order to progress the Line further. <br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: CUST_TRX_TYPE_ID IS REQUIRED FOR INVOICE INTERFACE');



