debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_WAIT_FOR_CTO_NOTIFIED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '24777',
      p_sig_id                 => 'EBS_MFG_OM_ONT_ONTONESO_WAIT_FOR_CTO_NOTIFIED',
      p_sig_sql                => 'SELECT p.instance_label,
       s.activity_status,
       le.line_id
  FROM wf_item_activity_statuses s,
       wf_process_activities p,
       oe_order_lines_all le
 WHERE le.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, le.line_id, le.top_model_line_id, le.ato_line_id, le.link_to_line_id, le.service_reference_line_id )
   AND s.process_activity = p.instance_id
   AND s.item_type = ''OEOL''
   AND p.activity_name = ''WAIT_FOR_CTO''
   AND s.activity_status = ''NOTIFIED''
   AND s.item_key = to_char(le.line_id)
   AND EXISTS (
  SELECT 1
    FROM wf_item_activity_statuses s2,
         wf_process_activities p2,
         oe_order_lines_all l
   WHERE l.item_type_code = ''CONFIG''
     AND l.ato_line_id = TO_NUMBER(s.item_key)
     AND s2.item_key = to_char(l.line_id)
     AND s2.item_type = ''OEOL''
     AND p2.instance_id = s2.process_activity
     AND p2.activity_name = ''FULFILL_LINE''
     AND s2.activity_status = ''NOTIFIED'' )',
      p_title                  => 'Model Line is Stuck In BOOKED status with Fulfilled Quantity Populated Cannot Progress to Invoicing',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Order lines have successfully shipped and interfaced, Model lines are still in a BOOKED status yet the fulfilled quantity is populated.
Other lines are in an AWAITING FULFILLMENT Status. 

Line workflow for the model lines shows that the Wait FOR CTO workflow activity is Notified and the Create Configuration Line Manual is complete.',
      p_solution               => 'A data fix will be required.
Refer to [2747411/KB720399] for details.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONT_ONTONESO_WAIT_FOR_CTO_NOTIFIED');



debug('begin add_signature: EBS_MFG_OM_ONTONESO_INVOICE_PENDING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '26167',
      p_sig_id                 => 'EBS_MFG_OM_ONTONESO_INVOICE_PENDING',
      p_sig_sql                => 'SELECT   
     h.order_number "Order Number",
     l.header_id "Header ID",
     h.flow_status_code "Header Status",
     om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line",
     l.line_id "LINE_ID",
     l.item_type_code  "Item Type",
     h.ship_from_org_id  "Order Ship From Org ID",
     l.ship_from_org_id  "Line Ship From Org ID",
     dl.name  "Delivery Name",
     dl.gross_weight  "Del Gross Weight",
     dl.net_weight AS "Del Net Weight",
     l.inventory_item_id "Item ID",
     mtl.segment1  "Item Ordered",
     l.ordered_quantity "Order Qty",
     l.shipped_quantity "Shipped Qty",
     l.fulfilled_quantity "Fulfilled Qty",
     l.invoiced_quantity "Inv Qty",
     mtl.unit_weight  "Item Unit Weight",
     mtl.weight_uom_code  "Weight UOM Code",
     substr(l.flow_status_code, 1, 20) "Line Status",
     substr(nvl(l.invoice_interface_status_code, '' ''),1,15) "Invoice Interface",
     dl.delivery_id "Delivery ID",
     dd.oe_interfaced_flag "OM Interface",
     nvl(dd.inv_interfaced_flag, ''N'') "INV Interface",
     dd.delivery_detail_id "Delivery Detail ID",
     dd.requested_quantity "Requested Qty",
     dd.shipped_quantity "Shipped QTY",
     substr(decode(dd.released_status, ''Y'', ''Y=Staged'', ''R'', ''R=Ready to Relese'',''S'', ''S=Rel to Warehouse'', ''B'', ''B=Backorder'', ''P'', ''P=Pending Inv'', ''C'',''C=Shipped'', ''N'', ''N=Not Ready'',''D'', ''D=Cancelled'', ''X'', ''X=Not Applicable'', dd.released_status),1,18) "Release Status",
     substr(decode(dl.status_code, ''CL'', ''CL=Closed'', ''CO'', ''CO=Confirmed'',''IT'', ''IT=In-Transit'', ''OP'', ''OP=Open'', ''PA'',''PA=Packed'', ''SA'', ''SA=Shipment Advice Received'', ''SC'', ''SC=Shipment Cancellation Request'',''SR'', ''SR=Shipment Requested'', dl.status_code),1,30) "Delivery Status",
     dl.confirm_date  "Confirm Date",
     l.model_remnant_flag  "Model Remnant",
     l.shippable_flag  "Shippable"
 FROM
        wsh_new_deliveries dl,
        wsh_delivery_assignments da,
        wsh_delivery_details dd,
        oe_order_headers_all h,
        oe_order_lines_all l,
        mtl_system_items_b mtl
WHERE
  l.header_id = ##$$HEADERID$$##
  AND   NVL(''##$$LINEID$$##'',0) in (0,L.LINE_ID,L.TOP_MODEL_LINE_ID,L.ATO_LINE_ID,L.LINK_TO_LINE_ID,L.SERVICE_REFERENCE_LINE_ID)
  AND   dd.delivery_detail_id = da.delivery_detail_id
  AND   da.delivery_id = dl.delivery_id
  AND   dd.source_code = ''OE''
  AND   h.header_id = l.header_id
  AND   l.line_id = dd.source_line_id
  AND   mtl.organization_id = nvl(l.ship_from_org_id, h.ship_from_org_id)
  AND   mtl.inventory_item_id = l.inventory_item_id
  AND   EXISTS (
                SELECT 1
                  FROM
                        oe_order_lines_all l2,
                        wsh_new_deliveries dl2,
                        wsh_delivery_assignments da2,
                        wsh_delivery_details dd2
                 WHERE
                        dl2.status_code = ''CL''
                   AND  dd2.delivery_detail_id = da2.delivery_detail_id
                   AND  da2.delivery_id = dl2.delivery_id
                   AND  dd2.source_code = ''OE''
                   AND  l2.line_id = dd2.source_line_id
                   AND  nvl(l2.invoice_interface_status_code, ''N'') = ''MANUAL-PENDING''
                   AND  l2.flow_status_code = ''INVOICE_DELIVERY''
                   AND  l2.open_flag = ''Y''
                   AND  l2.cancelled_flag = ''N''
                   AND  dl2.name = dl.name
                )
ORDER BY
        9,
        2,
        5',
      p_title                  => 'Line Awaiting Invoice Interface - Pending Complete Delivery',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Line(s) that reach invoicing activity will wait at ''INVOICING_WAIT_FOR_RFR'' activity, and will remain at this activity unless all other lines belongs to same delivery reach this stage.  ',
      p_solution               => 'Refer to [2421331/KB720757] Sales Orders Stuck With Status #Awaiting Invoice Interface - Pending Complete Delivery.',
      p_success_msg            => 'All line(s) have progressed properly.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: EBS_MFG_OM_ONTONESO_INVOICE_PENDING');



debug('begin add_signature: SALES_ORDER_LINES_ORD_QTY_NOT_EQUAL_INVOICE_QTY');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2387',
      p_sig_id                 => 'SALES_ORDER_LINES_ORD_QTY_NOT_EQUAL_INVOICE_QTY',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line Number",
       lin.line_id "Line ID",
       lin.inventory_item_id "Item ID",
       substr(lin.flow_status_code, 1, 22) "Workflow Status",
       nvl(lin.ordered_quantity, 0) "Ordered Qty",
       lin.order_quantity_uom "Ordered UOM",
       nvl(lin.shipped_quantity, 0) "Shipped Qty",
       nvl(lin.shipping_quantity, 0) "Shipping Qty",
       nvl(fulfilled_quantity, 0) "Fulfilled Qty",
       nvl(lin.cancelled_quantity, 0) "Cancelled Qty",
       nvl(lin.invoiced_quantity, 0) "Invoiced Qty",
       nvl(lin.open_flag, ''N'') "Open",
       nvl(lin.booked_flag, ''N'') "Booked",
       nvl(lin.shippable_flag, ''N'') "Shipped",
       nvl(lin.cancelled_flag, ''N'') "Cancelled",
       nvl(lin.fulfilled_flag, ''N'') "Fullfilled",
       nvl(lin.shipping_interfaced_flag, ''N'') "Shipping Interface",
       lin.ship_from_org_id "Ship From",
       nvl(lin.invoice_interface_status_code, ''N'') "Invoice Interface",
       lin.ship_tolerance_above "Ship Tolerance Above",
       lin.ship_tolerance_below "Ship Tolerance Below",
       to_char(lin.actual_shipment_date, ''DD-MON-RR_HH24:MI:SS'') "Actual Ship",
       to_char(lin.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Create Date",
       to_char(lin.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Update Date"
  FROM oe_order_headers_all ord,
       oe_order_lines_all lin
 WHERE ord.header_id = ##$$HEADERID$$##
   AND lin.header_id = ##$$HEADERID$$##
   AND lin.shipped_quantity IS NOT NULL
   AND lin.ordered_quantity != abs(lin.invoiced_quantity)
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id )
 ORDER BY nvl(lin.line_set_id, 0),
          lin.line_number,
          nvl(lin.shipment_number, - 1),
          nvl(lin.option_number, - 1),
          nvl(lin.service_number, - 1)',
      p_title                  => 'Sales Order Line Ordered Qty does not equal Invoiced Qty',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order Line Ordered Qty does not equal the amount invoiced.',
      p_solution               => 'Sales Order Line(s) Ordered Qty does not match the Invoiced Qty.  Verify the invoiced quantity is valid.  For an explanation on how the Invoiced Qty is derived, refer to [728984/KB625731].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_ORD_QTY_NOT_EQUAL_INVOICE_QTY');



