debug('begin add_signature: SALES_ORDER_LINES_NOT_INVOICE_ELIGIBLE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5490',
      p_sig_id                 => 'SALES_ORDER_LINES_NOT_INVOICE_ELIGIBLE',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "Line",
       lin.line_id "Line ID",
       lin.inventory_item_id "Item ID",
       substr(itm.segment1, 1, 80) "Item Name",
       substr(lin.flow_status_code, 1, 22) "Workflow Status",
       nvl(lin.ordered_quantity, 0) "Ordered Qty",
       nvl(lin.invoiced_quantity, 0) "Invoiced Qty",
       nvl(lin.invoice_interface_status_code, ''N'') "Invoice Interface",
       itm.invoiceable_item_flag "Invoiceable Item",
       itm.invoice_enabled_flag "Invoice Enabled"
  FROM oe_order_lines_all lin,
       mtl_system_items itm
 WHERE lin.header_id = ##$$HEADERID$$##
   AND NVL(''##$$LINEID$$##'',0) in (0,lin.line_id, lin.top_model_line_id, lin.ato_line_id, lin.link_to_line_id, lin.service_reference_line_id)
   AND lin.ship_from_org_id = itm.organization_id(+)
   AND LIN.inventory_item_id = itm.inventory_item_id(+)
   AND lin.invoice_interface_status_code = ''NOT_ELIGIBLE''
  AND  lin.order_source_id <> 10
ORDER BY nvl(lin.line_set_id, 0),
         lin.line_number, 
         nvl(lin.shipment_number, -1), 
         nvl(lin.option_number, -1), 
         nvl(lin.service_number, -1)',
      p_title                  => 'Lines Not Eligible to be Invoiced',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order line(s) that are not eligible to be invoiced.',
      p_solution               => 'Reference [467622/KB788994] to determine why the line(s) did not interface to Receivables. ',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_NOT_INVOICE_ELIGIBLE');



debug('begin add_signature: SALES_ORDER_LINES_AWAITING_INVOICE_INTERFACE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14337',
      p_sig_id                 => 'SALES_ORDER_LINES_AWAITING_INVOICE_INTERFACE',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line Number",
       l.line_id,
       l.header_id,
       l.flow_status_code,
       l.org_id,
       dd.delivery_detail_id,
	     da.delivery_id
  FROM wsh_new_deliveries nd,
       wsh_delivery_assignments da,
       wsh_delivery_details dd,
       oe_order_lines_all l,
       oe_order_headers_all h
 WHERE nd.delivery_id (+) = da.delivery_id
   AND nd.status_code = ''CL''
   AND dd.source_code = ''OE''
   AND dd.delivery_detail_id = da.delivery_detail_id
   AND dd.source_line_id (+) = l.line_id
   AND l.open_flag = ''Y''
   AND l.cancelled_flag = ''N''
   AND nvl(l.invoice_interface_status_code, ''N'') = ''MANUAL-PENDING''
   AND l.flow_status_code = ''INVOICE_DELIVERY''
   AND l.header_id = h.header_id
   AND l.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'',0) in (0, l.line_id, l.top_model_line_id, l.ato_line_id, l.link_to_line_id, l.service_reference_line_id)
   AND NOT EXISTS (
       SELECT 1
        FROM ra_customer_trx_lines_all rctl
       WHERE rctl.interface_line_attribute6 = to_char(l.line_id)
         AND rctl.sales_order = h.order_number
         AND rctl.sales_order_line IS NOT NULL
         AND rctl.interface_line_context = ''ORDER ENTRY'' )
   AND NOT EXISTS (
       SELECT 1
        FROM ra_interface_lines_all ril
       WHERE ril.interface_line_attribute6 = to_char(l.line_id)
         AND ril.sales_order = h.order_number
         AND ril.interface_line_context = ''ORDER ENTRY''
         AND ril.sales_order_line IS NOT NULL )
ORDER BY l.line_number,
         nvl(l.shipment_number, - 1),
         nvl(l.option_number, - 1),
         nvl(l.component_number, - 1),
         nvl(l.service_number, - 1)	',
      p_title                  => 'Line Awaiting Invoice Interface Pending Complete Delivery',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'It is not possible to progress sales order lines in INVOICE_DELIVERY status.  The associated line workflow activity ''Awaiting Invoice Interface'' is in ''Pending Complete Delivery'' status. ',
      p_solution               => 'Some lines in delivery has applied Prebilling Implicit Acceptance and now pending at INVOICE_PENDING_ACCEPTANCE status, the delivery will progress until these lines has been accepted.  Check the flow status of the other order lines in the same delivery, if the pending lines shows ''Pending post-billing acceptance'' or ''Pending pre-billing acceptance'', that means user needs to wait for the acceptance expire or manual accept it to let order proceed.

As seen in [1925453/KB790517], to manually accept the pending line, select Fulfillment Acceptance on the line by selecting Actions -> Fulfillment Acceptance.

After acceptance, the application will progress and close the lines in the same delivery.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINES_AWAITING_INVOICE_INTERFACE');



debug('begin add_signature: SALES_ORDER_LINE_FULFILL_NOT_CLOSED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '21829',
      p_sig_id                 => 'SALES_ORDER_LINE_FULFILL_NOT_CLOSED',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(l.line_number, l.shipment_number, l.option_number, l.component_number, l.service_number) "Line Number",
       l.line_id "Line ID",
       l.ordered_quantity "Ordered Qty",
       l.shipped_quantity "Shipped Qty",
       l.fulfilled_quantity "Fulfilled Qty",
       l.invoiced_quantity "Invoiced Qty",
       l.shipping_interfaced_flag "Shipping Interfaced",
       l.fulfilled_flag "Fulfilled Flag",
       l.shippable_flag "Shippable Flag",
       l.flow_status_code "Line Flow Status",
       l.invoice_interface_status_code "Line Invoice Status",
       l.cancelled_flag "Cancelled Flag",
       l.cancelled_quantity "Cancelled Qty",
       l.fulfillment_date "Fulfilled Date"
  FROM oe_order_lines_all l,
       oe_order_headers_all h,
       wf_items wi
 WHERE h.header_id = ##$$HEADERID$$##
   AND l.header_id = ##$$HEADERID$$##
   AND nvl(''##$$LINEID$$##'', 0) IN ( 0, l.line_id, l.top_model_line_id, l.ato_line_id, l.link_to_line_id, l.service_reference_line_id )
   AND l.header_id = h.header_id
   AND wi.item_type (+) = ''OEOL''
   AND to_char(l.line_id) = wi.item_key (+)
   AND l.flow_status_code = ''FULFILLED''
   AND l.open_flag = ''Y''
   AND EXISTS (
  SELECT 1
    FROM ra_customer_trx_lines_all rac
   WHERE rac.interface_line_attribute6 = to_char(l.line_id)
     AND rac.sales_order = to_char(h.order_number)
     AND rac.interface_line_context = ''ORDER ENTRY''
     AND rac.line_type = ''LINE''
     AND rac.sales_order_line IS NOT NULL )
 ORDER BY l.line_number,
         nvl(l.shipment_number, - 1),
         nvl(l.option_number, - 1),
         nvl(l.component_number, - 1),
         nvl(l.service_number, - 1)		 ',
      p_title                  => 'Sales Order Line Fulfilled not Closed',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Sales Order lines are stuck in Fulfilled Status not closed status. Invoice also generated but the order line never progresses to closed status.',
      p_solution               => '<ul>
<li>Log a Service Request with Oracle Order Management</li>
<li>For more information regarding this issue, review [2697704/KB721783] for instructions and details.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_FULFILL_NOT_CLOSED');



debug('begin add_signature: EBS_MFG_OM_ONT_ONTONESO_SALES_ORDER_INVOICE_DETAILS_NOT_VISIBLE');
