      p_sig_sql                => 'SELECT
    NULL "SO Line #",
       NULL"Line Type",
       NULL "Line ID / Charge ID",      
       NULL "Source Code",
       rct.interface_header_attribute1 "Order No",
	   rct.interface_header_attribute2 "Header Order Type",
       NULL "Line Order Type",
       NULL "Delivery Name",
       NULL "WayBill",
       NULL "# Interfaced",
       NULL "Bill of Lading",
       NULL "Item Number",
       NULL "Warehouse ID",
       NULL "Price Adjustment ID",
       NULL "Shipment No",
       NULL "Option No",
       NULL "Service No",
        NULL "Sales Order No",
       NULL"Order Line",
       rct.created_by "Created By",
       to_char(rct.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Creation Date",
       rct.last_updated_by "Last Updated By",
       to_char(rct.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Last Update Date"      
FROM
    ra_customer_trx_all rct,
    oe_order_headers_all ooh    
WHERE
    length(rct.interface_header_attribute2) <> length(ltrim(rtrim(rct.interface_header_attribute2)))
    and rct.interface_header_attribute1=''##$$ORDERNO$$##''
    and rct.interface_header_attribute1=ooh.order_number
     and ooh.header_id=##$$HEADERID$$##
       --and rctl.interface_line_context = fnd_profile.value(''ONT_SOURCE_CODE'')
UNION ALL
 SELECT
    om_order_analyzer_pkg.line_shipment_option(lin.line_number, lin.shipment_number, lin.option_number, lin.component_number, lin.service_number) "SO Line #",
       rctl.line_type "Line Type",
      rctl.interface_line_attribute6 "Line ID / Charge ID",      
       rctl.interface_line_context "Source Code",
       rctl.interface_line_attribute1 "Order No",
	   NULL "Header Order Type",
       rctl.interface_line_attribute2 "Line Order Type",
       rctl.interface_line_attribute3 "Delivery Name",
       rctl.interface_line_attribute4 "WayBill",
       rctl.interface_line_attribute5 "# Interfaced",
       rctl.interface_line_attribute8 "Bill of Lading",
       rctl.interface_line_attribute9 "Item Number",
       rctl.interface_line_attribute10 "Warehouse ID",
       rctl.interface_line_attribute11 "Price Adjustment ID",
       rctl.interface_line_attribute12 "Shipment No",
       rctl.interface_line_attribute13 "Option No",
       rctl.interface_line_attribute14 "Service No",
       rctl.sales_order "Sales Order No",
       rctl.sales_order_line "Order Line",
       rctl.created_by "Created By",
       to_char(rctl.creation_date, ''DD-MON-RR_HH24:MI:SS'') "Creation Date",
       rctl.last_updated_by "Last Updated By",
       to_char(rctl.last_update_date, ''DD-MON-RR_HH24:MI:SS'') "Last Update Date"      
FROM
    ra_customer_trx_lines_all rctl, 
    oe_order_headers_all ooh,
    oe_order_lines_all lin   
WHERE
    length(rctl.interface_line_attribute2) <> length(ltrim(rtrim(rctl.interface_line_attribute2)))
    and interface_line_attribute1=''##$$ORDERNO$$##''
    and interface_line_attribute6= nvl(''##$$LINEID$$##'',interface_line_attribute6)
    and interface_line_attribute1=ooh.order_number
    and ooh.header_id=lin.header_id    
    and ooh.header_id=##$$HEADERID$$##
    and interface_line_attribute6=lin.line_id
    AND rctl.line_type = ''LINE''
    and rctl.interface_line_context = fnd_profile.value(''ONT_SOURCE_CODE'')
	and ooh.org_id = lin.org_id	',
      p_title                  => 'Sales Order Invoice Details Not Visible',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice Details Are Not Shown In The Invoice Tab In Additional Order Information Form',
