debug('begin add_signature: OM_DEBUG_PROFILES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '15473',
      p_sig_id                 => 'OM_DEBUG_PROFILES',
      p_sig_sql                => 'SELECT fpot.user_profile_option_name "Profile Name",
       decode(fpo.profile_option_name, 
              ''QP_DEBUG'',        (SELECT meaning FROM qp_lookups  WHERE lookup_type = ''QP_REQUEST_VIEWER_OPTIONS'' AND lookup_code = fpov.profile_option_value),
              ''WSH_DEBUG_MODE'',  (SELECT meaning FROM wsh_lookups WHERE lookup_type = ''WSH_DEBUG_ENABLED'' AND lookup_code = fpov.profile_option_value),
              ''WSH_PROFILER_ENABLED'', (SELECT meaning FROM wsh_lookups WHERE lookup_type = ''WSH_DEBUG_ENABLED'' AND lookup_code = fpov.profile_option_value),
              ''INV_DEBUG_TRACE'', (SELECT meaning FROM mfg_lookups WHERE lookup_type = ''SYS_YES_NO'' AND lookup_code = fpov.profile_option_value),
              fpov.profile_option_value) "Value",
       decode(fpov.level_id, 
               10001, ''Site'', 
               10002, ''Application'', 
               10003, ''Responsibility'', 
               10004, ''User'') "Set at Level", 
       decode(fpov.level_id, 
               10001, '''', 
               10002, (select application_short_name from fnd_application where application_id=fpov.level_value), 
               10003, (select responsibility_name from fnd_responsibility_vl where responsibility_id=fpov.level_value), 
               10004, (select user_name from fnd_user where user_id=fpov.level_value)) "Level Value" 
FROM   fnd_profile_option_values fpov,
       fnd_profile_options fpo,
       fnd_profile_options_tl fpot
WHERE fpov.profile_option_id = fpo.profile_option_id 
  AND fpo.profile_option_name = fpot.profile_option_name 
  AND fpot.language = ''US''
  AND fpo.profile_option_name IN (
        ''OE_DEBUG_LOG_DIRECTORY'', ''ONT_DEBUG_LEVEL'', 
        ''QP_DEBUG'',
        ''WSH_DEBUG_FILE_PREFIX'', ''WSH_DEBUG_LEVEL'', ''WSH_DEBUG_LOG_DIRECTORY'', ''WSH_DEBUG_MODE'', ''WSH_DEBUG_MODULE'',
        ''INV_DEBUG_FILE'', ''INV_DEBUG_LEVEL'', ''INV_DEBUG_TRACE'' )
ORDER BY fpo.application_id,
         fpo.profile_option_name, 
         fpov.level_id,
         fpov.level_value',
      p_title                  => 'Order Management Debug Profile Options Values',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no order management debug profile options values.',
      p_solution               => 'You may review [121054/KB627730] to generate a debug file in OM for assistance.',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: OM_DEBUG_PROFILES');



