debug('begin add_signature: SALES_ORDER_WSH_ACCOUNTING_PERIODS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '1561',
      p_sig_id                 => 'SALES_ORDER_WSH_ACCOUNTING_PERIODS',
      p_sig_sql                => 'SELECT DISTINCT * FROM
(
SELECT mp.organization_id      "Org ID",
       mp.organization_code    "Org",
       oac.period_name         "Period Name",
       oac.open_flag           "Open",
       oac.period_start_date   "Period Start Date",
       oac.period_close_date   "Period Close Date",
       oac.schedule_close_date "Period Schedule Close Date"
FROM mtl_parameters           mp,
     org_acct_periods         oac,
     wsh_delivery_details     det,
     wsh_delivery_legs        leg,
     wsh_trip_stops           stp,
     wsh_delivery_assignments asg,
     wsh_trips                trp
WHERE asg.delivery_detail_id = det.delivery_detail_id
      AND stp.stop_id (+) = leg.pick_up_stop_id
      AND stp.trip_id = trp.trip_id (+)
      AND leg.delivery_id (+) = asg.delivery_id
      AND det.source_code = ''OE''
      AND mp.organization_id = oac.organization_id
      AND mp.organization_id = det.organization_id
      AND trunc(stp.planned_departure_date) BETWEEN oac.period_start_date AND nvl(oac.period_close_date, oac.schedule_close_date)
      AND det.source_header_id = ##$$HEADERID$$##
UNION ALL
SELECT mp.organization_id      "Org ID",
       mp.organization_code    "Org",
       oac.period_name         "Period Name",
       oac.open_flag           "Open",
       oac.period_start_date   "Period Start Date",
       oac.period_close_date   "Period Close Date",
       oac.schedule_close_date "Period Schedule Close Date"
FROM mtl_parameters       mp,
     org_acct_periods     oac,
     wsh_delivery_details det,
     oe_order_lines_all   lin
WHERE det.source_line_id = lin.line_id
      AND det.source_code = ''OE''
      AND mp.organization_id = oac.organization_id
      AND mp.organization_id = det.organization_id
      AND trunc(lin.schedule_ship_date) BETWEEN oac.period_start_date AND nvl(oac.period_close_date, oac.schedule_close_date)
      AND det.source_header_id = ##$$HEADERID$$##
)
ORDER BY 1,5',
      p_title                  => 'Accounting Periods',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No open Accounting Periods found for this sales order.',
      p_solution               => '<p>Accounting Periods for this sales order have not been opened if scheduling has completed.  If scheduling has not yet completed, Schedule Ship Date will be NULL and not be able to verify appropriate periods.  </p>
<p>Open the appropriate period(s) by going to:</p>
<ul>
<li>Inventory &gt; Accounting Close Cycle &gt; Inventory Accounting Period</li>
<li>Select appropriate warehouse</li>
<li>Select Change Status</li>
</ul>
<p>Refer to [746268/KB627378] for additional details.</p>',
      p_success_msg            => 'Accounting Periods are open for this sales order.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '15'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_WSH_ACCOUNTING_PERIODS');



debug('begin add_signature: SALES_ORDER_LINE_WF_ACTIVITY_CHILD');
   l_info('##MASK##ASSIGNED_USER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7386',
      p_sig_id                 => 'SALES_ORDER_LINE_WF_ACTIVITY_CHILD',
      p_sig_sql                => 'SELECT ap.display_name "Process Name",
       ac.display_name "Activity Name",
       l_as.meaning "Status",
       wf_core.activity_result(ac.result_type, ias.activity_result_code) "Result",
       pa.process_name "Process Code",
       pa.activity_name "Activity Code",
       ias.activity_status "Status Code",
       ias.activity_result_code "Result Code",
       to_char(ias.begin_date, ''DD-MON-RR HH24:MI:SS'') "Begin Date",
       to_char(ias.end_date, ''DD-MON-RR HH24:MI:SS'') "End Date",
       to_char(ias.due_date, ''DD-MON-RR HH24:MI:SS'') "Due Date",
       ias.assigned_user "Assigned User",
       ias.notification_id "Notification ID",
       ias.error_name "Error Name",
       ias.error_message "Error Message",
       ias.begin_date,
       ias.execution_time
  FROM wf_item_activity_statuses ias,
       wf_process_activities pa,
       wf_activities_vl ac,
       wf_activities_vl ap,
       wf_items i,
       wf_lookups l_as
 WHERE ias.item_type = ''OEOL''
   AND ias.item_key = ''##$$FK1$$##''
   AND ias.process_activity = pa.instance_id
   AND pa.activity_name = ac.name
   AND pa.activity_item_type = ac.item_type
   AND pa.process_name = ap.name
   AND pa.process_item_type = ap.item_type
   AND pa.process_version = ap.version
   AND l_as.lookup_type = ''WFENG_STATUS''
   AND l_as.lookup_code = ias.activity_status
   AND i.item_type = ias.item_type
   AND i.item_key = ias.item_key
   AND i.begin_date >= ac.begin_date
   AND i.begin_date < nvl(ac.end_date, i.begin_date + 1)
UNION ALL
SELECT * FROM (
  SELECT * FROM (
    SELECT ap.display_name "Process Name",
           ac.display_name "Activity Name",
           l_as.meaning "Status",
           wf_core.activity_result(ac.result_type, ias.activity_result_code) "Result",
           pa.process_name "Process Code",
           pa.activity_name "Activity Code",
           ias.activity_status "Status Code",
           ias.activity_result_code "Result Code",
           to_char(ias.begin_date, ''DD-MON-RR HH24:MI:SS'') "Begin Date",
           to_char(ias.end_date, ''DD-MON-RR HH24:MI:SS'') "End Date",
           to_char(ias.due_date, ''DD-MON-RR HH24:MI:SS'') "Due Date",
           ias.assigned_user "Assigned User",
           ias.notification_id "Notification ID",
           ias.error_name "Error Name",
           ias.error_message "Error Message",
           ias.begin_date,
           ias.execution_time
      FROM wf_item_activity_statuses_h ias,
           wf_process_activities pa,
           wf_activities_vl ac,
           wf_activities_vl ap,
           wf_items i,
           wf_lookups l_as
     WHERE ias.item_type = ''OEOL''
       AND ias.item_key = ''##$$FK1$$##''
       AND ias.process_activity = pa.instance_id
       AND pa.activity_name = ac.name
       AND pa.activity_item_type = ac.item_type
       AND pa.process_name = ap.name
       AND pa.process_item_type = ap.item_type
       AND pa.process_version = ap.version
       AND l_as.lookup_type = ''WFENG_STATUS''
       AND l_as.lookup_code = ias.activity_status
       AND i.item_type = ias.item_type
       AND i.item_key = ias.item_key
       AND i.begin_date >= ac.begin_date
       AND i.begin_date < nvl(ac.end_date, i.begin_date + 1)
     ORDER BY ias.begin_date DESC,
              execution_time DESC)
  WHERE ROWNUM <= 6 )
ORDER BY 16, 17',
      p_title                  => 'Line ID: ##$$FK1$$## : Sales Order Line Workflow Activity ',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no sales order line workflow activity.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '17'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_WF_ACTIVITY_CHILD');



