debug('begin add_signature: SALES_ORDER_LINE_WF_STATUS_ERRORS_PARENT');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22448',
      p_sig_id                 => 'SALES_ORDER_LINE_WF_STATUS_ERRORS_PARENT',
      p_sig_sql                => 'SELECT om_order_analyzer_pkg.line_shipment_option(lin.line_number,lin.shipment_number,lin.option_number, lin.component_number, lin.service_number) "Line Number",
       lin.line_id                         "Line ID",
       lin.flow_status_code "Workflow Status",
       lin.line_id                         "##$$FK1$$##"
FROM   oe_order_lines_all lin
WHERE  lin.header_id = ##$$HEADERID$$##
       and NVL(''##$$LINEID$$##'',0) in (0,
                                       LIN.LINE_ID,
                                       LIN.TOP_MODEL_LINE_ID,
                                       LIN.ATO_LINE_ID,
                                       LIN.LINK_TO_LINE_ID,
                                       LIN.SERVICE_REFERENCE_LINE_ID)
       AND ( EXISTS (SELECT ''x''
                     FROM   wf_item_activity_statuses ias,
                            wf_process_activities pa,
                            wf_items i
                     WHERE  ias.item_type = ''OEOL''
                            AND ias.item_key = to_char(lin.line_id)
                            AND ias.process_activity = pa.instance_id
                            AND ias.activity_status = ''ERROR''
                            AND i.item_type = ias.item_type
                            AND i.item_key = ias.item_key)
