      AND pa.process_name = ap.name
      AND pa.process_item_type = ap.item_type
      AND pa.process_version = ap.version
      AND i.item_type in (''OMERROR'', ''WFERROR'')
      AND i.parent_item_type = ''OEOL''
      AND i.parent_item_key = ''##$$FK1$$##''
      AND i.begin_date >= ac.begin_date
      AND i.begin_date < nvl(ac.end_date, i.begin_date + 1) 	  
UNION ALL
SELECT * FROM (
SELECT * FROM (
SELECT i.item_type              "Item Type",
       i.item_key               "Item Key",
 	   ap.display_name          "Process Name",
       ac.display_name          "Activity Name",
       ias.activity_status      "Activity Status",
       ias.activity_result_code "Activity Result",
       pa.process_name          "Process",
       pa.activity_name         "Activity",
       ias.error_name           "Error Name",
       ias.error_message        "Error Message",
	   ias.error_stack          "Error Stack",
       ias.begin_date,
       ias.execution_time
FROM wf_item_activity_statuses_h ias,
     wf_process_activities     pa,
     wf_activities_vl          ac,
     wf_activities_vl          ap,
     wf_items                  i
WHERE ias.item_type = i.item_type
      AND ias.item_key = i.item_key
      AND ias.process_activity = pa.instance_id
      AND pa.activity_name = ac.name
      AND pa.activity_item_type = ac.item_type
      AND pa.process_name = ap.name
      AND pa.process_item_type = ap.item_type
      AND pa.process_version = ap.version
      AND i.item_type in (''OMERROR'', ''WFERROR'')
      AND i.parent_item_type = ''OEOL''
      AND i.parent_item_key = ''##$$FK1$$##''
      AND i.begin_date >= ac.begin_date
      AND i.begin_date < nvl(ac.end_date, i.begin_date + 1) 	  	 
ORDER BY ias.begin_date desc,
         execution_time desc ) 
where rownum<=6) 
ORDER BY 12, 13',
      p_title                  => 'Line ID: ##$$FK1$$## : Sales Order Line Workflow Error',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'There is no workflow error found on this order line',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: SALES_ORDER_LINE_WF_STATUS_ERROR_PROCESS');



