---------------------------------
-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_order_number                 IN NUMBER      DEFAULT NULL
           ,p_header_id                    IN NUMBER      DEFAULT NULL
           ,p_line_id                      IN NUMBER      DEFAULT NULL
           ,p_include_apps_check           IN VARCHAR2    DEFAULT 'N'
           ,p_print_wf                     IN VARCHAR2    DEFAULT 'Y'
           ,p_print_purch                  IN VARCHAR2    DEFAULT 'Y'
           ,p_print_mfg                    IN VARCHAR2    DEFAULT 'Y'
           ,p_print_inv                    IN VARCHAR2    DEFAULT 'Y'
           ,p_print_ar                     IN VARCHAR2    DEFAULT 'Y'
           ,p_max_output_rows              IN NUMBER      DEFAULT 200
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';

  IF (p_order_number IS NOT NULL) THEN
    g_params_string := g_params_string || to_char(p_order_number) || '_';
  END IF;
  IF (p_header_id IS NOT NULL) THEN
    g_params_string := g_params_string || to_char(p_header_id) || '_';
  END IF;


  l_step := '10';
  initialize_files;

  analyzer_title := 'Sales Order Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_order_number                 => p_order_number
    ,p_header_id                    => p_header_id
    ,p_line_id                      => p_line_id
    ,p_include_apps_check           => upper(p_include_apps_check)
    ,p_print_wf                     => upper(p_print_wf)
    ,p_print_purch                  => upper(p_print_purch)
    ,p_print_mfg                    => upper(p_print_mfg)
    ,p_print_inv                    => upper(p_print_inv)
    ,p_print_ar                     => upper(p_print_ar)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: SO_Header');
start_section('Header', 'SO_Header');
   set_item_result(run_stored_sig('SALES_ORDER_HEADER_INFORMATION_DISPLAY'));
   set_item_result(run_stored_sig('SALES_ORDER_ORDER_TYPE'));
   IF p_print_wf = 'Y' THEN
      set_item_result(run_stored_sig('SALES_ORDER_HEADER_WF_ACTIVITY'));
      set_item_result(run_stored_sig('SALES_ORDER_WF_ORDER_LEVEL_ERRORS'));
      set_item_result(run_stored_sig('SALES_ORDER_WF_ACTIVITY_ORDER_ERROR'));
      set_item_result(run_stored_sig('SALES_ORDER_WF_NOTIFICATIONS'));
      set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_AME_WF_ACTIVITY'));
      set_item_result(run_stored_sig('SALES_ORDER_HEADER_NO_WORKFLOW'));
      set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_HEADER_WF_LOOPING'));
   END IF;
   set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_CUSTOMER'));
   set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_CUST_ADDRESS'));
   set_item_result(run_stored_sig('SALES_ORDER_GENERIC_HOLD_DISPLAY'));
   set_item_result(run_stored_sig('SALES_ORDER_HEADER_PROCESSING_MSGS'));
   set_item_result(run_stored_sig('SALES_ORDER_SALES_CREDITS'));
   set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_HEADER_ACKS'));
   set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_BSA_HEADER'));
   set_item_result(run_stored_sig('EBS_MFG_OM_ONT_ONTONESO_PAYMENT'));
   set_item_result(run_stored_sig('SALES_ORDER_HEADER_OPEN_WITH_CLOSED_LINES'));
